INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-94bg9', '94bg9', 'La nación expuesta. Cultura visual y procesos de formación de la nación en América Latina', NULL, '["Sven Schuster"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra reúne once ensayos originales acerca de la función de las imágenes en los procesos de formación de la nación en América Latina, incluyendo contribuciones de especialistas de Europa, Estados Unidos, América Latina e Israel. Inspirados por el reciente “giro pictorial” en las ciencias sociales, estos textos no sólo transcienden los límites nacionales, sino también los disciplinares, combinando acercamientos de la historia, la literatura, los estudios culturales y las ciencias políticas. En general, los autores indagan sobre la función que han desempeñado las imágenes de lo propio y de lo ajeno –como parte de discursos nacionalistas– dentro de exposiciones y museos, en la prensa, en el arte, en la fotografía, en el cine, así como en forma de monumentos y estatuas, es decir en su función de “imágenes públicas”.', '["visual culture","nation formation","nationalism","public image","museums and exhibitions","photography","cinema","press","Latin America"]', '10.7476/9789587385243', '9789587385243', 'https://books.scielo.org/id/94bg9', 'https://books.scielo.org/id/94bg9/pdf/schuster-9789587385243.pdf', NULL, 'https://books.scielo.org/id/94bg9/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-94cmn', '94cmn', 'Brazilian ectoparasite fauna of veterinary importance', 'volume 1. Mite fauna of veterinary importance: Acariformes', '["Barros-Battesti, Darci Moraes","Machado, Rosangela Zacarias","André, Marcos Rogério"]', 'Colégio Brasileiro de Parasitologia Veterinária (CBPV)', 'Brasil', 'SciELO Books', 'books', 2021, NULL, 'en', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', NULL, 'The work BRAZILIAN ECTOPARASITE FAUNA OF VETERINARY IMPORTANCE consists of three volumes. This volume deals with endo and ectoparasitic mite fauna of domestic and wild animals that belongs in the superorder ACARIFORMES (Trombidiformes and Sarcoptiformes). This book forms almost complete documentation of the ectoparasites of domestic and wild animals, with images and up-to-date lists of the ectoparasite species of veterinary importance that occur in Brazil, but also including the literature records of mites from many countries.', '[]', '10.7476/9786599219177', '9786599219160', 'https://books.scielo.org/id/94cmn', NULL, NULL, 'https://books.scielo.org/id/94cmn/cover/cover_thumbnail.jpeg', 315, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-94xt2', '94xt2', 'Misiones, Estado y pueblos indígenas: transformaciones de una relación histórica', NULL, '["José Enrique Juncosa Blasco","Luis Alvarez","Verónica Loor Salazar","Angélica Almeida","Margarita Alvarado","Juan Bottasso","Miguel Ángel Cabodevilla","Ignacio Helmke Miquel","Juan Illicachi Guzñay","Fernando Pairicán Padilla","Galo Sarmiento","SUESS Paulo","Ángel Torres-Toukoumidis"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra contribuye a comprender la compleja relación entre las iglesias y el Estado respecto a los pueblos indígenas. La primera parte recoge contribuciones de misioneros, teólogos, antropólogos e historiadores. Sus artículos exponen casos de la Amazonía ecuatoriana y peruana relacionados con las misiones capuchinas, salesianas y franciscanas. Incluye también un estudio sobre la relación de la misión franciscana con los mapuche en su doble rol de agente gubernamental y evangelizadora y un estudio de caso en Chimborazo, así como una revisión crítica de los documentos en torno al Sínodo para la Amazonía. La segunda parte transcribe tres documentos relacionados con los hechos acaecidos en las Escuelas Residenciales Indígenas de Canadá que conmocionaron la opinión pública. Se trata de un fragmento del Informe de la Comisión de la Verdad y Reconciliación de Canadá (2015); la Declaración de disculpa de los obispos católicos de Canadá a los indígenas de esta tierra; y, finalmente, la Carta abierta del Equipo de Pastoral Indígena (EDIPA) de Neuquén (Argentina) que se hace eco de los sucesos de Canadá desde la perspectiva de solidaridad, sanación y reparación.', '["indigenous peoples","church-state relations","Christian missions","Catholic missions","Capuchin missions","Salesian missions","Franciscan missions","Mapuche","Truth and Reconciliation Commission of Canada","Ecuadorian Amazon","Peruvian Amazon","Chimborazo"]', '10.7476/9789978108239', '9789978108239', 'https://books.scielo.org/id/94xt2', 'https://books.scielo.org/id/94xt2/pdf/enrique-9789978108239pdf', NULL, 'https://books.scielo.org/id/94xt2/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-952wd', '952wd', 'A Bahia já deu régua e compasso: medicina legal, raça e criminalidade na Bahia (1890-1940)', NULL, '["Iraneidson Santos Costa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro nos dá régua e compasso para conhecer as entranhas do pensamento e das práticas racistas a que se dedicaram as instituições acadêmicas e jurídico-policiais na Bahia nas primeiras décadas da República. Ao repassar sem rebuço esse ponto crucial do nosso passado, o livro ajuda a entender por que a criminalização sistemática do negro é, ainda hoje, um dado angustiante na vida da maior parte da população brasileira.', '["forensic medicine","racism","criminalization of Black people","racial thought","police institutions","academic institutions","Bahia","early Brazilian Republic","history of medicine","racial discrimination in criminal justice"]', '10.7476/9786556305011', '9786556305011', 'https://books.scielo.org/id/952wd', 'https://books.scielo.org/id/952wd/pdf/costa-9786556305011.pdf', NULL, 'https://books.scielo.org/id/952wd/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-955tc', '955tc', 'La administración de empresas: una perspectiva desde el profesional mateista hacia el futuro', 'una perspectiva desde el profesional mateista hacia el futuro', '["Julian Cortés Cabrera"]', 'Editorial Fundación Universitaria San Mateo', 'Colombia', 'SciELO Books', 'books', 2019, '2019-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Con esta obra se pretende la consolidación del tejido social en el marco del interés por comprender las empresas actuales, y la importancia otorgada al talento humano como eje imprescindible para el diseño de estrategias que conlleven a la innovación, competitividad y sostenibilidad en el mercado. Entonces, llama la atención discernir los elementos propios de la administración, en tanto, contribuyen con el mejoramiento del medio ambiente, la sociedad y el Estado, pues las compañías logran ser consideradas como las pioneras en la creación de políticas públicas que permitan la consolidación de vínculos comunitarios entre los diferentes actores de las cadenas de valor, logrando con ello, oportunidades de empleabilidad y rentabilidad en el país.', '["business management","human talent","business strategy","innovation","competitiveness","sustainability","corporate social responsibility","public policy","value chain","employability","profitability"]', '10.7476/9786289572506', '9789585690073', 'https://books.scielo.org/id/955tc', 'https://books.scielo.org/id/955tc/pdf/cortes-9786289572506.pdf', NULL, 'https://books.scielo.org/id/955tc/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-95n6t', '95n6t', 'Trajetórias interrompidas: perdas gestacionais, luto e reparação', NULL, '["Vívian Volkmer Pontes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A partir de uma perspectiva do construtivismo semiótico-cultural em psicologia, a obra se debruça sobre o tema da perda gestacional involuntária e como essa ocorrência implica em descontinuidade do desenvolvimento do self, desafiando os entendimentos e expectativas que haviam sido construídos acerca de si mesmo e do mundo. O livro traz em seus nove capítulos os resultados do estudo realizado pela autora, que trata, essencialmente, sobre como o self constrói continuidade através de rupturas sucessivas ao longo da trajetória reprodutiva.', '["miscarriage","grief","self-continuity","self-development","reproductive trajectories"]', '10.7476/9788523220099', '9788523220099', 'https://books.scielo.org/id/95n6t', 'https://books.scielo.org/id/95n6t/pdf/pontes-9788523220099.pdf', NULL, 'https://books.scielo.org/id/95n6t/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-95w3p', '95w3p', 'A hierarquização da ciência: estudo sobre a construção da irrelevância científica', 'estudo sobre a construção da irrelevância científica', '["Fabrício Monteiro Neves"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Quem decide o que é relevante na ciência? Por que algumas pesquisas, instituições e pesquisadores ganham reconhecimento, enquanto outros permanecem à margem? Em A Hierarquização da Ciência: estudo sobre a construção da irrelevância científica, Fabrício Monteiro Neves investiga os mecanismos que produzem e reproduzem essas desigualdades. A obra convida o leitor a repensar como se constroem prestígio, reconhecimento e invisibilidade no mundo científico e aponta caminhos para uma ciência mais plural e democrática.', '["scientific hierarchy","scientific relevance","scientific prestige","research institutions","pluralism in science","democratization of science"]', '10.7476/9786557083086', '9786557082430', 'https://books.scielo.org/id/95w3p', NULL, NULL, 'https://books.scielo.org/id/95w3p/cover/cover_thumbnail.jpeg', 162, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-963vf', '963vf', 'Transtorno de déficit de atenção/ hiperatividade: diagnóstico da prática pedagógic', NULL, '["Rosana Aparecida Albuquerque Bonadio","Nerli Nonato Ribeiro Mori"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Pesquisar sobre os problemas de atenção no contexto escolar lança-nos a um grande desafio: compreender como as crianças e adolescentes estão sendo diagnósticados com Transtorno de Déficit e Atenção e Hiperatividade - TDAH; conhecer os encaminhamentos e as intervenções realizadas por médicos, professores psicólogos, fonoaudiólogos e demais especialistas fora e intramuros da escola.', '["attention deficit hyperactivity disorder","ADHD diagnosis","school-based diagnosis","adolescents","referral pathways","teaching practice","school psychologists","speech-language pathologists","specialist physicians"]', '10.7476/9788576286578', '9788576286578', 'https://books.scielo.org/id/963vf', 'https://books.scielo.org/id/963vf/pdf/bonadio-9788576286578.pdf', NULL, 'https://books.scielo.org/id/963vf/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-965tk', '965tk', 'Recomeçar: família, filhos e desafios', NULL, '["Nayara Hakime Dutra Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O tema deste livro é a organização das famílias após a separação conjugal, um momento marcado por intensas mudanças em sua configuração. A autora discute as possibilidades e desafios vivenciados no universo familiar e sua relação com a sociedade. A expressão das dificuldades é manifestada nas questões relativas à saúde, à habitação, aos relacionamentos, à alimentação, ao vestuário, enfim, às necessidades básicas de sobrevivência. A investigação foi realizada a partir de documentação obtida no Serviço Social na Unidade Auxiliar Centro Jurídico Social da Unesp campus de Franca-SP', '["family reorganization","divorce","children","family and society","basic needs","health","housing","relationships","food","clothing","social work"]', '10.7476/9788579830365', '9788579830365', 'https://books.scielo.org/id/965tk', 'https://books.scielo.org/id/965tk/pdf/oliveira-9788579830365.pdf', NULL, 'https://books.scielo.org/id/965tk/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-96gpq', '96gpq', 'Família, escola e desempenho escolar', NULL, '["Nogueira, Maria Alice","Resende, Tânia de Freitas","Nogueira, Claudio Marques Martins"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro constitui-se numa sólida contribuição para a sociologia da educação no Brasil. Medir a influência da família sobre o desempenho escolar das crianças, utilizando, de modo inovador, modelos quantitativos, consistiu apenas na primeira etapa do trabalho aqui apresentado, o qual se destaca no cenário das pesquisas nacionais sobre o tema das relações família-escola em vários pontos. Além das dimensões e diversificação da amostra, não se conhecem, no Brasil, estudos que tenham relacionado as práticas e as dinâmicas internas das famílias à proficiência do aluno obtida em testes padronizados. Tal etapa foi seguida da busca dos mecanismos finos por meio dos quais pode ser mensurado o impacto da vida doméstica no aprendizado dos estudantes. Isso exigia uma investigação qualitativa como a realizada no segundo projeto. Os diferentes capítulos de ambas as partes do livro apresentam conclusões que devem influenciar o desenho de instrumentos de pesquisas futuras, mas principalmente lançar um olhar mais detalhado para o muito que uma ação junto com as famílias pode fazer a fim de melhorar nossos resultados educacionais. Nesse sentido, os textos aqui reunidos trazem informações inéditas e importantes para subsidiaras escolhas que precisam ser feitas para a definição de políticas públicas de educação.', '["school-family relations","academic performance","family influence on learning","family dynamics","standardized test scores","education policy"]', '10.7476/9786558581567', '9786558581109', 'https://books.scielo.org/id/96gpq', NULL, NULL, 'https://books.scielo.org/id/96gpq/cover/cover_thumbnail.jpeg', 248, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-96spq', '96spq', 'Clima escolar: perspectivas e possibilidades de análise', NULL, '["João Marcos Vitorino dos Santos","Joyce Mary Adam"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro propõe a discussão sistemática sobre o clima escolar, levando em consideração as dimensões apresentadas como forma de levantar indicadores que favorecem os processos de convivência e trocas entre pares, assim como a identificação das questões relacionais que precisam ser melhoradas para que a comunidade escolar esteja mais integrada com o projeto de escola da instituição. Os autores justificam a necessidade de se articular nas escolas uma cultura de avaliação que extrapole a abstração de dados censitários sobre a aprendizagem, abrindo possibilidades para se pensar a importância do diagnóstico preciso da qualidade das relações entre os sujeitos escolares, como mecanismo de prevenção às situações de disruptividade. Assim, pensar na melhoria das condições que afetam a convivência, e que por vezes, passam despercebidos pelos sujeitos escolares, é fator relevante, e fomenta a possibilidade de as instituições escolares criarem possibilidades de ação frente aos desafios evidenciados por meio da análise de seu clima escolar.', '["school climate","school coexistence","peer relationships","school community","school projects","relationship quality"]', '10.7476/9786559542512', '9786559542512', 'https://books.scielo.org/id/96spq', 'https://books.scielo.org/id/96spq/pdf/santos-9786559542512.pdf', NULL, 'https://books.scielo.org/id/96spq/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-96v9g', '96v9g', 'Capoeira, identidade e gênero: ensaios sobre a história social da capoeira no Brasil', NULL, '["Josivaldo Pires de Oliveira","Luiz Augusto Pinheiro Leal"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A capoeira deixou os pés de página dos compêndios mais importantes da história nacional para adquirir vida própria, tornando-se ela mesma tema de volumosos trabalhos, que desvelam planos e horizontes antes absolutamente desconhecidos da nossa historiografia. Este trabalho faz parte desta nova safra.', '["capoeira","identity","gender","Afro-Brazilian culture","Brazilian history"]', '10.7476/9788523217266', '9788523217266', 'https://books.scielo.org/id/96v9g', 'https://books.scielo.org/id/96v9g/pdf/oliveira-9788523217266.pdf', NULL, 'https://books.scielo.org/id/96v9g/cover/cover_thumbnail.jpeg', NULL, 46, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-96y5f', '96y5f', 'La inclusión de las TIC en la educación de personas con discapacidad: relatos de experiencias', NULL, '["Miriam Mariana Gallegos Navas"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Las TIC constituyen un punto de partida y en muchas ocasiones supondrán la diferencia entre la exclusión y la inclusión. Desde esta perspectiva, si no utilizamos tecnologías inclusivas en las aulas, es probable que estemos contribuyendo a dicha exclusión” (Soto, 2013, p. 14). El presente texto ofrece a la comunidad educativa varias experiencias relacionadas al uso de las tecnologías de información y comunicación como recurso de apoyo en la educación de estudiantes con discapacidad, experiencias que surgen como, resultado del proyecto de investigación denominado “Estudio de la Aplicabilidad del Enfoque Ecológico Funcional en la Educación de Estudiantes con Discapacidad en el Ecuador”, ejecutado por el Grupo de Investigación de Educación Inclusiva (GEI) de la Universidad Politécnica Salesiana del Ecuador entre enero de 2016 y junio de 2017. El mencionado proyecto se desarrolló en el marco del curso de formación continua de “Diseño Curricular desde una perspectiva ecológica funcional”, auspiciado por CBM Internacional en el que participaron docentes y directivos de instituciones educativas de todo el país que brindaron su aporte al proyecto como informantes directos y recogiendo información que permitió el análisis del estado de la situación educativa de los estudiantes con discapacidad en el país.', '["information and communication technologies","inclusive education","students with disabilities","assistive technology","curricular design","teacher experiences","Ecuador"]', '10.7476/9789978104958', '9789978104958', 'https://books.scielo.org/id/96y5f', 'https://books.scielo.org/id/96y5f/pdf/gallegos-9789978104958.pdf', NULL, 'https://books.scielo.org/id/96y5f/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-97dxr', '97dxr', 'Itinerários da loucura em território Dogon', NULL, '["Denise Dias Barros"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Neste livro, Denise Dias Barros apresenta inúmeros aspectos da problemática da loucura e métodos de tratamento tal como se apresenta entre os Dogon, sociedade negro-africana da África do Oeste.O texto não contém complexidades forçadas: sua densidade e concreção aparecem como qualidades naturais do discurso, que é sólido e preciso, chegando ao que deseja expor por caminhos que muitas vezes fogem da convencionalidade dita científica para fazer aflorar fatores insuspeitados.Diria que, além de seu interesse para certas áreas médicas -que travarão contato com realidades desconcertantes para elas -, trata-se de um trabalho do campo da sociologia, em formulação diferencial, porque estabelece relações entre fenômenos de uma determinada sociedade tendo por base ações e relações sociais ancoradas em valores históricos extremamente precisos e internalizados.Assim, a loucura aparece como fato indissoluvelmente ligado às práticas sociais, ocorrendo certamente a individualização dos problemas, mas com relacionamento estreito com a questão do equilíbrio e desequilíbrio, da ordem e da desordem, sempre ao nível interdependente da pessoa e da sociedade.Porém, não fica o trabalho relegado apenas a estas instâncias, o que já seria percurso de fôlego -pois que é repassado da crueza da dor humana e da tentativa de compreendê-la e situá-la.Deixo ao leitor o gosto de ir desvelando método, realidades e emoções, situações e soluções, bem como o prazer de ir ao encontro de uma rica galeria de tipos humanos com os quais vale a pena travar contato.Ao tratar de tão delicados assuntos -desconhecidos em nosso país sob tais formulações e abordagem, como tantas outras realidades da África negra -, a autora serve-se de indicadores de reflexão do maior significado, todos presentes de alguma forma no interior do texto, com a vantagem de o método estar mais presente no discurso do que no seu enunciado.Em primeiro lugar, Denise procura abordar a África negra e os problemas em que desejou penetrar a partir de uma visão que trata as questões de dentro para fora, chegando ao que chamo de ''África interna'', onde os fatos se concretizam a partir de práticas sociais originárias.É a ''África-Sujeito''.Com isso, contrapõe-se ao método que tenta a penetração nos fenômenos de fora 10 para dentro, chegando ao que denomino ''África-Objeto'', tão difundida e tão consagrada na bibliografia enganosa.Uma outra trilha que a autora percorre é a da palavra em sociedades negro-africanas.De fato, excluídos aqueles momentos em que se tornou necessário usar bibliografias, esse caminhar se fez no trabalho de campo -sim, Denise foi viver entre os Dogon para melhor conhecer o homem, a sociedade e o assunto a tratar -e no belo material obtido em narrativas e outros testemunhos junto ao grande número de depoentes, adivinhos, notáveis de cultos, terapeutas especialistas em problemas psíquicos, familiares, doentes etc., material esse que lhe trouxe sólidas instâncias empíricas que permitiram chegar a abstrações justificadas.Não se deve esquecer que na África negra de que se trata aqui, estamos diante de sociedades da palavra, nas quais esta não se confunde com a emissão articulada e inteligente da voz.Nestas sociedades, mais apropriadamente, a oralidade configura-se como dimensão da personalidade profunda que deve obrigatoriamente casar-se com a proposição segundo a qual essa palavra aparece como um conjunto de respostas a um determinado assunto, sempre compatíveis entre si, ainda que possam ser conflitantes.A palavra negro-africana não é meio de comunicação apenas, ela confere existência.Nesse sentido, é possível concordar que este é um trabalho referido à palavra dogon sobre a loucura, suas formas de manifestação, diagnósticos, impactos e métodos de tratamento, o todo sempre referido a valores e práticas sociais ancestrais.Ao adotar a palavra dogon, Denise conquistou verdades inestimáveis sobre a loucura entre eles e cresceu muito em sua figura de pesquisadora, pois que, bastante não fosse tal esforço, junta-se ao pequeno grupo de estudiosos que sabem não estarem diante de sociedade de analfabetos -como geralmente se quer para a África negra -, mas de sociedades da palavra.Aqui, convém abrir um espaço para apontar o nobre significado do conjunto de contos em que a loucura aparece entre os Dogon de uma ou outra maneira, recolhidos pela autora pela palavra das pessoas que identifica e que forneceram precioso material diferencial.O problema da loucura é tratado com desvelo pelos Dogon, que, diante de seu significado social, criaram temáticasalgumas de grande complexidade -inerentes às práticas sociais referidas ao fenômeno.Estes contos, além de sua beleza e de sua condição de mecanismo revelador de valores e conhecimentos, transmitem grande solidez ao discurso, permitindo chegar a uma compreensão mais real e honesta.É um dos momentos mais fortes do texto e base de uma série de reflexões.A autora perpassa sua obra com referências, às vezes extremamente sutis e difíceis de serem percebidas, à complexa questão das forças vitais, pois reconhece que os negro-africanos encontram nessa proposta os fundamentos de 11 grande parte de sua filosofia, de explicação do mundo, bem como respostas para algumas das mais importantes instâncias definidoras da natureza e dos seres, inclusive da noção de pessoa, que envolve de certa forma todo o trabalho.De fato, são essas forças passíveis de serem aumentadas ou diminuídas, provocando os respectivos resultados que, em última instância, regem os fatores de equilíbrio, desequilíbrio, ordem e desordem no homem e na sociedade, sendo a loucura manifestação de ruptura, de quebra da ordem natural ou da ordem social, o que precisa ser recuperado.O insucesso traz conseqüências dolorosas, como se verá.', '["madness","Dogon people","African traditional medicine","treatment of madness","social practices","order and disorder","human suffering","sub-Saharan Africa","ethnographic fieldwork","West Africa","individual and society"]', '10.7476/9788575413326', '9788575413326', 'https://books.scielo.org/id/97dxr', 'https://books.scielo.org/id/97dxr/pdf/barros-9788575413326.pdf', NULL, 'https://books.scielo.org/id/97dxr/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-97tnk', '97tnk', 'O slogan da tolerância na política educacional: uma análise crítica da estratégia de combate ao racismo', 'uma análise crítica da estratégia de combate ao racismo', '["Juliana Vieira Marques","Elma Júlia Gonçalves de Carvalho"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O uso do slogan da tolerância, enquanto instrumento de combate ao racismo e às diversas intolerâncias, tem sido recorrente nos documentos de políticas educacionais nas últimas décadas. Este aspecto tem exigido, por parte de nós educadores, reflexão e debate, pois temos que lidar diariamente com estas temáticas, não apenas porque as políticas de valorização e reconhecimento da diversidade têm chegado à sala de aula, mas também porque a diversidade assume cada vez mais relevância no mundo contemporâneo. Considerando que a perspectiva da educação antirracista se apresenta revestida de uma grande complexidade e nos desafia a repensar teorias e práticas, nos propusemos a organizar o livro O slogan da tolerância na política educacional: uma análise crítica da estratégia de combate ao racismo. Assim, por meio da análise histórica e social do conceito de raça e de racismo e do slogan da tolerância nas políticas educacionais antirracistas, pretendemos ampliar o debate sobre essa importante questão, bem como oferecer elementos para a compreensão sobre suas implicações sociais e educacionais na atualidade.', '["anti-racist education","education policy","racism","concept of race","diversity in education","anti-racist policy"]', '10.7476/9786587626192', '9786586383645', 'https://books.scielo.org/id/97tnk', NULL, NULL, 'https://books.scielo.org/id/97tnk/cover/cover_thumbnail.jpeg', 288, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-97w88', '97w88', 'Indumentária e moda: caminhos investigativos', NULL, '["Ivana Guilherme Símili","Ronaldo Salvador Vasques"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro foi concebido como um desfile de pensamentos sobre as roupas e a moda. Se há um fio condutor nas roupas-textos oferecidas para a apreciação do/a leitor/a, em cada um dos capítulos, é o de fazer pensar, o que é, afinal, a moda? Os caminhos percorridos pelos/as autores/as, como estilistas do pensamento, expõem-se nas criações dos objetos de estudos, proporcionando visões e versões da moda.', '["clothing","fashion","fashion theory","fashion studies"]', '10.7476/9788576286516', '9788576285809', 'https://books.scielo.org/id/97w88', NULL, NULL, 'https://books.scielo.org/id/97w88/cover/cover_thumbnail.jpeg', 220, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-98jsz', '98jsz', 'Gestão e vigilância sanitária: modos atuais do pensar e fazer', 'modos atuais do pensar e fazer', '["Marismary Horsth De Seta","Vera Lúcia Edais Pepe","Gisele O''Dwyer de Oliveira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra traz reflexões que iluminam a interseção entre vigilância sanitária e gestão em saúde, ao abordar os conceitos, saberes e práticas relacionadas a esses dois campos. Em linguagem dialógica e acessível, reveste-se de interesse para profissionais da saúde, gestores, professores, pesquisadores e alunos.', '["health management","health surveillance","public health administration","health management practices"]', '10.7476/9788575413265', '9788575410998', 'https://books.scielo.org/id/98jsz', 'https://books.scielo.org/id/98jsz/pdf/de-9788575413265.pdf', NULL, 'https://books.scielo.org/id/98jsz/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-98kjw', '98kjw', 'A saúde no Brasil em 2030: organização e gestão do sistema de saúde - Vol. 3', NULL, '["Fundação Oswaldo Cruz"]', 'Fiocruz/Ipea/Ministério da Saúde/Secretaria de Assuntos Estratégicos da Presidência da República', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste volume são tratados temas relacionados à Organização e Gestão do Sistema de Saúde, assinalando-se os princípios do sistema de saúde brasileiro. Inicialmente, aborda-se a gestão do nível federal do sistema (administração direta, agências reguladoras, fundações nacionais, empresas públicas nacionais) na condução da política nacional e na gestão do sistema de saúde no Brasil, com o propósito de identificar os principais desafios para a reconfiguração estratégica da atuação do Executivo federal na saúde nas próximas décadas.', '["health system organization","health services administration","Brazilian health system","federal health administration","health policy","regulatory agencies","public enterprises","strategic reconfiguration"]', '10.7476/9788581100173', '9788581100173', 'https://books.scielo.org/id/98kjw', 'https://books.scielo.org/id/98kjw/pdf/noronha-9788581100173.pdf', NULL, 'https://books.scielo.org/id/98kjw/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-98z6c', '98z6c', 'Gênero, sexualidades e diferenças: categorias de análise, (des)territórios de disputas', NULL, '["Márcio de Oliveira","Eliane Rose Maio"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra ‘Gênero, sexualidades e diferenças: categorias de análises, (des) territórios de disputas’, organizada por nós e escritas por parceiros/as, que lutam conosco sobre temas tão necessários em nossa vida cotidiana, remete-nos à necessidade de enfrentamento das mais variadas formas de violência e injustiça, buscando unir o campo da pesquisa e da militância. Ao apresentarmos um livro sobre as temáticas de gênero, sexualidade e diversidade sexual em tempos tão árduos e ameaçadores, traduz-nos a importância de continuarmos nessa luta: de respeito e dignidade para todas as pessoas, principalmente ao apresentarmos as violências contínuas, quer sejam violências sexuais, físicas, psíquicas, em crianças, ‘gays’, lésbicas, travestis, transexsuais, mulheres que fazem parte do considerado grupo vulnerável em razão de uma educação machista. O material apresenta textos que virão desconstruir essa educação sexista, principalmente a existente no espaço escolar, que ainda nos aprisiona em separações desiguais de gênero. Fica o convite para a leitura e para a (des) construção de conceitos sociais e culturais de gênero.', '["gender","sexuality","sexual diversity","gender-based violence","sexual violence","machismo","gender inequality","LGBT rights","women''s vulnerability","gender categories","research and activism"]', '10.7476/9786586383034', '9788576287551', 'https://books.scielo.org/id/98z6c', NULL, NULL, 'https://books.scielo.org/id/98z6c/cover/cover_thumbnail.jpeg', 141, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-999cg', '999cg', 'O canto do lobo: reflexões sobre a obra de António Lobo Antunes', NULL, '["Valverde, Tércia Costa","Cabral, Thaíla Moura"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O título “O canto do lobo: reflexões sobre a obra de António Lobo Antunes” é uma alusão à vastidão do conjunto da obra de António Lobo Antunes, consagrado escritor português contemporâneo, que encanta o público leitor através das falas melódicas de seus personagens que, poeticamente, fascinam a todos nós.', '["António Lobo Antunes","contemporary Portuguese literature","literary criticism","character speech","poetic language"]', '10.7476/9788555921063', '9786589524076', 'https://books.scielo.org/id/999cg', NULL, NULL, 'https://books.scielo.org/id/999cg/cover/cover_thumbnail.jpeg', 295, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9bjmr', '9bjmr', 'Literaturas africanas comparadas: paradigmas críticos e representações em contraponto', NULL, '["Elena Brugioni"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro apresenta um percurso de reflexão desenvolvido em torno dos paradigmas críticos e dos repertórios bibliográficos que pautam os estudos pós-coloniais. Convocando os projetos literários de autores como João Paulo Borges Coelho, Ungulani Ba Ka Khosa, Chinua Achebe, Mia Couto, Ruy Duarte de Carvalho, M. G. Vassanji, NoViolet Bulawayo, Arménio Vieira e Abdulai Sila, surgem possibilidades comparativas insólitas, das quais resultam novos pontos de partida para o campo de estudo das literaturas africanas contemporâneas. Elena Brugioni é professora licenciada em Letras Modernas. Publicou e desenvolveu pesquisas nas áreas de Literaturas Africanas Comparadas, Estudos do Oceano Índico, Teoria Pós-colonial e Literatura Comparada. Seus atuais interesses de pesquisa se debruçam sobre cartografias literárias e paradigmas críticos para o estudo das literaturas africanas contemporâneas e narrativas visuais em perspectiva pós-colonial comparada.', '["African literature","comparative literature","postcolonial studies","critical paradigm","literary representation","contemporary African literature","literary cartography","postcolonialism","Chinua Achebe","Mia Couto","NoViolet Bulawayo","Ungulani Ba Ka Khosa"]', '10.7476/9786586253757', '9786586253061', 'https://books.scielo.org/id/9bjmr', NULL, NULL, 'https://books.scielo.org/id/9bjmr/cover/cover_thumbnail.jpeg', 256, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9d22x', '9d22x', 'Psicologia e populações vulnerabilizadas: contextos de formação e intervenção', 'contextos de formação e intervenção', '["Renata Meira Véras","Sabrina Daiana Cúnico","Juliana Fernandes-Eloi","Dóris Firmino Rabelo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro aborda a interação da psicologia com grupos considerados vulneráveis segundo o conceito de vulnerabilidade social, que vem sendo adotado por diversos campos do conhecimento, partindo do reconhecimento de uma psicologia alinhada com os direitos humanos e compromissada com as questões sociais. A partir de capítulos com aportes teóricos e práticos, o livro aborda questões relevantes para o atendimento ético e qualificado dessas populações, demarcando as possibilidades e limitações enquanto profissional de psicologia e difundindo práticas eficazes em diferentes contextos. Espera-se que a leitura ofereça subsídios de avaliação e intervenção para estudantes e profissionais de psicologia que atuam ou têm interesse no trabalho com pessoas que têm suas vidas marcadas pelo preconceito, pela desigualdade e/ou pela exclusão social.', '["vulnerable populations","social vulnerability","psychology education","psychological intervention","human rights","ethical care","prejudice","social inequality","social exclusion","psychological assessment"]', '10.7476/9786556308937', '9786556306636', 'https://books.scielo.org/id/9d22x', 'https://books.scielo.org/id/9d22x/pdf/veras-9786556308937.pdf', NULL, 'https://books.scielo.org/id/9d22x/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9ffr9', '9ffr9', 'A sociologia do Brasil urbano', NULL, '["Anthony Leeds","Elisabeth Leeds"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em meio às comemorações pelos 450 anos de fundação da cidade do Rio de Janeiro, a Editora Fiocruz traz ao público a segunda edição de um livro que é referência no estudo de habitações populares e favelas no Brasil e na América Latina: A Sociologia do Brasil Urbano, do antropólogo Anthony Leeds e da cientista política Elizabeth Leeds. O original, fruto de uma década de pesquisas, havia sido originalmente publicado em 1978 por iniciativa do antropólogo Gilberto Velho. A nova edição, organizada por Elizabeth Leeds e pela socióloga Nísia Trindade Lima, vem reparar uma ausência: a obra encontrava-se esgotada e, portanto, inacessível às novas gerações de pesquisadores. A Sociologia do Brasil Urbano apresenta análises sobre a estrutura de poder e de classes à luz da história das favelas e dos assentamentos não controlados na América Latina. As favelas do Rio de Janeiro, objeto privilegiado pelo estudo, foram analisadas pelo modo como foram tratadas pelo Estado e como eram desenvolvidas as políticas de habitação.', '["urban sociology","favelas","informal settlements","popular housing","housing policy","Rio de Janeiro","Gilberto Velho"]', '10.7476/9788575415740', '9788575414644', 'https://books.scielo.org/id/9ffr9', NULL, NULL, 'https://books.scielo.org/id/9ffr9/cover/cover_thumbnail.jpeg', 432, 170, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9fmrc', '9fmrc', 'Médicos do Sertão: ciência, saúde e doenças em Goiás 1947-1960', NULL, '["Tamara Rangel Vieira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-11-08', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O processo de institucionalização da medicina goiana no período de 1947 a 1960 é o tema central do livro, que integra a coleção História e Saúde da Editora Fiocruz. Fruto da tese de doutorado da autora no Programa de Pós-Graduação em História das Ciências e da Saúde da Casa de Oswaldo Cruz, o título evidencia como um conjunto de jovens médicos construiu em Goiás - estado então distante dos mais conceituados centros médicos e científicos do Brasil do século XX - uma comunidade médica de pesquisa e ensino capaz de dialogar com seus pares, nacional e internacionalmente. Um dos resultados desse processo foi, como mostra a pesquisadora, o surgimento de diversas instituições e organizações médicas. Tamara Rangel Vieira aborda ainda a questão das desigualdades regionais e mostra como a atuação dos profissionais de saúde nas endemias típicas do Brasil Central influenciaram diretamente o processo de institucionalização da medicina goiana.', '["institutionalization of medicine","Goiás","medical history","medical community","medical education","medical research","medical institutions","regional health disparities","endemic disease","Central Brazil","young physicians"]', '10.7476/9786557081716', '9786557081372', 'https://books.scielo.org/id/9fmrc', NULL, NULL, 'https://books.scielo.org/id/9fmrc/cover/cover_thumbnail.jpeg', 306, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9g7j5', '9g7j5', 'Fast-food: um estudo sobre a globalização alimentar', NULL, '["José Ângelo Wenceslau Góes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A industrialização trouxe mudanças de hábitos alimentares com o consumo de alimentos enlatados, pré-cozidos, fast-food. A chamada “comida caseira” foi ficando cada vez mais rara. Este livro busca compreender as representações sociais e os significados desse tipo de alimentação, descrevendo e interpretando as mudanças de hábitos alimentares dos consumidores de duas lanchonetes de uma grande franquia, com o surgimento dessa alimentação em Salvador. Através de relatos, foi possível buscar nas relações socioculturais e simbólicas dos indivíduos um novo “olhar” do ato alimentar e sua influência na saúde.', '["fast food","food globalization","dietary habits","social representations","dietary intake","fast food chains","franchised restaurants","food and health","Salvador, Bahia"]', '10.7476/9788523211936', '9788523206932', 'https://books.scielo.org/id/9g7j5', NULL, NULL, 'https://books.scielo.org/id/9g7j5/cover/cover_thumbnail.jpeg', 215, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9gpd5', '9gpd5', 'Fusiones identitarias: el desplazamiento forzoso en el diario El País', NULL, '["Germán Ayala Osorio","Carmen Jimena Holguín","Hernando Uribe Castro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Colombia', 'SciELO Books', 'books', 2017, '2017-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'En este texto se registran los hallazgos del seguimiento y análisis de hechos noticiosos y editoriales asumidos y presentados por el diario EL PAÍS de Cali, en específicos momentos históricos a lo largo de varios gobiernos colombianos. Para asumir la tarea analítica, se plantean tres categorías pensadas desde el discurso de las representaciones sociales, móvil e hilo conductor de la investigación sobre la que se sostiene esta publicación. Dichas categorías se expresan así: 1. Objetivación positiva; 2. Objetivación neutra; y, 3. Objetivación negativa.', '["forced displacement","El País newspaper","media representation","objectivation","social representations","identity","Colombian government","news framing","editorial discourse","Cali"]', '10.7476/9789586190084', '9789588994321', 'https://books.scielo.org/id/9gpd5', NULL, NULL, 'https://books.scielo.org/id/9gpd5/cover/cover_thumbnail.jpeg', 240, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9gqvq', '9gqvq', '“A missão sou eu!”: uma história sobre o Código Penal de José Gonçalves Cotta na colônia de Moçambique', NULL, '["Cristiane Soares de Santana"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esse livro resulta de uma pesquisa de doutorado que teve como objetivo compreender os passos da Missão Etognósica de Moçambique e analisar uma das suas produções, o “Projecto” definitivo do Código Penal dos indígenas da colônia de Moçambique. A obra analisada neste livro insere-se na perspectiva da produção dos saberes coloniais, que podem ser caracterizados, segundo Loomba (2005), como uma variedade de escritos publicados compreendidos como importantes estudos contemporâneos do colonialismo e do pós-colonialismo, podendo deles serem exemplo: cartas, escritos governamentais, documentos escritos etc.', '["colonial criminal law","ethnographic missions","colonial knowledge production","colonialism","postcolonialism","colonial legal history"]', '10.7476/9786588211625', '9786588211519', 'https://books.scielo.org/id/9gqvq', 'https://books.scielo.org/id/9gqvq/pdf/santana-9786588211625.pdf', 'https://books.scielo.org/id/9gqvq/epub/santana-9786588211625.epub', 'https://books.scielo.org/id/9gqvq/cover/cover_thumbnail.jpeg', 265, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9gx7y', '9gx7y', 'Theodoro de Moraes na história da alfabetização no Brasil', NULL, '["Bárbara Cortella Pereira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra discute a contribuição do educador paulista Theodoro de Moraes (1877-1956) para a disseminação da assim denominada “pedagogia moderna” no Brasil, tanto por meio de sua atuação em cargos e funções no magistério como de sua produção ensaística e pedagógica, extremamente prolífera. Além de participar da produção de documentos oficiais, Moraes elaborou artigos para periódicos, textos de literatura infantil, livros, cartilhas e ainda foi tradutor e conferencista. O educador, de acordo com a autora, defendia com ênfase o ensino da leitura para crianças e para adolescentes e adultos, pelo chamado método analítico, um componente essencial da pedagogia moderna e que se destaca pela busca da praticidade e o uso da intuição. Por este método, o ensino deve ser gradual, completo e contínuo, de modo a favorecer a atividade individual do aluno. O processo de ensino seguiria, dessa forma, “do mais simples para o mais complicado” e avançaria “passo a passo”. O educador prescrevia ainda prática e exercícios constantes e o uso comedido das regras durante o transcorrer das atividades didáticas. Muito graças a Moraes, o método analítico para o ensino inicial da leitura – que se tornara oficial para as escolas primárias do estado de São Paulo entre o fim do século 19 e o início do século 20 – teve um inegável revigoramento e deixaria marcas indeléveis na educação do país.', '["history of literacy","modern pedagogy","reading instruction","analytical methods","adult literacy","primary education","São Paulo","educational thought","children''s literature"]', '10.7476/9786557144886', '9786557144886', 'https://books.scielo.org/id/9gx7y', 'https://books.scielo.org/id/9gx7y/pdf/pereira-9786557144886.pdf', NULL, 'https://books.scielo.org/id/9gx7y/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9hbxd', '9hbxd', 'Nossas árvores: conservação, uso e manejo de árvores nativas no sul da Bahia', NULL, '["Carlos Eduardo Pereira"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'O livro apresenta informações sobre a implantação e o atual estado de conservação da Mata Atlântica do Sul da Bahia, discorrendo sobre as principais interações ecológicas entre árvores e florestas tropicais, os princípios genéticos associados ao manejo e conservação das árvores, o uso das espécies nativas em programas de restauração florestal e sistemas agroflorestais, a coleta e produção de sementes, marcação e seleção de matrizes, além da produção de mudas em viveiros e o seu plantio no campo.', '["native tree species","tree conservation","tree management","Atlantic Forest","southern Bahia","tropical forests","forest restoration","agroforestry systems","seed collection","seed production","tree selection","seedling production"]', '10.7476/9786586213904', '9788574555430', 'https://books.scielo.org/id/9hbxd', NULL, NULL, 'https://books.scielo.org/id/9hbxd/cover/cover_thumbnail.jpeg', 304, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9hjwg', '9hjwg', 'A primeira gazeta da Bahia: idade d''Ouro do Brazil', NULL, '["Maria Beatriz Nizza da Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, a historiadora luso-portuguesa Maria Beatriz Nizza da Silva faz uma análise da gazeta editada na Bahia a partir de 1811, resgatando e revelando a Cidade da Bahia durante o período colonial, através de uma perspectiva social e cultural e um olhar lançado sob as práticas comunicacionais do período. A Idade d’Ouro do Brazil, publicação implantada por Manuel Antônio de Castro, foi uma verdadeira revolução na Bahia, dando impulso à sua imprensa.', '["colonial press","Bahia","social and cultural history","19th-century Brazil"]', '10.7476/9788523212223', '9788523212223', 'https://books.scielo.org/id/9hjwg', 'https://books.scielo.org/id/9hjwg/pdf/silva-9788523212223.pdf', NULL, 'https://books.scielo.org/id/9hjwg/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9hsxr', '9hsxr', 'Recortes do cotidiano do SUS', 'análises, reflexões e contribuições de um mestrado profissional', '["Maria Aparecida Araújo Figueiredo","Gilvânia Patrícia do Nascimento Paixão"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro traz uma coletânea resultante de projetos desenvolvidos por discentes do Mestrado Profissional em Saúde Coletiva (Mepisco). Com uma abordagem diversificada, formada por distintos olhares, o livro mergulha em diferentes temáticas presentes no cotidiano do Sistema Único de Saúde (SUS), uma vez que as mestrandas e mestrandos trouxeram as problemáticas iniciais de seus cotidianos profissionais no âmbito do SUS. Assim, ao folhear as páginas desta obra, o leitor imerge em textos sobre diferentes públicos, ambientes e níveis de atenção do SUS. É uma leitura altamente recomendada para profissionais, gestores e estudantes que se interessam pela temática e que buscam contribuir com a saúde pública do país. Se esse for o seu caso, junte-se a nós nesta jornada e descubra como Recortes do cotidiano do SUS pode contribuir com o fortalecimento das práticas profissionais no âmbito do SUS.', '["public health system","everyday practices","healthcare workers","primary care","levels of care","health management","professional practice"]', '10.7476/9786556308982', '9786556306483', 'https://books.scielo.org/id/9hsxr', 'https://books.scielo.org/id/9hsxr/pdf/figueiredo-9786556308982.pdf', NULL, 'https://books.scielo.org/id/9hsxr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9jbn9', '9jbn9', 'Comunicación y ciudad: lenguajes, actores y relatos', NULL, '["Narcisa Medranda Morales","Nelly Valbuena-Bedoya"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Una veintena de autores participa en esta publicación en la que la comunicación y la política ciudadana son protagonistas. Las reflexiones teóricas provenientes de claustros docentes, grupos de investigación y prácticas en el aula, están divididas en tres grandes bloques: Aproximaciones a las relaciones entre comunicación y ciudad, La ciudad en narrativa meme y Resignificación, de la teoría a la práctica. Las ponencias, presentadas en las Jornadas de Comunicación y reunidas en estas páginas, tocan temas clave sobre ciudad, globalización y tecnología; reafirman la identidad del comunicador y estimulan su creatividad para potenciar herramientas orientadas a una comunicación transformadora desde la construcción colectiva.', '["citizen communication","resignification","globalization","technology","transformative communication","collective construction","urban identity"]', '10.7476/9789978105702', '9789978105702', 'https://books.scielo.org/id/9jbn9', 'https://books.scielo.org/id/9jbn9/pdf/medranda-9789978105702.pdf', NULL, 'https://books.scielo.org/id/9jbn9/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9jg68', '9jg68', 'Conflito no Araguaia: peões e posseiros contra a grande empresa', NULL, '["Neide Esterci"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em 1967, estive pela primeira vez em Santa Terezinha de passagem para a aldeia Tapirapé, onde cheguei como auxiliar de pesquisa do Prof. Roberto Cardoso de Oliveira, à época desenvolvendo um projeto sobre contatos interétnicos. Eu não tinha, então, intenção de estudar posseiros e peões, mas o que vi e ouvi foi a motivação para retornar, anos mais tarde. [trecho tirado da introdução do livro]', '["Araguaia","land disputes","landless workers","landowners","Santa Terezinha","indigenous peoples","interethnic relations","agrarian conflict"]', '10.7476/9788599662519', '9788599662519', 'https://books.scielo.org/id/9jg68', 'https://books.scielo.org/id/9jg68/pdf/esterci-9788599662519.pdf', NULL, 'https://books.scielo.org/id/9jg68/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9js25', '9js25', 'Hipnose, dores, crônicas &amp; complexidade: técnicas avançadas', NULL, '["Maurício S. Neubern"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Neuroscience', 'As relações entre hipnose e dores crônicas consistem num dos eventos mais antigos da história da psicologia moderna. Contudo, até hoje pouco se explica sobre a hipnose e seus modos de ação, sem contar que, geralmente, ela se encontra longe das academias. Como algumas palavras, num contexto relacional específico, conseguem alterar significativamente dores intensas decorrentes de problemas como fibromialgia, lesões após acidentes, processos oncológicos e doenças autoimunes é uma questão que ainda se encontra longe de respostas. Ao mesmo tempo, as dores crônicas também representam desafios a profissionais e pesquisadores, pois escapam à lógica homogênea organicista para exigirem interdisciplinaridade. Desemprego, depressão, morte, violência, espiritualidade, trabalho, família, sexualidade, dinheiro, gênero e classe social são temas que surgem com frequência quando se oferecem espaços de acolhimento a pessoas acometidas por essas dores. Logo, um livro sobre técnicas de hipnose não pode se render ao instrumentalismo dominante em vários setores de nossa sociedade. Ele precisa nascer comprometido com a eficiência de seus resultados, mas também com a reflexão teórica e ética de seus fundamentos. Trata-se de fenômenos humanos que necessitam de uma visão que favoreça, ou ao menos se mantenha aberta, à articulação de suas várias dimensões. Sem essa adesão à complexidade, não se torna possível o reconhecimento do humano.', '["hypnosis","chronic pain","fibromyalgia","pain management","complexity","multidisciplinary care"]', '10.7476/9788523013455', '9788523012489', 'https://books.scielo.org/id/9js25', NULL, NULL, 'https://books.scielo.org/id/9js25/cover/cover_thumbnail.jpeg', 280, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9k5p6', '9k5p6', 'Biotechnology in Europe and Latin America: prospects for co-operation', NULL, '["Bernardo Sorj","Mark F. Cantley","Simpson, Karl"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'en', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'It is not easy to enact laws on fundamental issues of complex nature like, for instance, biotechnology.In many instances it implies a high degree of confidence in the assessment and monitoring of the long-term implications and consequences of the decisions taken today.This is not yet the case!The decisions taken today do have more than ever in the past far-reaching consequences for millions of people, whose daily life will be deeply affected in the future.In a modern representative democracy, it is a must that Parliament has the capability to legislate on the basis of honest attempts to forecast and assess the long-term implications and consequences of a given development; so that it is possible to monitor and direct the processes in such a way that the impact is for the benefit of mankind, not to its detriment.Since it has become clear that developments in biotechnology have an international-character, international cooperation, regulations and legislation are of great importance.Especially regulations in the field of deliberate release of manipulated micro-organisms, because they are not at all controlled by national borders.Important is also the democratization of the decision-making process.This means that more attention should be paid to the provision of balanced information to the public at large in order to increase public awareness.', '["biotechnology regulation","international cooperation","biotechnology law","democratic decision-making","public awareness","science policy","Europe","Latin America"]', '10.7476/9788579820366', '9788579820366', 'https://books.scielo.org/id/9k5p6', 'https://books.scielo.org/id/9k5p6/pdf/sorj-9788579820366.pdf', NULL, 'https://books.scielo.org/id/9k5p6/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9k9jc', '9k9jc', 'O massacre de Manguinhos', NULL, '["Herman Lent"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A nova edição de O Massacre de Manguinhos inaugura a Coleção Memória Viva, criada para tornar acessíveis aos leitores obras de reconhecida relevância acadêmica e institucional. A coleção é fruto do projeto “Acesso aberto e uso da literatura científica no ensino”, desenvolvido no Instituto de Comunicação e Informação Científica e Tecnológica em Saúde (Icict), da Fundação Oswaldo Cruz (Fiocruz), onde as políticas de acesso aberto têm sido encaradas como estratégicas para o fortalecimento da ciência e da saúde pública. O pesquisador Herman Lent narra a repressão da ditadura militar à atividade científica na Fundação Oswaldo Cruz.', '["military dictatorship","Fiocruz","scientific freedom","public health research"]', '10.7476/9788575416402', '9788575416402', 'https://books.scielo.org/id/9k9jc', 'https://books.scielo.org/id/9k9jc/pdf/lent-9788575416402.pdf', NULL, 'https://books.scielo.org/id/9k9jc/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9kcvv', '9kcvv', 'Em Pessoa: estudos sobre a poesia e a prosa de Fernando Pessoa', NULL, '["Ferreira, Sandra","Edvaldo Aparecido Bergamo"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra Em Pessoa: estudos sobre a poesia e a prosa de Fernando Pessoa, organizada por Sandra Ferreira e Edvaldo Bergamo, apresenta um conjunto de ensaios escritos por pesquisadores dedicados aos estudos da obra pessoana e vinculados a prestigiadas instituições nacionais e internacionais: Maria Helena Nery Garcez (USP), Jerónimo Pizarro (Universidad de los Andes/Colômbia), Luiz Maffei (UFF), Onésimo Teotónio Almeida (Brown University/EUA), Jorge Fernandes da Silveira (UFRJ/CNPq), Paulo de Medeiros (University of Warwick/Reino Unido), Lilian Jacoto (USP), Augusto Rodrigues da Silva Junior (UnB), Ida Alves (UFF/CNPq), Natália Rocha Marques e Edvaldo A. Bergamo (UnB), Nicolás Barbosa López (Universidad de los Andes/Colômbia), Ana Clara Magalhães de Medeiros (UnB), Fernando de Moraes Gebra (UFFS) e Hermenegildo Bastos (UnB). Os ensaios aqui reunidos contribuem para reafirmar a dimensão universal de Fernando Pessoa (“Sê plural como o universo!”) e o incessante empenho crítico demandado por sua obra, ainda, e cada vez mais, capaz de incutir dúvidas, convidar a revisitações interpretativas, sugerir outras tantas interpretações e correlações, como é próprio de toda obra viva. Tanto é assim que uma das inumeráveis divisas para a obra de Pessoa poderia ser colhida no Livro do Desassossego: “Vivo sempre no presente”.', '["Fernando Pessoa","Portuguese poetry","Portuguese prose","literary criticism","literary interpretation","Livro do Desassossego","universalism in literature"]', '10.7476/9788523013424', '9788523010782', 'https://books.scielo.org/id/9kcvv', NULL, NULL, 'https://books.scielo.org/id/9kcvv/cover/cover_thumbnail.jpeg', 282, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9kdvf', '9kdvf', 'Psiquiatria social e reforma psiquiátrica', NULL, '["Paulo Amarante"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1994, '1994-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Nesta obra o leitor encontrará especialistas da área discutindo a reforma psiquiátrica brasileira nos seguintes aspectos: comunidade terapêutica; psicoterapia institucional; psiquiatria de setor; psiquiatria preventiva e comunitária; psiquiatria democrática; território; cidadania e doença mental; desvio e marginalização; história da psiquiatria; epidemiologia; planejamento em saúde mental. Os textos repensam as teorias e subsidiam a necessária revisão da prática e, por isso, constituem-se numa ferramenta importante para os que se dedicam ao ensino e à pesquisa no âmbito da saúde mental e os que militam na busca da cidadania nesse setor.', '["psychiatric reform","social psychiatry","therapeutic communities","institutional psychotherapy","mental health prevention","community psychiatry","democratic psychiatry","history of psychiatry","psychiatric epidemiology","mental health service planning","mental health policy","Brazil"]', '10.7476/9788575415061', '9788585676049', 'https://books.scielo.org/id/9kdvf', 'https://books.scielo.org/id/9kdvf/pdf/amarante-9788575415061.pdf', NULL, 'https://books.scielo.org/id/9kdvf/cover/cover_thumbnail.jpeg', NULL, 86, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9kj3w', '9kj3w', 'Cidade, corpo e alimentação: aproximações interdisciplinares', NULL, '["Maria Lúcia Magalhães Bosi","Shirley Donizete Prado","Lígia Amparo-Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'alimentação e saúde: saberes em rede.Disponível em: http://books.scielo.org/search/?lang=pt&index=tw&where=BOOK&q=shirley&filter%5Bpublisher%5D%5B%5D=EDUERJ.APRESENTAÇÃO 13 que identifica o senso comum está presente nas ideias de "área rural" e "área urbana", "zona rural" e "zona urbana"; em trechos que mencionam "domicílios distribuídos em localidades urbanas e rurais de determinados municípios" ou "a área mais pobre do município no perímetro urbano e na zona rural" ou "agricultura familiar rural" ou ainda como aspectos de ordenamento metodológico para trabalhos de campo, como no estabelecimento de "[xx domicílios] no extrato urbano e [xx] no extrato rural".A visão estanque de um mapa físico no qual se recorta localidades distintas, separadas por linhas que delimitam conjuntos de indivíduos objetivamente fixados, predomina nos desenhos metodológicos e nas discussões decorrentes dessas concepções.Em raros casos, uma noção de movimento é mencionada como "transição de um cenário rural para o urbano", o que mais se assemelha ao deslocamento de indivíduos desprovido, contudo, de problematização ou análise da ordem simbólica, das experiências humanas, dos afetos, dos valores éticos e morais, das relações de poder que atravessam os fenômenos em exame.Região como recorte geográfico institucionalizado foi o que encontramos em 90 artigos que mencionavam a "Região Nordeste do Brasil", a "Região Metropolitana do Rio de Janeiro, a "Região Oeste da cidade de São Paulo" ou uma determinada "Região do Estado de Santa Catarina", entre outras variações cruas das divisões políticas formais do país.Similarmente, encontra-se o local presente em 44 artigos quando são mencionados o "planejamento intersetorial em nível local", a "biodiversidade local", "o refeitório [como] local de consumo", a "equipe local", o "local institucionalmente reconhecido da pesquisa científica", o "local de trabalho", a "realidade local" ou o "local de aquisição de frutas".Como uma versão em tamanho menor da área urbana ou da região, a ideia de local segue na mesma esteira da concretude dos mapas, das linhas formais de demarcação.Cartografia não encontra expressão nesses trabalhos, sequer como materialização gráfica da superfície terrestre, o que, em ideia, equivaleria ao local representado ou a um mapeamento, esta sim palavra encontrada em nossos exercícios exploratórios guardando os significados já registrados.os seus paradoxos.Força sem adjetivos e substantivos, incitadora de políticas destituídas de protagonistas definidos; força que lega à cidade o sentido de uma incansável arena de embates.Civilizar, educar, aprimorar e conquistar direitos seriam perpassados pela intensidade do inquieto coletivo mantendo-os em constante instabilidade.Metas cívicas, projetos de cidadania seriam inquiridos drasticamente pelos paradoxos que irrompem da urbe viva, desigual e tensa.A alma da rua possui rosto, mas qual?Para que serve a cidade?João do Rio, ao afirmar a existência da alma estranha aos urbanistas, aproxima-se de Walter Benjamin, avizinha-se do rosto do mundo das coisas, presença intensiva marcante nos jogos infantis descrito pelo filósofo berlinense.Nos jogos dos infantes, crianças: sentem-se irresistivelmente atraídas pelo resíduo que surge na construção, no trabalho de jardinagem ou doméstico, na costura ou na marcenaria.Em produtos residuais reconhecem o rosto que o mundo das coisas volta exatamente para elas, e para elas unicamente.(BENJAMIN, 1987, p. 19) No jogo infantil, o rosto do mundo das coisas alheio às classificações inequívocas dos objetos, às funções do dia a dia, revida, acena para o olhar e insufla a ação.As coisas têm almas singulares que incitam experimentações intermináveis.A rua cujo rosto pertence ao mundo das coisas, apela por jogos, ou lutas, inesgotáveis: Crianças e artistas se põem a experimentar com o mundo, isto é, a destruí-lo e a reconstruí-lo, porque não o consideram como definitivamente dado.Essas brincadeiras essenciais implicam uma noção de ação política que não visa a transformação do mundo segundo normas prefixadas, mas a partir de exercícios e tentativas nos quais a experiência humana -tanto espiritual e inteligível como sensível e corporal -assume outras formas.(GAGNEBIN, 2014, p. 175)', '["urban-rural divide","food and health","food and the body","dietary intake","food and power","gender and food"]', '10.7476/9786556300108', '9786556300108', 'https://books.scielo.org/id/9kj3w', 'https://books.scielo.org/id/9kj3w/pdf/bosi-9786556300108.pdf', NULL, 'https://books.scielo.org/id/9kj3w/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9kyp5', '9kyp5', 'Estudos linguísticos da/na Fronteira Sul', NULL, '["Cláudia Andrea Rost Snichelotto","Mary Neiva Surdi da Luz"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os textos que compõem este livro vinculam-se às três linhas de pesquisa do Programa de Pós-Graduação em Estudos Linguísticos da Universidade Federal da Fronteira Sul (UFFS): 1) Práticas discursivas e subjetividades; 2) Diversidade e mudança linguística; 3) Língua e cognição: representação e processamento da linguagem. Todos os textos atestam a qualidade, o amadurecimento e a consolidação da pesquisa em Estudos Linguísticos da UFFS e, de modo geral, dão chance ao leitor de conhecer a história do tempo presente da produção do conhecimento científico do PPGEL. A primeira parte trata de reflexões sobre o conceito de complexidade linguística, da intersecção entre Linguística e Literatura, através da metáfora do literário e do grande empreendimento de organizar o inédito Atlas Linguístico das línguas em contato nesta parte da Fronteira Sul. A segunda dedica-se a abordagens que pendem para a perspectiva formal da gramática. E a última parte trata de posturas discursivas.', '["linguistic complexity","linguistics and literature","contact languages","linguistic atlas","formal grammars","discursive practices","subjectivity","linguistic diversity","language change","language and cognition","language processing","linguistic representation"]', '10.7476/9786586545449', NULL, 'https://books.scielo.org/id/9kyp5', 'https://books.scielo.org/id/9kyp5/pdf/snichelotto-9786586545449.pdf', NULL, 'https://books.scielo.org/id/9kyp5/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9n2wg', '9n2wg', 'Textos hipocráticos: o doente, o médico e a doença', NULL, '["Henrique Fortuna Cairus","Wilson Alves Ribeiro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra apresenta pela primeira vez e na íntegra, alguns dos mais importantes tratados recolhidos sob o nome de Hipócrates na coleção de textos gregos chamados Corpus Hippcraticum. Os tratados escolhidos apresentam importantes conceitos e preceitos desenvolvidos há mais de dois milênios e que, até hoje, estão presentes na prática médica ocidental. O leitor encontra textos sobre a importância da medicina hipocrática, tratados deontológicos, que estabeleceram os alicerces práticos da ética médica, e sobre o universo da prática médica antiga.', '["Hippocratic Corpus","Hippocratic medicine","Hippocratic Oath","medical ethics","history of medicine","ancient Greek medicine","physician-patient relationship","concept of disease","medical deontology"]', '10.7476/9788575413753', '9788575413753', 'https://books.scielo.org/id/9n2wg', 'https://books.scielo.org/id/9n2wg/pdf/cairus-9788575413753.pdf', NULL, 'https://books.scielo.org/id/9n2wg/cover/cover_thumbnail.jpeg', NULL, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9n7jy', '9n7jy', 'Educação, comunicação e tecnologia educacional: interfaces com o campo da saúde', NULL, '["Simone Monteiro","Eliane Portes Vargas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra reúne artigos sobre as tecnologias educacionais desenvolvidas no contexto dos desafios colocados pela Aids e demais agravos à saúde nos últimos 25 anos. Os textos aqui reunidos foram desenvolvidos por pesquisadores dedicados a análises conceituais e ao desenvolvimento de estratégias metodológicas relacionadas, direta ou indiretamente, à produção e avaliação do uso de tecnologias educacionais.', '["educational technology","health education","HIV/AIDS","health communication","educational technology evaluation","health education strategies"]', '10.7476/9788575415337', '9788575415337', 'https://books.scielo.org/id/9n7jy', 'https://books.scielo.org/id/9n7jy/pdf/monteiro-9788575415337.pdf', NULL, 'https://books.scielo.org/id/9n7jy/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9nk5n', '9nk5n', 'A Itália em disputa: comunistas e democratas-cristãos no longo pós-guerra (1943-1978)', NULL, '["Giuseppe Vacca"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A história narrada neste livro é excepcional. São 35 anos da vida política italiana após o fascismo e a guerra. Instalada a República, veio em seguida a luta pela reconstrução e pela modernização do país. Com o passar dos anos, alteraram-se sobremaneira as estruturas do país e a sociabilidade dos italianos. Essa grande epopeia se fez por meio de uma dinâmica política marcada pelo embate e, ao mesmo tempo, pelo consenso entre a Democracia Cristã e o Partido Comunista, duas forças populares e opostas. O que dava sustentação ao sistema político não era a oposição entre direita e esquerda, mas uma dupla legitimação: o antifascismo, base do “campo” democrático, e o anticomunismo, imprescindível para governar em tempos de Guerra Fria. Vacca analisa a fase ascendente da democracia italiana, da Liberazione à morte de Aldo Moro, para muitos um marco do seu bloqueio e o início do longo declínio. (Alberto Aggio)', '["Christian Democracy","Italian Communist Party","postwar Italy","Italy","Cold War","anti-fascism","anti-communism","political consensus","Italian political history","Aldo Moro"]', '10.7476/9788526815377', '9786586253948', 'https://books.scielo.org/id/9nk5n', NULL, NULL, 'https://books.scielo.org/id/9nk5n/cover/cover_thumbnail.jpeg', 303, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9pcr2', '9pcr2', 'Composições do instante: processos de composição e improvisação em dança contemporânea na Cidade de São Paulo', 'processos de composição e improvisação em dança contemporânea na Cidade de São Paulo', '["Clara Gouvêa do Prado"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O presente trabalho tem como território de pesquisa a trajetória e produção artística da Cia Damas em Trânsito e os Bucaneiros (CDTB) (2006- ), grupo de dança contemporânea paulistano. Compreende-se esta investigação em sua incursão no percurso do grupo e nos entrelaçamentos na experiência artística da pesquisadora, que o integra desde a fundação, pela abordagem autoetnográfica amparada em Fortin (2009), e pela poética mobilizada por Louppe (2012). Evidencia-se nesse trajeto o agir composicional da CDTB, síntese do conjunto de suas práticas e fazeres, levando-se em conta seus processos de criação em dança, nos quais a improvisação é tanto procedimento de criação quanto modo de composição no aqui-agora da cena. Busca-se ainda, nesta discussão, levantar questões e propor diálogos sobre a dança contemporânea, a improvisação, o Contato Improvisação, as corporeidades cênicas, os processos de criação coletivos e colaborativos e a dança em espaços urbanos. Considera-se o corpo-sujeito de sua dança, seus discursos e história, como aponta Lilian Vilela (2010), e compreende-se neste percurso uma narrativa singular. Neste recorte conciliamos a leitura dos processos e das obras realizados pelo grupo, traçando paralelos com a dança situada, com os fundamentos do Contato Improvisação e com as práticas somáticas (alicerces das suas pesquisas corporais), assim como com os procedimentos e pesquisas de artistas improvisadores que foram referências para o grupo no cenário artístico da dança contemporânea brasileira. Ademais, a investigação e a criação da CDTB nos espaços urbanos alavancam reflexões sobre a arte e a cidade, arte relacional e contextual, e reverberações com discussões que regem os regimes espaciais e cinéticos nas cidades segundo questões e conceitos de Milton Santos (2014) e André Lepecki (2012).', '["contemporary dance","dance composition","improvisation","contact improvisation","somatic practices","collective creation","urban dance","body in performance","relational art","art and the city","Brazilian contemporary dance","São Paulo"]', '10.7476/9786559543748', '9786559543748', 'https://books.scielo.org/id/9pcr2', 'https://books.scielo.org/id/9pcr2/pdf/prado-9786559543748.pdf', NULL, 'https://books.scielo.org/id/9pcr2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9pzv9', '9pzv9', 'Um metódico à brasileira: a História da historiografia de Afonso de Taunay (1911-1939)', NULL, '["Karina Anhezini"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A historiografia brasileira, de forma geral, tem negligenciado a real abrangência das documentações propostas e analisadas por Afonso de Taunay. Neste livro, Karina Anhezini preenche essa significativa lacuna: recupera aquela documentação, localiza e critica os usos dados das infor­mações e nos oferece uma obra abrangente e pertinente aos modelos analíticos desenvolvidos pela historiografia moderna. De forma competente, a autora demonstra como a historiografia desenvolvida por Taunay tinha caráter laudatório e épico – elementos fundamentais para a compreesão da história escrita no Brasil no final do século XIX e nas primeira décadas do século XX – e tece um fio narrati­vo que navega por inúmeras fontes literárias, sem, contudo, perder a pre­cisão e o detalhamento histórico. Ao recuperar os escritos e o modelo metodológico de análise desenvolvido por Taunay, trilhando pelo modelo de intelectualidade existente naquele período, a autora abre novos cami­nhos para a percepção das obras e do pensamento desse historiador. Um livro importante, que certamente garante a continuidade e a atualização dos debates sobre a historiografia brasileira na atualidade.', '["Brazilian historiography","historical method","intellectual history","late 19th and early 20th century","historiographical sources"]', '10.7476/9786557145388', '9786557145388', 'https://books.scielo.org/id/9pzv9', 'https://books.scielo.org/id/9pzv9/pdf/anhezini-9786557145388.pdf', NULL, 'https://books.scielo.org/id/9pzv9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9q', '9q', 'Escritas e narrativas sobre alimentação e cultura', NULL, '["Maria do Carmo Soares de Freitas","Gardênia Abreu Vieira Fontes","Oliveria, Nilce de"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne estudos sobre Alimentação e Cultura e prioriza escritas e narrativas sobre o comer em distintos grupos e lugares. Fundamenta-se nas Ciências Humanas para diversas leituras sobre o comer e, assim, busca compreender a nutrição como ação social. E para conhecer o universo simbólico das relações entre cultura e alimentação, estudam-se o habitus, condutas, comportamentos alimentares, valores e crenças.', '["food and culture","dietary habits","food narratives","symbolic relations","habitus","food consumption behavior"]', '10.7476/9788523209148', '9788523209148', 'https://books.scielo.org/id/9q', 'https://books.scielo.org/id/9q/pdf/freitas-9788523209148.pdf', NULL, 'https://books.scielo.org/id/9q/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9qfsp', '9qfsp', 'Guia de identificação das espécies de anfíbios (Anura e Gymnophiona) do estado de Goiás e do Distrito Federal, Brasil Central', NULL, '["Wilian Vaz Silva","Natan Medeiros Maciel","Fausto Nomura","Alessandro Ribeiro de Morais","Vinícius Guerra","Danusy Lopes Santos","Sheila Pereira de Andrade","Arthur Ângelo Bispo de Oliveira","Reuber Albuquerque Brandão","Rogério Pereira Bastos"]', 'Sociedade Brasileira de Zoologia', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'O “Guia de Identificação das Espécies de Anfíbios (Anura e Gymnophiona) do Estado de Goiás e do Distrito Federal, Brasil Central” é um trabalho que busca promover a disseminação do conhecimento regional e popularizar o conhecimento sobre os anfíbios do Cerrado, sendo um instrumento de pesquisa útil, tanto para o leigo quanto para o pesquisador interessado. O guia está estruturado em seções que tratam da caracterização de 114 espécies de anfíbios (111 anuros e 3 gimnofionos) com informações disponíveis na literatura científica e dos próprios autores. A caracterização de cada espécie reúne informações sobre a localidade-tipo, a distribuição geográfica, os nomes populares, a caracterização morfológica do adulto e do girino e dados de história natural. São apresentadas imagens em vida das espécies e mapas de distribuição para o Estado de Goiás e Distrito Federal, além de uma chave dicotômica confeccionada a partir da seleção de algumas características morfológicas evidentes, que podem ajudar na identificação das espécies.', '["amphibians","Anura","caecilians","species identification","Cerrado","Goiás","Distrito Federal","geographic distribution","morphology","tadpoles","natural history","dichotomous key"]', '10.7476/9786587590011', '9786587590011', 'https://books.scielo.org/id/9qfsp', 'https://books.scielo.org/id/9qfsp/pdf/vaz-9786587590011.pdf', NULL, 'https://books.scielo.org/id/9qfsp/cover/cover_thumbnail.jpeg', NULL, 47, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9qkyp', '9qkyp', 'Rede de frio: gestão, especificidades e atividades', NULL, '["Silva, Marileide do Nascimento","Flauzino, Regina Fernandes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Um eficiente (e complexo) processo de conservação, armazenamento e distribuição – denominado rede de frio – garante a qualidade das vacinas que chegam às diversas salas de imunização do país. A manutenção adequada da rede de frio é fator essencial para que se alcance o objetivo de imunizar as pessoas contra doenças infecciosas de grande relevância. Igualmente indispensáveis são a conscientização e a preparação dos profissionais encarregados da rede de frio, a quem esta obra especialmente se dirige. “É fundamental que a formação desses profissionais esteja em consonância com a proposta da vigilância em saúde, baseada na atenção básica e na reorganização das práticas sanitárias, com ênfase na integralidade do cuidado, sem perder o foco da importância do conhecimento técnico”, afirmam as organizadoras. Este volume “destaca a necessidade do trabalho compartilhado e do planejamento para gestão eficiente da rede; ressalta o papel estratégico que o trabalhador da rede de frio desempenha nesse processo; e debate assuntos que vão desde o calendário vacinal até o gerenciamento dos resíduos resultantes das atividades desenvolvidas na imunização e na rede de frio de imunobiológicos”.', '["cold chain","vaccine storage and distribution","immunization","vaccine management","health professions education","health surveillance","primary care","immunobiological products","cold chain management"]', '10.7476/9786557080962', '9786557080962', 'https://books.scielo.org/id/9qkyp', 'https://books.scielo.org/id/9qkyp/pdf/silva-9786557080962.pdf', NULL, 'https://books.scielo.org/id/9qkyp/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9r27r', '9r27r', 'Práticas epidemiológicas nos serviços de saúde: arranjos tecnológicos', NULL, '["Rita Barradas Barata"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, '2024-11-12', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra trata da epidemiologia nos serviços de saúde do Sistema Único de Saúde (SUS), e diferentes arranjos tecnológicos, influenciados pelo saber epidemiológico, disponíveis para a organização das práticas em saúde coletiva.', '["health services","epidemiological knowledge","public health practice","Unified Health System (SUS)"]', '10.7476/9786557082263', '9786557082263', 'https://books.scielo.org/id/9r27r', NULL, NULL, 'https://books.scielo.org/id/9r27r/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9s5b9', '9s5b9', 'Conexões: ensaios em história da arte', NULL, '["Maria Cristina Louro Berbara","Roberto Conduru","Vera Beatriz Siqueira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Articula contribuições de professores e estudantes de graduação e pós-graduação de instituições do Brasil e do exterior, com o objetivo de produzir uma história da arte fora do paradigma de centro e periferia, a partir da América Latina e do Brasil. Os ensaios enfocam as relações entre história da arte e processos de mundialização, os trânsitos de ideias e materiais e observam os paralelos de realizações artísticas em diferentes contextos socioculturais.', '["art history","Latin American art","Brazilian art","globalization","artistic production","sociocultural context","transnational art history"]', '10.7476/9786588808085', '9788575113431', 'https://books.scielo.org/id/9s5b9', NULL, NULL, 'https://books.scielo.org/id/9s5b9/cover/cover_thumbnail.jpeg', 324, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9tc7r', '9tc7r', 'Saúde, trabalho e formação profissional', NULL, '["Antenor Amâncio Filho","M. Cecilia G. B. Moreira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Reúne textos de especialistas das áreas de Saúde e de Educação com longa, competente e comprometida atuação na luta por mudanças sociais, preocupados com um (con)viver humano mais solidário. A obra mostra ser possível a constituição de serviços de saúde com profissionais sensíveis e preparados para atuar em tempos de novas exigências técnicas e de capacitação profissional. Por instigar a (re)pensar o aperfeiçoamento técnico e ético do trabalho, com idéias e propostas originais e atuais, trata-se, certamente, de contribuição de relevância para aqueles que, direta ou indiretamente, encontram-se engajados na causa do Sistema Único de Saúde.', '["healthcare workers","professional training","health services","Unified Health System (SUS)","social change","solidarity","health education"]', '10.7476/9788575412787', '9788575412787', 'https://books.scielo.org/id/9tc7r', 'https://books.scielo.org/id/9tc7r/pdf/amancio-9788575412787.pdf', NULL, 'https://books.scielo.org/id/9tc7r/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9tmvy', '9tmvy', 'Guerra fria e política editorial: a trajetória da Edições GRD e a campanha anticomunista dos Estados Unidos no Brasil (1956-1968)', NULL, '["Laura de Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Analisa a publicação de livros anticomunistas no Brasil entre as décadas de 1950 e 1960, tomando como referencial a trajetória da Edições GRD. Através de sua relação com instituições como o IPÊS, o Franklin Book Programs e a USIA, a editora brasileira se situou no epicentro das políticas editoriais norteamericanas durante a Guerra Fria.', '["Cold War","editorial policy","anti-communism","United States Information Agency","inverse photoemission","US cultural diplomacy","book publishing","Brazil–United States relations","1950s-1960s"]', '10.7476/9788576286509', '9788576286332', 'https://books.scielo.org/id/9tmvy', NULL, NULL, 'https://books.scielo.org/id/9tmvy/cover/cover_thumbnail.jpeg', 274, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9v294', '9v294', 'Tópicos em saúde, ambiente e trabalho: um olhar ampliado', NULL, '["Rita de Cássia Pereira Fernandes","Mônica Angelim Gomes de Lima","Tânia Maria de Araújo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', '“Padrões de saúde e qualidade de vida das populações são estabelecidos por redes complexas de relações entre produção e ambiente”. A obra tem como objetivo explorar e descrever as condições de trabalho distintas, afetando a gênese e a permanência dos problemas de saúde gerados entre os trabalhadores do estado da Bahia e seus familiares. É uma apresentação de realidades diversas que permitem observar a diversidade do mundo que nos cerca (envolvendo a produção e o ambiente) e seus impactos na saúde.', '["occupational health","working conditions","environmental health","health and environment","quality of life","workers'' families","health problems","Bahia"]', '10.7476/9786556300122', '9786556300122', 'https://books.scielo.org/id/9v294', 'https://books.scielo.org/id/9v294/pdf/fernandes-9786556300122.pdf', NULL, 'https://books.scielo.org/id/9v294/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9vwbk', '9vwbk', 'Educação inclusiva: formação e experiências', NULL, '["Antonilma Santos Almeida Castro","Edinalma Rosa Oliveira Bastos","Zenilda Fonseca de Jesus Souza"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Educação Inclusiva: formação e experiências traz para o leitor discussões sobre a formação docente relacionadas às experiências vivenciadas no âmbito da educação inclusiva, centralizando como eixo discursivo os contextos educacionais, incluindo a classe hospitalar, considerando-os espaços para construção de múltiplos saberes. É colocado em pauta também o diálogo entre educação e saúde, compreendendo tais instâncias como territórios de aprendizagens.', '["inclusive education","teacher professional development","hospital classrooms","education and health","learning spaces","teacher experiences"]', '10.7476/9786589524908', '9786589524908', 'https://books.scielo.org/id/9vwbk', 'https://books.scielo.org/id/9vwbk/pdf/castro-9786589524908.pdf', NULL, 'https://books.scielo.org/id/9vwbk/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9wgnc', '9wgnc', 'Gênero televisivo e modo de endereçamento no telejornalismo', NULL, '["Itânia Maria Mota Gomes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Duarte Oliveira acompanha as transformações ocorridas no período de 2004 e 2005 no programa veiculado pela TV Record, buscando compreender como o programa se configura na articulação entre dois subgêneros da programação jornalística, o telejornal e o programa temático.O Cidade Alerta, com sua ênfase na produção de notícias sobre violência urbana, polícia e segurança, com uma cobertura marcadamente sensacionalista, apresenta-se como um telejornal policial.A vinheta, o cenário, as cores, os enquadramentos de câmera, a performance cênica do apresentador e suas estratégias verbais de interpelação da audiência, o bom relacionamento construído com o meio policial, o que lhe garante vários "furos" e a possibilidade de acompanhar e transmitir ao vivo ações policiais, algumas delas programadas para acontecer no horário da transmissão do programa, são aspectos que, articulados no Cidade Alerta, constroem para o programa um lugar de juiz da sociedade: seja substituindo ou tentando substituir as instituições do judiciário, seja assumindo o papel do próprio Estado, que controla e disciplina os desvios sociais, o Cidade Alerta propõe um pacto com a audiência de um jornalismo de vigilância, denúncia e prestação de serviço.A relação que constrói com a audiência diz que ele está ali, vigilante, alerta, pronto a denunciar as falhas dos sistemas públicos e a alertar a sociedade sobre os riscos a que está sujeita.No capítulo 6, Marília Hughes Guerreiro Costa analisa um dos programas mais emblemáticos do telejornalismo brasileiro e também um dos mais antigos ainda em exibição na grade de oferta televisiva atual.O Globo Repórter, que teve sua primeira transmissão em abril de 1973, só perde, em tempo de duração na grade da TV aberta brasileira para o Jornal Nacional, da mesma emissora, a TV Globo.Para compreender O modo de endereçamento do Globo Repórter, a autora faz uma avaliação histórica do programa, tomando em análise três momentos distintos: os anos iniciais, na década de 70; os anos 80, que marcam uma série de alterações técnicas, econômicas e de linguagem; e o ano de 2008, percorrendo um período de 35 anos de programa.O Globo Repórter tem seus anos iniciais marcados pela colaboração de vários cineastas, a maioria deles vindos de uma experiência com o Cinema Novo, o que represen- Metodologia de Análise de Telejornalismo 1Itania Maria Mota Gomes INTRODUÇÃO A importância que a televisão assume no Brasil ainda não produziu, como resultado, o desenvolvimento de métodos de análise adequados de seus produtos.O mais frequente é que a televisão seja tomada a partir de abordagens mais gerais, macroeconômicas, históricas ou sociais, e que o programa televisivo, enquanto um produto cultural com certas especificidades, seja deixado de lado.Na maior parte dos casos, os estudos que tomam a televisão como seu objeto de investigação, ainda que considerem seus produtos, tendem a se dispersar em direção a outros objetos de análise, afastando-se da análise dos programas efetivamente produzidos e veiculados.No caso do telejornalismo, a situação parece se agravar.Tais estudos têm o mérito de reconhecer a televisão como objeto de interesse científico e de produzir conhecimento relevante sobre a televisão no Brasil, em especial quanto ao seu caráter histórico, social e econômico, mas a pouca ênfase nos produtos televisivos, tomados eles mesmos como objeto empírico, tem resultado numa certa fragilidade teórica e metodológica, quando se trata de descrever, analisar, interpretar os modos de funcionamento, as especificidades, as características do programa televisivo 2 .', '["television journalism","television genres","modes of address","Roda Viva","Fantástico","police journalism","sensationalism","audience relations","Rede Globo","Jornal Nacional","Brazilian television news","1970s"]', '10.7476/9788523211998', '9788523207977', 'https://books.scielo.org/id/9wgnc', 'https://books.scielo.org/id/9wgnc/pdf/gomes-9788523211998.pdf', NULL, 'https://books.scielo.org/id/9wgnc/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9wnw8', '9wnw8', 'Usos da Linguagem dos Riscos: das certezas passadas às imponderabilidades contemporâneas', NULL, '["Mary Jane Paris Spink"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, '2024-12-10', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O objetivo principal deste livro é sistematizar as teorizações sobre o uso da linguagem dos riscos em diferentes campos de saber – da ciência, do governo e do senso comum –, com base em pesquisas realizadas em um percurso que teve início quando era vital o enfrentamento da epidemia do HIV/aids, na década de 1990.', '["risk communication","risk discourse","HIV/AIDS epidemic","official discourse","scientific discourse","common sense","uncertainty"]', '10.7476/9786557081969', '9786557081983', 'https://books.scielo.org/id/9wnw8', NULL, NULL, 'https://books.scielo.org/id/9wnw8/cover/cover_thumbnail.jpeg', 283, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9wss4', '9wss4', 'La gestión social en rehabilitación. Un enfoque emergente en salud pública para la fisioterapia', NULL, '["Daiana Alexandra Camargo Rojas","García Sánchez","Margin del Socorro Martínez-Matheus","María Fernanda Díaz Muñoz"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'La gestión social ha sido asumida por el grupo de investigación Ciencias de la Rehabilitación como un proceso de acciones y toma de decisiones que hay que recorrer desde el abordaje de un problema, su estudio y comprensión, hasta el diseño y la implementación de propuestas, acordes con las realidades de los contextos (Cruz; Hernández; Ríos; Garzón, Álvarez, 2009). Dicho proceso requiere del aprendizaje continuo y en conjunto de los grupos sociales, que les permita tener una incidencia política; en definitiva la gestión social es una estrategia política que articule a la sociedad civil con el estado y con las instituciones, para la transformación de realidades. Esta estrategia incorporada en los programas de fisioterapia, fonoaudiología y terapia ocupacional de la Universidad del Rosario como una de las áreas de profundización, ha sido fundamentada y actualizada de acuerdo a los cambios sociales, políticos e investigativos, que afectan su conceptualización. Por ello, esta obra busca conceptualizar el área de profundización en gestión social en rehabilitación, específicamente desde el programa de fisioterapia, reconociendo los avances epistemológicos y praxiológicos y permitiendo un dialogo entre el concepto propiamente dicho, las nociones de salud pública, las competencias y estrategias pedagógicas para la formación en el área y el enfoque investigativo.', '["social management","rehabilitation","public health","physiotherapy education","curriculum development","teaching methods","professional competence","civil society","Colegio Mayor de Nuestra Señora del Rosario"]', '10.7476/9789587386325', '9789587386318', 'https://books.scielo.org/id/9wss4', NULL, NULL, 'https://books.scielo.org/id/9wss4/cover/cover_thumbnail.jpeg', 101, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9x87c', '9x87c', 'A política externa brasileira e a UNASUL: geopolítica e expansão do capitalismo brasileiro na América do Sul', NULL, '["Tiago Nery"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Investiga a tensão entre a dimensão política e econômica da política externa brasileira, em período marcado pela ascensão das forças progressistas em diferentes países sul-americanos, na primeira década do século XXI. A análise efetua-se ao nível macro, sistêmico, da relação entre Estado e capitalismo, na dimensão regional, entre os projetos políticos de regionalismo e a expansão do capitalismo brasileiro na América do Sul, e ao nível micro, nacional, entre as orientações de política externa das distintas coalizões políticas e o modelo de desenvolvimento dominante. Com esse recorte temporal, o autor propõe uma reflexão sobre as mudanças na América do Sul, e especialmente no Brasil, destacando a criação da União das Nações Sul-Americanas (Unasul) como expressão das políticas sociais inclusivas e políticas externas autônomas adotadas. A obra inclui ainda um olhar sobre o momento atual, com a perda da arquitetura institucional sul-americana construída em governos anteriores e o refluxo dos investimentos internacionais de empresas brasileiras envolvidas nos processos da Lava Jato, entre outros aspectos.', '["Brazilian foreign policy","UNASUR","geopolitics","Brazilian capitalism","regionalism","state-capital relations","development models","Operation Car Wash","21st century"]', '10.7476/9786587949192', '9786587949192', 'https://books.scielo.org/id/9x87c', 'https://books.scielo.org/id/9x87c/pdf/nery-9786587949192.pdf', NULL, 'https://books.scielo.org/id/9x87c/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9xfzt', '9xfzt', 'Crianças, adolescentes e crack: desafios para o cuidado', NULL, '["Simone Gonçalves de Assis"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O crack é uma droga de rápida absorção que causa impacto instantâneo na saúde global dos usuários e provoca comprometimento clínico e psiquiátrico. Este livro aborda o consumo da droga por crianças e adolescentes e as consequências que sofrem devido ao uso da substância por pais ou responsáveis. A obra reúne dez capítulos e tem por base os resultados de duas pesquisas realizadas pela Fundação Oswaldo Cruz. Os autores atuam em diferentes campos de conhecimento e dão à obra uma visão interdisciplinar sobre o assunto. Eles buscaram identificar quantos e quem são esses jovens indivíduos e traçar um perfil deles, além de refletir sobre as formas de atenção existentes em algumas cidades brasileiras. Para a organizadora, o crack é um problema de saúde pública que afeta diversas famílias brasileiras, “mais pelos impactantes efeitos provocados nos indivíduos e na sociedade, do que necessariamente pelos números alcançados. Nos estudos que aferem prevalência existente no país, o uso do crack tende a atingir algo em torno de 1% da população em geral, enquanto outros problemas como, por exemplo, o uso de álcool, abrangem proporções muito maiores”.', '["crack cocaine","children and adolescents","substance use","parental drug use","family impact","public health","care and treatment","youth profile"]', '10.7476/9788575415542', '9788575415542', 'https://books.scielo.org/id/9xfzt', 'https://books.scielo.org/id/9xfzt/pdf/assis-9788575415542.pdf', NULL, 'https://books.scielo.org/id/9xfzt/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9xnbf', '9xnbf', 'Crimes de feminicídio no enquadramento midiático: o que não é nominado não existe (Brasil, 2015-2018)', 'o que não é nominado não existe (Brasil, 2015-2018)', '["Lourdes Maria Bandeira"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Enquanto professora universitária por 44 anos, dos quais 30 foram exercidos no Departamento de Sociologia da Universidade de Brasília, dedicados aos trabalhos de pesquisa na área da violência contra as mulheres e de gênero, a professora Lourdes Maria Bandeira sistematizou suas últimas pesquisas neste livro. Este trabalho representa quatro anos de pesquisa e de seu compromisso institucional com o Departamento de Sociologia da Universidade de Brasília. Esta pesquisa representou a conclusão da sua vida acadêmica, uma vez que se aposentou em outubro de 2020 e deixou como legado a formação de dezenas de estudantes orientadas/os nessa área de pesquisa, muitas/os das/os quais foram suas/seus colegas na UnB, como também em outras universidades. O texto é atual ao tratar da morte violenta de mulheres, fenômeno persistente, cuja importância efetivou a criação, na Câmara Legislativa do DF, da Comissão Parlamentar de Inquérito dos Crimes de Feminicídio no DF. Os resultados são assustadores, dada a persistência do crime que atinge as mulheres, o que enfatiza a atualidade e a necessidade de pesquisa sobre o tema. A complexidade dos dados e sua pertinência atual tomaram corpo maior do que o esperado pela própria autora, e culminaram na produção desta obra.', '["femicide","media framing","violence against women","gender","parliamentary inquiry commission","Distrito Federal","gender-based violence"]', '10.7476/9786558462767', '9786558460688', 'https://books.scielo.org/id/9xnbf', NULL, NULL, 'https://books.scielo.org/id/9xnbf/cover/cover_thumbnail.jpeg', 553, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9yf86', '9yf86', 'Partidos, ideologia e composição social: um estudo das bancadas partidárias na Câmara dos Deputados', NULL, '["Leôncio Martins Rodrigues"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este trabalho tem como objeto principal a composição social das bancadas na Câmara dos Deputados de seis dos principais partidos brasileiros. Entendemos que os resultados da pesquisa indicaram que há uma relação consistente e coerente entre os meios socio-ocupacionais de recrutamento partidário e as orientações político-programáticas dos partidos na escala ideológica direita-centro-esquerda. Complementarmente, o exame das configurações partidárias resultantes das eleições de 1990, 1994 e 1998 mostrou um quadro multipartidário relativamente estável, com avanços mais fortes das correntes de centro, perdas pequenas da direita e ganhos também pequenos da esquerda.', '["Chamber of Deputies","political ideology","party recruitment","Brazilian political parties","party system","center-right","centre-left"]', '10.7476/9788579820250', '9788579820250', 'https://books.scielo.org/id/9yf86', 'https://books.scielo.org/id/9yf86/pdf/rodrigues-9788579820250.pdf', NULL, 'https://books.scielo.org/id/9yf86/cover/cover_thumbnail.jpeg', NULL, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9ynp9', '9ynp9', 'Fúria narcísica entre alunos e professores: as práticas de cyberbullying e os tabus presentes na profissão de ensinar', NULL, '[]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', '[RETIRADO/WITHDRAWN] Na sociedade atual, na qual impera a concentração dispersa – ou seja, a concentração que dificilmente consegue se fixar o tempo necessário para que haja aprendizado profundo, pois a dispersão se torna seu principal componente –, os alunos canalizam a raiva de terem de se concentrar em conteúdos aprendidos no profissional que, historicamente, sempre exigiu tal comportamento: o professor. Diante das práticas de cyberbullying contra professores, o autor do livro analisa o modo como tabus contra a profissão de ensinar são hoje revitalizados, ao mesmo tempo em que pondera sobre como o professor poderia agir para que deixasse de se tornar alvo das agressões online dos alunos, reconfigurando-se como figura de autoridade na chamada cultura digital.', '["cyberbullying","teachers","students","narcissism","taboos","teaching profession","online aggression","digital culture","teacher authority","attention and concentration"]', '10.7476/9786586768459', '9786586768459', 'https://books.scielo.org/id/9ynp9', 'https://books.scielo.org/id/9ynp9/pdf/zuin-9786586768459.pdf', NULL, 'https://books.scielo.org/id/9ynp9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9yvv2', '9yvv2', 'A democracia impressa: transição do campo jornalístico e do político e a cassação do PCB nas páginas da grande imprensa, 1945-1948', NULL, '["Heber Ricardo da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A democracia impressa: transição do campo jornalístico e do político e a cassação do PCB nas páginas da grande imprensa brasileira (1945-1948) analisa historicamente os posicionamentos da imprensa brasileira acerca da cassação do PCB e de seus mandatos durante a vigência do regime democrático inaugurado com a Constituição de 1946. Ancorado numa ampla investigação de jornais paulistas e cariocas - O Estado de S. Paulo, Folha da Manhã e Diário de S. Paulo, Correio da Manhã, O Globo e Jornal do Brasil - o livro desvenda as relações e o papel da imprensa como agente político na passagem do regime estadonovista à nova ordem democrática, época igualmente de transição de um jornalismo ligado a grupos políticos específicos para um modelo jornalístico empresarial. Concebendo os jornais não apenas como fonte de pesquisa, mas também como objeto de estudo, uma vez que, são produtores de acontecimentos políticos, a obra caracteriza as concepções democráticas dos periódicos analisados, bem como as ligações entre as folhas e os demais agentes políticos, além de entender as relações existentes dentro da própria empresa jornalística', '["Brazilian press","Brazilian Communist Party","press and politics","economic journalism","O Estado de S. Paulo","O Globo","Jornal do Brasil","Correio da Manhã","1946 Constitution","democratic transition","São Paulo newspapers","Rio de Janeiro newspapers"]', '10.7476/9788579830129', '9788579830129', 'https://books.scielo.org/id/9yvv2', 'https://books.scielo.org/id/9yvv2/pdf/silva-9788579830129.pdf', NULL, 'https://books.scielo.org/id/9yvv2/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9zhsp', '9zhsp', 'Suicídio revolucionário: a luta armada e a herança da quimérica revolução em etapas', NULL, '["Claudinei Cássio de Rezende"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com o objetivo de dilucidar o processo de exaurição da esquerda comunista no Brasil, esta dissertação analisa o construto acerca da teoria da revolução social na esquerda derrotada pela ditadura bonapartista, colocando em relevo a última fase do pensamento de Carlos Marighella. Perdendo pela primeira vez e definitivamente a hegemonia na esquerda comunista após a instauração, em 1964, da ditadura militar, o Partido Comunista Brasileiro (PCB) congregou a última esquerda comunista organizada – objetivando a revolução social – que ainda mantinha substantiva inserção sindical, apoio das classes subalternas e posição de centro gravitacional dos movimentos sociais. Ao entrar em processo de depleção após a exacerbação da repressão, o PCB se diluiu numa constelação de agremiações que intempestivamente se desvincularam do interlocutor racional do trabalho, provocando nos movimentos sociais uma ablação do partido. Coordenando a imersão geral da esquerda comunista na luta armada, Carlos Marighella estruturou a Ação Libertadora Nacional (ALN), a mais substantiva facção oriunda da fratura pecebista. Por influência da então recente Revolução Cubana e por imposição violenta da ditadura, a ruptura tática efetuada por Marighella teve como princípio seu descrédito diante das organizações partidárias, motivando a sua convicção de que a guerra de guerrilhas nutriria a vanguarda da revolução brasileira. A análise imanente da integralidade dos escritos de Carlos Marighella desvela que sua inflexão que rumou em oposição à matriz tática pecebista – tática que o partido seguia pelo menos desde sua Declaração de Março de 1958, ancorada na orientação soviética da revolução pacífica e do binômio proletariado–burguesia – não experimentara um rompimento de aporte estratégico, retendo intacto o núcleo teórico pecebista mais infesto: a quimérica...', '["Carlos Marighella","Brazilian Communist Party","armed struggle","guerrilla warfare","communist left","Brazilian military dictatorship","Cuban Revolution","social revolution","revolutionary theory","social movements","trade unions","1964 coup"]', '10.7476/9788579830822', '9788579830822', 'https://books.scielo.org/id/9zhsp', 'https://books.scielo.org/id/9zhsp/pdf/rezende-9788579830822.pdf', NULL, 'https://books.scielo.org/id/9zhsp/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-9zzts', '9zzts', 'O Estado da Arte sobre Refugiados, Deslocados Internos, Deslocados Ambientais e Apátridas no Brasil: atualização do Diretório Nacional do ACNUR de teses, dissertações, trabalhos de conclusão de curso de graduação em João Pessoa (Paraíba) e artigos (2007 a 2017)', NULL, '["Andrea Pacheco Pacífico","Andrezza Teles Pinheiro","Júlia Patrícia Ferreira de Vasconcelos Granja","Adolfino Varela"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O escritório do Alto Comissariado das Nações Unidas para Refugiados (ACNUR) no Brasil celebrou, em 2019, os quinze anos da Cátedra Sérgio Vieira de Mello. Foi um momento opor­tuno para resgatar a memória das principais ações e produ­ções em prol da população que buscou o Brasil como país de proteção, e, ao mesmo tempo, inaugurar um momento de respostas para os desafios do presente, buscando a construção de um futuro mais acolhedor para pessoas refugiadas, deslocadas, apátridas e tan­tas outras que precisaram deixar suas casas para poderem viver uma vida normal aqui no país. O propósito deste livro é apresentar e discutir os resultados de uma pesquisa que mapeou o estado da arte sobre refugiados, deslocados internos, deslocados ambien­tais e apátridas, a partir da produção acadêmica divulgada entre 2007 e 2017. Em se tratando de recorte temporal, a crise financeira de 2007, na Europa, trouxe mudanças drásticas na migração mundial, par­ticularmente, entre 2007 e 2011, quando um grande número de migrantes irregulares do Oriente Médio, da África e do Sul da Ásia tentaram entrar na Europa via Turquia e Grécia. Enquanto isso, o Brasil, em 2007, celebrava os dez anos de criação da avançada lei de proteção aos refugiados (Lei 9474/97), em que ampliava a definição da Convenção da ONU de 1951, considerando também como refugiado aquele que estava fora de seu país de origem por violação maciça e generalizada aos direitos humanos (art. 1º, III)', '["refugees","internally displaced persons","environmental displacement","statelessness","2008 financial crisis","João Pessoa"]', '10.7476/9786587171128', '9786587171128', 'https://books.scielo.org/id/9zzts', 'https://books.scielo.org/id/9zzts/pdf/pacifico-9786587171128.pdf', NULL, 'https://books.scielo.org/id/9zzts/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b23ds', 'b23ds', 'Ideologia e populismo Adhemar de Barros Miguel Arraes Carlos Lacerda Leonel Brizola', NULL, '["Guita Grin Debert"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro tem o sabor de uma aventura. Seu caminho é a estreita área comum que se delineia entre as técnicas estruturalistas de análise do discurso e a problemática posta pelos trabalhos políticos sobre o populismo.[...][trecho retirado da apresentação do livro]', '["populism","ideology","political discourse","discourse analysis","Carlos Lacerda","Leonel Brizola","Brazilian politics"]', '10.7476/9788599662724', '9788599662724', 'https://books.scielo.org/id/b23ds', 'https://books.scielo.org/id/b23ds/pdf/debert-9788599662724.pdf', NULL, 'https://books.scielo.org/id/b23ds/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b25q7', 'b25q7', 'Ilegalidad aparente o violación permanente: los derechos de autor y las tecnologías P2P', NULL, '["Édgar Iván León Robayo","Eduardo Varela Pezzano"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Durante las dos últimas décadas, el mundo ha sido testigo de cómo la protección jurídica debida a las creaciones del talento humano se encuentra en crisis, dada la expansión global de las telecomunicaciones a través de Internet. La posibilidad de realizar descargas directas de contenidos alojados en discos duros, servidores o, incluso, en la nube, modificó de manera abrupta el comportamiento social, permitiéndole a cualquier internauta obtener canciones, películas, videos o software, entre otros, sin necesidad de reconocer derechos a sus creadores. Millones de dólares en pérdidas dieron lugar a que la industria del entretenimiento buscara solución a este problema por medio de mecanismos de protección jurídica en contra de los usuarios de estos programas, con el objeto de impedir el constante enriquecimiento de los infractores. Lastimosamente, en ocasiones, estas medidas resultaron excesivas y los procedimientos solo han dado lugar a sentimientos de rechazo por parte del público y a una mala prensa. De igual manera se implementaron mecanismos tecnológicos que les permitieran a los autores obtener protección respecto de sus obras. Aunque con la implementación de otras medidas como la puesta en vigencia de normas o la posibilidad de pagar tarifas mínimas para tener acceso a las obras se creyó que los autores encontraban protección, esto realmente no ocurrió. La facilidad en el uso de estos programas permite perpetrar estas conductas de manera gratuita, pues basta simplemente conectar un computador a Internet para alcanzar el objetivo. Esta obra analiza los problemas que suscitan la utilización de la tecnología a través de redes P2P, el derecho a la cultura y a protección de los derechos de los titulares de obras protegidas.', '["copyright infringement","peer-to-peer networks","copyright protection","cultural rights","intellectual property","copyright holders'' rights","digital distribution","entertainment industry","legal protection of authors","technological protection measures"]', '10.7476/9789587386424', '9789587386417', 'https://books.scielo.org/id/b25q7', NULL, NULL, 'https://books.scielo.org/id/b25q7/cover/cover_thumbnail.jpeg', 100, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b27wf', 'b27wf', 'Mãos à obra, Brasil: proposta de governo', NULL, '["Fernando Henríque Cardoso"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O Brasil é um país em mudança dentro de um mundo em mudança. Hoje nós temos uma escolha a fazer. Podemos nos deixar levar pelas mudanças como numa enxurrada. Ou podemos nos organizar melhor e confiar na nossa capacidade de construir o futuro com as próprias mãos. [trecho retirado da apresentação do livro]', '["government proposal","political program","social change","national development","political leadership"]', '10.7476/9788599662663', '9788599662663', 'https://books.scielo.org/id/b27wf', 'https://books.scielo.org/id/b27wf/pdf/cardoso-9788599662663.pdf', NULL, 'https://books.scielo.org/id/b27wf/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b2bzp', 'b2bzp', 'Sansón y la lechuza. Relatos quechuas de Hancavelica, Perú', NULL, '["Pablo Landeo Muñoz"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2023, '2023-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '1er. Premio en Documentación lingüística. El presente corpus de relatos de tradición oral quechua fue recopilado a partir de 2016, principalmente en las comunidades de los distritos de Lircay, Anchonga y Acobamba (Huancavelica, Perú). Esta obra representa la devolución del autor a la comunidad, siguiendo el principio de reciprocidad andina, al compartir los relatos recopilados y la información que sirvió de base para su tesis doctoral en la Sorbona (París) en 2021. La metodología se sustenta en la etnografía del relato que considera los siguientes aspectos: transcripción y traducción de textos a partir de archivos de voz de cinco narradores, inmersión en la actividad cotidiana de los narradores, inesperados y atención al contexto narrativo. Además incorpora la perspectiva del investigador, quien se guía por las dudas de su infancia vivida en el entorno comunal. Luego de 18 días de paro nacional y atendiendo al llamado de los representantes de las organizaciones sociales, la iglesia, a través de la Conferencia Episcopal Ecuatoriana, aceptó intervenir para encontrar un camino de paz y reconciliación para el país. Estas páginas hacen pública, de manera sistemática y ordenada, los documentos que han sido parte de este proceso. Los Documentos preliminares que llevaron a las partes a instalar mesas de diálogo; el Acta de la paz con la transcripción de las intervenciones de cada uno de los líderes de las organizaciones sociales e indígenas, así como de la CEE y el ministerio de Gobierno durante la firma del Acta de la paz (30 de junio de 2022); la Hoja de ruta con los compromisos básicos para garantizar las condiciones de un diálogo con resultados; el Desarrollo de las demandas que fueron presentadas por organizaciones sociales e indígenas a las instancias gubernamentales al inicio de las sesiones; los Documentos del proceso de seguimiento, con la metodología de seguimientos de los compromisos del gobierno. También recoge los actores, instituciones, facilitadores, cofacilitadores, relatores y corelatores de cada mesa. Esta publicación tiene un valor histórico enorme, tanto para el presente cuanto para el futuro. Su consideración y análisis consolidará prácticas que favorezcan la paz a través de la mediación en escenarios de conflictos sociopolíticos.', '["Indigenous storytelling","peace dialogue","Andean cosmology","Andean spirituality","Andean medicine","Andean ritual"]', '10.7476/9789942099389', '9789942099099', 'https://books.scielo.org/id/b2bzp', NULL, NULL, 'https://books.scielo.org/id/b2bzp/cover/cover_thumbnail.jpeg', 538, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b2fzp', 'b2fzp', 'Ditaduras militares: Brasil, Argentina, Chile e Uruguai', NULL, '["Rodrigo Patto Sá Motta"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os autores desta coletânea são pesquisadores brasileiros, argentinos, chilenos e uruguaios, especialistas na história das ditaduras recentes. Os textos contemplam temas consolidados na pesquisa acadêmica e, também, novas linhas de investigação, em combinação muito fértil. O leitor encontrará nestas páginas estudos sobre aspectos essenciais do tema: as disputas no campo da memória, as políticas sociais, culturais e educacionais das ditaduras, os embates no campo artístico-cultural e o funcionamento dos aparatos repressivos.', '["military dictatorship","Brazil","Argentina","Chile","memory politics","social policy","cultural policy","education policy"]', '10.7476/9786558580812', '9788542300697', 'https://books.scielo.org/id/b2fzp', NULL, NULL, 'https://books.scielo.org/id/b2fzp/cover/cover_thumbnail.jpeg', 338, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b2n8w', 'b2n8w', 'Patrimônio, território e turismo no Brasil, Costa Rica e Itália', NULL, '["Marafon, Glaucio José","Faccioli, Marina","Sánchez, Meylin Alvarado"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Propõe diferentes perspectivas relacionadas aos estudos de patrimônio territorial e turismo no Brasil, na Costa Rica e na Itália. Os autores são professores do Instituto de Geografia da UERJ, da Faculdade de Ciências Geográficas da Universidade da Costa Rica e da Universidade Tor Vergata (Roma 2). Apresentada no idioma original dos autores (português, espanhol e italiano), a obra revela os temas de interesse e as abordagens desenvolvidas pelos pesquisadores em seus respectivos países, sob o prisma da geografia do turismo. O livro é fruto das atividades desempenhadas no contexto dos acordos de cooperação firmados pela UERJ com a Universidade da Costa Rica e com a Universidade Tor Vergata. Além dos aspectos evidenciados, o conteúdo reflete as singularidades do desenvolvimento dos estudos de patrimônio territorial no contexto socioeconômico e cultural de cada país.', '["territorial heritage","heritage tourism","tourism geography","territory","comparative heritage studies","Brazil","Costa Rica","Italy"]', '10.7476/9786500030327', '9786500030327', 'https://books.scielo.org/id/b2n8w', 'https://books.scielo.org/id/b2n8w/pdf/marafon-9786500030327.pdf', NULL, 'https://books.scielo.org/id/b2n8w/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b37sm', 'b37sm', 'A formação ética dos médicos: saindo da adolescência com a vida (dos outros) nas mãos', NULL, '["Sérgio Rêgo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Traz um estudo da realidade da formação ética dos futuros médicos nas escolas de medicina do Brasil, retratando as dificuldades que os jovens profissionais se deparam quando deixam de ser formalmente aprendizes e passam a responder moral, jurídica e socialmente pela vida de um semelhante. Leitura necessária para os envolvidos com a formação moral do futuro médico.', '["medical ethics education","medical students","moral responsibility","legal responsibility","social responsibility","medical schools","adolescence","professional identity"]', '10.7476/9788575413241', '9788575413241', 'https://books.scielo.org/id/b37sm', 'https://books.scielo.org/id/b37sm/pdf/rego-9788575413241.pdf', NULL, 'https://books.scielo.org/id/b37sm/cover/cover_thumbnail.jpeg', NULL, 32, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b3jpx', 'b3jpx', 'Televisão e realidade', NULL, '["Itânia Maria Mota Gomes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne os trabalhos apresentados nos painéis temáticos, pelos conferencistas convidados, e a conferência de abertura do Colóquio, realizada por François Jost, professor da Université Sorbonne Nouvelle/Paris III e diretor do Centre d’Etude des Images et des Sons Médiatiques (CEISME).', '["television","reality","media representation","François Jost"]', '10.7476/9788523208806', '9788523208806', 'https://books.scielo.org/id/b3jpx', 'https://books.scielo.org/id/b3jpx/pdf/gomes-9788523208806.pdf', NULL, 'https://books.scielo.org/id/b3jpx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b3rzk', 'b3rzk', 'História e comunicação na nova ordem internacional', NULL, '["Maximiliano Martín Vicente"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro estabelece pontos de encontro entre a História e a Comunicação, analisando a trajetória recente dessas duas áreas no intuito de identificar suas possibilidades de convergência. Indica também, por outro lado, a necessidade de se atentar para as diferenças entre ambas, sem que isso represente, necessariamente, um antagonismo irreversível. Privilegiando a História do Tempo Presente e as Teorias da Comunicação, o livro salienta a importância do diálogo entre historiadores e teóricos da comunicação. Segundo o autor, as duas áreas podem contribuir à sociedade como ferramentas de desconstrução de discursos, idéias e versões. Por meio de um estudo de caso - os atentados de 11 de setembro, noticiados pelos periódicos Veja e Le Monde Diplomatique - sua pesquisa evidencia a importância de alguns procedimentos usados na comunicação para a História do Tempo Presente', '["contemporary history","communication theory","historiography","September 11 attacks","Veja magazine","Le Monde Diplomatique","deconstruction of discourse","new international order","history of the present time"]', '10.7476/9788598605968', '9788598605968', 'https://books.scielo.org/id/b3rzk', 'https://books.scielo.org/id/b3rzk/pdf/vicente-9788598605968.pdf', NULL, 'https://books.scielo.org/id/b3rzk/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b4km4', 'b4km4', 'Sociedade política no Brasil pós-64', NULL, '["Bernardo Sorj","María Herminia Tavarés de Almeida"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[...] acreditamos que o livro constitui pelo menos um esforço no sentido de apresentar uma visão do conjunto e relativamente coerente das transformações em curso nas últimas duas décadas na sociedade brasileira. Nosso objetivo e desejo é que possa tornar-se referência e incentivo para novos e melhores estudos, capazes de proporcionar uma imagem sintética da complexa estrutura social brasileira. [trecho retirado da apresentação do livro]', '["post-1964 Brazil","social change","Brazilian society","social structure"]', '10.7476/9788599662632', '9788599662632', 'https://books.scielo.org/id/b4km4', 'https://books.scielo.org/id/b4km4/pdf/sorj-9788599662632.pdf', NULL, 'https://books.scielo.org/id/b4km4/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b4pn2', 'b4pn2', 'Política Cultural: conceito, trajetória e reflexões', NULL, '["Néstor García Canclini"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro foi concebido com o intuito de comemorar os 30 anos do conceito de política cultural de Néstor García Canclini, um clássico no campo de estudos da cultura. Os artigos que constituem a obra buscam refletir sobre a relevância das políticas culturais num cenário em que a própria ideia de nação é posta em xeque diante da potência dos grupos hegemônicos de cultura e comunicação e das novas formas de criatividade e consumo cultural possibilitadas pelas tecnologias. Em síntese, a publicação contribui para a consolidação acadêmica da política cultural e para a formação crítica daquelas(es) que atuam no âmbito da organização cultural no Brasil.', '["cultural policy","Néstor García Canclini","cultural consumption","cultural technology","nation and culture","cultural institutions","cultural studies"]', '10.7476/9786556300849', '9788523218928', 'https://books.scielo.org/id/b4pn2', NULL, NULL, 'https://books.scielo.org/id/b4pn2/cover/cover_thumbnail.jpeg', 159, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b4zpq', 'b4zpq', 'Modelagem matemática: perspectivas, experiências, reflexões e teorizações', NULL, '["Célia Finck Brandt","Dionísio Burak","Tiago Emanuel Klüber"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Essa nova edição mantém os capítulos da primeira, porém, sob outra estrutura, a partir da inclusão de cinco novos, totalizando doze que constituíram quatro núcleos: 1) Sobre a perspectiva de Modelagem, 2) Modelagem Matemática nos níveis e modalidades de ensino, 3) Modelagem Matemática e Formação de Professores, 4) Modelagem Matemática e Teorizações. A partir desses núcleos foi possível apresentar um novo subtítulo que expressa a sua unidade temática: Modelagem Matemática: perspectivas, experiências, reflexões e teorizações. Para além de um novo título, esse novo livro avança em questões pertinentes ao tema e, ao agregar os capítulos, permite efetuar reflexões mais robustas do ponto de vista de cada núcleo. Com isso, esperamos que essa obra traga as devidas contribuições a todos os interessados na prática e na pesquisa em Modelagem.', '["mathematical modeling","teacher professional development"]', '10.7476/9788577982325', '9788577982325', 'https://books.scielo.org/id/b4zpq', 'https://books.scielo.org/id/b4zpq/pdf/brandt-9788577982325.pdf', NULL, 'https://books.scielo.org/id/b4zpq/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b5b72', 'b5b72', 'A evolução histórica da ergonomia no mundo e seus pioneiros', NULL, '["José Carlos Plácido da Silva","Luís Carlos Paschoarelli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os conceitos e aplicações da ergonomia estão em constante discussão no âmbito acadêmico, caracterizando um corpus de conhecimento de grande expressividade para a própria ciência ergonômica e demais áreas tecnológicas correlatas, a saber: engenharias, design, arquitetura, entre outras.Mas entre as demandas para ampliar as análises em torno dessa disciplina apresenta-se sua evolução histórica, a qual está completa de controvérsias e discussões.De fato, há ainda uma grande dificuldade em relatar suas etapas históricas dentro do âmbito geográfico e a participação de seus precursores nessas fases.O propósito dessa coletânea foi o de reunir os estudos realizados pelos alunos da linha de pesquisa ergonomia, associados ao Laboratório de Ergonomia e Interfaces (LEI), no Programa de Pósgraduação em Design da Faculdade de Arquitetura, Artes e Comunicação da Universidade Estadual Paulista, e apresentar subsídios para ampliação da discussão e reflexão evolutiva da ergonomia.', '["history of ergonomics"]', '10.7476/9788579831201', '9788579831201', 'https://books.scielo.org/id/b5b72', 'https://books.scielo.org/id/b5b72/pdf/silva-9788579831201.pdf', NULL, 'https://books.scielo.org/id/b5b72/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b5jhm', 'b5jhm', 'A casa das mulheres n’outro terreiro: famílias matriarcais em Salvador', NULL, '["Maria Gabriela Hita"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra resulta de pesquisas realizadas no bairro Nordeste de Amaralina entre os anos de 1992 e 2003 em duas extensas redes de parentesco matriarcais chefiadas por duas avós e gira em torno de relações que expressão a díade Mãe-Filhos. A autora narra minuciosamente a história de duas senhoras afrodescendentes convidando o leitor a acompanhar cada trajetória da vida das personagens reais que integram o livro, mostrando as duras condições estruturais enfrentadas, desde a lenta ascensão socioeconômica dessas famílias que passam por obstáculos de viuvez, desemprego e violência doméstica até a criatividade das estratégias forjadas para enfrentá-las como o amor, a raiva, a luta, e a esperança.', '["matrilineal family","Afro-descendant women","grandmother","mother-child relationship","Salvador, Bahia","domestic violence","widowhood","unemployment","socioeconomic mobility","life trajectories","family resilience"]', '10.7476/9786556303741', '9788523211271', 'https://books.scielo.org/id/b5jhm', NULL, NULL, 'https://books.scielo.org/id/b5jhm/cover/cover_thumbnail.jpeg', 513, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b5k3s', 'b5k3s', 'A política pública como campo multidisciplinar', NULL, '["Eduardo Cesar Leão Marques","Carlos Aurélio Pimenta de Faria"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Muitas são as disciplinas que têm se dedicado ao estudo das ações do Estado, sobretudo a partir dos anos 1980, quando começaram a ganhar fôlego as pesquisas sobre as políticas públicas. Não só diferentes disciplinas se voltaram para esse campo, como os estudos passaram a focar uma grande variedade de temas. Se, por um lado, a pluralidade de olhares contribui para o avanço das pesquisas, por outro, a dispersão disciplinar e temática indica um risco de fragmentação do campo. A necessidade de sistematizar os estudos na área, mas sem abrir mão de um panorama abrangente, motivou o lançamento desta coletânea, que propõe um diálogo entre ciência política, sociologia, administração pública, antropologia, direito, psicologia, demografia, história e relações internacionais. Os capítulos apresentam as teorias e os enquadramentos conceituais que têm sido produzidos e utilizados por cada disciplina. O objetivo é que esse quadro favoreça uma interpretação colaborativa, construída sobre bases teóricas compartilhadas. Além das universidades e das diferentes esferas do governo, outros atores sociais também têm contribuído para o avanço desse campo. “No plano da sociedade, a instrumentalização do conhecimento científico tem sido uma constante por parte de ONGs e grupos de interesse, que não raro se tornam também produtores de conhecimento acerca das políticas públicas e dos problemas societários”, destacam os organizadores. O livro, portanto, é leitura fundamental para quem se interessa pelos desafios do Estado neste início de século e pelas distintas formas de compreensão das políticas públicas.', '["public policy","multidisciplinary approach","state action","conceptual framework","disciplinary fragmentation","non-governmental organizations","interest groups","state challenges","collaborative interpretation"]', '10.7476/9786557080825', '9788575415641', 'https://books.scielo.org/id/b5k3s', NULL, NULL, 'https://books.scielo.org/id/b5k3s/cover/cover_thumbnail.jpeg', 286, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b5prc', 'b5prc', 'Solidariedade e organizações: pensar uma outra organização', NULL, '["Genauto Carvalho de França Filho","Philippe Eynaud"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro parte de um diagnóstico crítico sobre a dupla insustentabilidade que tem caracterizado a dinâmica do desenvolvimento das sociedades contemporâneas: a crise ambiental e o aumento das desigualdades. Tais condições têm revelado um déficit de solidariedade tanto na relação dos seres humanos com a natureza, quanto na relação das pessoas entre si. É assim que o livro funda sua reflexão num paradoxo importante relativo ao lugar da solidariedade nas sociedades atuais: nunca antes houve tanta necessidade de fortalecê-la, tanto no plano nacional quanto internacional, e a reflexão a seu propósito jamais foi tão eludida, tão desconhecida, para não dizer tão desacreditada. Após salientar como a solidariedade foi invisibilizada na construção do conhecimento sobre as organizações e a gestão, o livro explora a emergência de práticas organizacionais inovadoras visando responder aos dilemas dessa dupla insustentabilidade. São os desafios e potencialidades contidos numa outra economia que nos convida a refletir sobre uma outra gestão.', '["solidarity","organizations","organizational management","environmental crisis","inequality","sustainability","human-nature relationship","alternative economy","critical management studies"]', '10.7476/9786556301990', '9786556301990', 'https://books.scielo.org/id/b5prc', 'https://books.scielo.org/id/b5prc/pdf/franca-9786556301990.pdf', NULL, 'https://books.scielo.org/id/b5prc/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b5pv2', 'b5pv2', 'Polícia e sociedade: gestão de segurança pública violência e controle social', NULL, '["Ivone Freire Costa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A gestão da segurança pública no Brasil é um debate que evidencia a relação entre Polícia e Sociedade. A visão apresentada neste livro acirra a discussão. Tendo como objeto de estudo a Polícia baiana, a autora Ivone Freire Costa focaliza as ações policiais no bairro da Liberdade - o conglomerado da violência e da criminalidade mais populoso e complexo da cidade de Salvador. Desta forma, são avaliadas a falta de confiança, o medo e a insegurança que permeiam a relação entre cidadãos e policiais. A principal finalidade da obra é incentivar a proposta de co-responsabilidade social entre Polícia e Sociedade de maneira positiva, harmônica e produtiva. É evidenciando as falhas na segurança pública e a crescente busca de conformidade social do cidadão no mundo do ilegal, que a autora sugere caminhos para o tão almejado pacto de paz.', '["public security management","police-community relations","social control","violence","crime"]', '10.7476/9788523212193', '9788523212193', 'https://books.scielo.org/id/b5pv2', 'https://books.scielo.org/id/b5pv2/pdf/costa-9788523212193.pdf', NULL, 'https://books.scielo.org/id/b5pv2/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b753r', 'b753r', 'Ilustres ordinários do Brasil', NULL, '["Jean Marcel Carvalho França"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro reúne ensaios sobre a história do Brasil a partir da descrição de uma galeria de tipos sociais e de tiques comportamentais que a sociedade brasileira construiu e consolidou para si ao longo do tempo. É, em outras palavras, um livro sobre pequenas permanências, sobre pequenos traços do país e do seu povo que, de tanto serem repetidos, lembrados, discutidos, por vezes cantados em verso e prosa, ganharam ares de verdade e produziram impactos sociocomportamentais mensuráveis.', '["Brazilian society","social types","behavioral characteristics","social stereotypes","national character","Brazilian people"]', '10.7476/9788595462809', '9788595462809', 'https://books.scielo.org/id/b753r', 'https://books.scielo.org/id/b753r/pdf/franca-9788595462809.pdf', 'https://books.scielo.org/id/b753r/epub/franca-9788595462809.epub', 'https://books.scielo.org/id/b753r/cover/cover_thumbnail.jpeg', 151, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b7kvj', 'b7kvj', 'Refugiados e políticas de exclusão: histórias do nazismo, holocausto e exílio no Brasil', 'histórias do nazismo, holocausto e exílio no Brasil', '["Cristiana Facchinetti","Pedro Felipe Muñoz","Maurício Parada"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Refugiados e Políticas de Exclusão: histórias do nazismo, Holocausto e exílio no Brasil reúne pesquisadores brasileiros e estrangeiros em uma análise refinada e interdisciplinar sobre o impacto da migração forçada de intelectuais e perseguidos políticos que refúgio no Brasil durante o regime nazista. Dividido em duas partes — uma voltada à história e à historiografia do nazismo e do Holocausto, e outra centrada na experiência brasileira — o livro combina reflexão teórica, pesquisa documental e perspectiva crítica sobre o passado e o presente. A obra permite ao leitor compreender a continuidade e a longa duração de certas tendências e de movimentos políticos, contribuindo também para análises contemporâneas sobre a mobilidade humana, a cidadania, a violência e a saúde. A obra é fruto da chamada pública Coletâneas Temas Inovadores , promovida pela Editora Fiocruz.', '["refugees","Nazi Germany","Holocaust","forced migration","political persecution","exclusion policies","citizenship","human mobility","violence","health","historiography of Nazism"]', '10.7476/9786557082904', '9786557082058', 'https://books.scielo.org/id/b7kvj', NULL, NULL, 'https://books.scielo.org/id/b7kvj/cover/cover_thumbnail.jpeg', 330, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b7ppv', 'b7ppv', 'Análise política em saúde: a contribuição do pensamento estratégico', NULL, '["Leonardo Federico"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Concentrando-se na leitura e interpretação de Pensamento Estratégico e Lógica da Programação, obra de Mario Testa, o título recupera a perspectiva hermenêutica e a contribuição das teorias de autores como Bourdieu e Gramsci para discutir o planejamento em saúde. O autor comenta também o processo de elaboração teórica que Testa empreendeu para distanciar-se da lógica normativa da programação tradicional.', '["strategic thinking","health planning","hermeneutics","Pierre Bourdieu","Antonio Gramsci","normative logic","health policy"]', '10.7476/9788523220006', '9788523214166', 'https://books.scielo.org/id/b7ppv', NULL, NULL, 'https://books.scielo.org/id/b7ppv/cover/cover_thumbnail.jpeg', 286, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b7spy', 'b7spy', 'A pluriatividade na agricultura familiar', NULL, '["Sérgio Schneider"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro se propõe a examinar as relações da agricultura familiar com a emergência e a consolidação das atividades não-agrícolas no espaço rural e a formação de unidades produtivas crescentemente identificadas com a pluriatividade das famílias rurais. Neste sentido, agrega-se, às pesquisas que vêm sendo realizadas para aprofundar os conhecimentos sobre a agricultura familiar e suas possibilidades de desenvolvimento social e econômico no espaço rural. Nos anos recentes, vários cientistas sociais vêm dedicando seus estudos e análises às formas familiares. Esse trabalho intelectual tem sido desenvolvido sob variados focos, podendo-se extrair pelos menos dois ensinamentos. O primeiro indica a existência de diferentes estratégias sociais e econômicas através das quais as populações, grupos e indivíduos identificados com a agricultura familiar vêm viabilizando sua reprodução social e sobrevivência econômica nas sociedades contemporâneas. O segundo e maior aprendizado demonstra que, pelo menos nas nações mais desenvolvidas, o Estado tem sido o maior responsável pela manutenção de políticas públicas e formas de apoio à expansão e à consolidação das unidades que se organizam e estruturam com base no trabalho familiar. A presente obra situa-se no primeiro veio citado, alinhando-se às pesquisas cujo objetivo tem sido o de demonstrar os mecanismos e as estratégias que viabilizam, e em certos casos até ampliam e fortalecem, as formas familiares no campo.', '["family farming","pluriactivity","rural households","family forms","social reproduction","economic survival","rural development"]', '10.7476/9788538603894', '9788538603894', 'https://books.scielo.org/id/b7spy', 'https://books.scielo.org/id/b7spy/pdf/schneider-9788538603894.pdf', NULL, 'https://books.scielo.org/id/b7spy/cover/cover_thumbnail.jpeg', NULL, 336, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b8jj5', 'b8jj5', 'Universos da arte', NULL, '["Fayga Ostrower"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro Fayga Ostrower analisa obras de arte usando os princípios da linguagem visual e mostra como todo artista é fruto das influências que busca, bem como de seu tempo histórico. O livro tem mais de 300 ilustrações, sendo 118 esquemas que exemplificam os conceitos de composição e 188 reproduções de obras datadas desde a pré-história até os dias de hoje. Quem teve o privilégio de assistir às aulas de Fayga reconhece aqui sua forma de falar: a linguagem simples para explicar problemas complexos e a profunda crença de que arte e experiência de vida se misturam.', '["visual language","art history","composition","artistic influence","historical context of art","prehistoric art","Fayga Ostrower"]', '10.7476/9788526814745', '9788526810181', 'https://books.scielo.org/id/b8jj5', NULL, NULL, 'https://books.scielo.org/id/b8jj5/cover/cover_thumbnail.jpeg', 510, 73, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b8n7j', 'b8n7j', 'Violência e cultura no Brasil', NULL, '["Rubén George Oliven"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O título deste livro — Violência e Cultura no Brasil — poderia levar o leitor a imaginar que estou procurando explicar a violência em nossa sociedade a partir de sua cultura. Trata-se, na verdade, de dois temas distintos que correspondem a meus interesses teóricos e às atividades de pesquisa que desenvolvo no Mestrado em Antropologia, Política e Sociologia da Universidade Federal do Rio Grande do Sul com o apoio desta Universidade, do CNPq (Conselho Nacional de Desenvolvimento Científico e Tecnológico) e da FINEP (Financiadora de Estudos e Projetos).', '["violence","culture","Brazilian society","anthropology of violence","sociology of violence","political anthropology"]', '10.7476/9788579820069', '9788579820069', 'https://books.scielo.org/id/b8n7j', 'https://books.scielo.org/id/b8n7j/pdf/oliven-9788579820069.pdf', NULL, 'https://books.scielo.org/id/b8n7j/cover/cover_thumbnail.jpeg', NULL, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b97mz', 'b97mz', 'O tecido do tempo: o patrimônio cultural no Brasil e a Academia Sphan: a relação entre modernismo e barroco', NULL, '["Mariza Veloso Motta Santos"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra suscita imediato interesse de antropólogos e sociólogos, pois as perguntas – o que preservar e por que preservar – exigem respostas baseadas em uma ordem de valores, impondo à reflexão conceitos como tempo, memória e história, que sustentam representações e constroem a teoria e a prática em torno do patrimônio cultural. Esta é uma pesquisa pioneira, um dos primeiros pilares plantados para a criação desse campo de estudos dentro das ciências sociais. Além de estudar a gênese de uma instituição cultural, Mariza Veloso faz uma leitura original do modernismo brasileiro, de seu vanguardismo singular que valoriza o novo e não abre mão da tradição, daquilo que tem valor histórico ou estético, do que uma sociedade não pode se esquecer. Um dos achados mais importantes da autora refere-se à compreensão da instituição entendida como Academia Sphan, pois ali produziram-se estudos, pesquisas, livros e ensaios sobre o patrimônio cultural. Outro achado importante é a relação original entre modernismo e barroco, homologias inusitadas entre dois momentos paradigmáticos da modernidade. A obra é também endereçada aos que se dedicam à história das ideias e ao pensamento social no Brasil. Por acrescentar conhecimento sobre o assunto, por munir de conceitos e argumentos aqueles que se interessam pelo tema, esta é referência básica e continuará a ser lida, citada e reproduzida por estudantes, pesquisadores e técnicos envolvidos no estudo do patrimônio material e imaterial.', '["cultural heritage","Brazilian modernism","Baroque","cultural heritage preservation","memory","time","history","cultural institutions","tangible and intangible heritage","intellectual history","vanguardism"]', '10.7476/9788523013493', '9788523012120', 'https://books.scielo.org/id/b97mz', NULL, NULL, 'https://books.scielo.org/id/b97mz/cover/cover_thumbnail.jpeg', 458, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-b9ydg', 'b9ydg', 'O antídoto do mal: crítica de arte e loucura na modernidade brasileira', NULL, '["Gustavo Henrique Dionísio"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'relata integralmente a sua experiência em Engenho de Dentro.', '["art criticism","madness","modernity","Brazilian modernism","madness in art","critique of modernity"]', '10.7476/9788575415443', '9788575415443', 'https://books.scielo.org/id/b9ydg', 'https://books.scielo.org/id/b9ydg/pdf/dionisio-9788575415443.pdf', NULL, 'https://books.scielo.org/id/b9ydg/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bbwrq', 'bbwrq', 'Novos horizontes entre a pandemia e pós-pandemia', NULL, '["Rocha, Sérgio Luiz Alves da","Andrade, Rogério Pelizzari de"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea reúne produções apresentadas nos Congressos da Intercom dos anos de 2022 e 2023 (44º e 45º Congresso Brasileiro de Ciências da Comunicação, respectivamente). Por conta das restrições sanitárias ainda vigentes à época, as atividades foram adaptadas para o formato híbrido, exigindo novas lógicas na organização, realização e participação dos congressistas. O resultado, além de um registro histórico de uma época ainda de difícil avaliação, há contribuições genuínas ao adensamento de teorias, construção de práticas e ideias de novos temas para futuras investigações na área da na área da Comunicação e Educação.', '["COVID-19 pandemic","hybrid conference","communication and education","conference organization","remote participation","post-pandemic"]', '10.7476/9788574556147', '9788574556048', 'https://books.scielo.org/id/bbwrq', 'https://books.scielo.org/id/bbwrq/pdf/rocha-9788574556147.pdf', NULL, 'https://books.scielo.org/id/bbwrq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bc2w8', 'bc2w8', 'El juez administrativo colombiano: ¿Un actor influyente en el fortalecimiento del Estado social y constitucional de derecho?', NULL, '["Indira Latorre"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Difícilmente se pondría en duda que el juez constitucional colombiano ha resultado ser un actor representativo e incluso simbólico del Estado social de derecho en Colombia. Por el contrario, no es tan fácil saber cuál es la imagen compartida que se tiene acerca del juez administrativo, en parte porque se investiga muy poco por los cambios que la justicia administrativa colombiana ha tenido que vivir para responder a un modelo de Estado para el cual no fue creada. Con el ánimo se superar este vacío, a partir de la relación entre derecho y política, este libro indaga por las transformaciones del derecho administrativo, por los elementos que alteran el rol del juez administrativo en el Estado social de derecho, así como por las distintas herramientas que le permiten al juez enfrentar tales alteraciones. A tal fin se analizan, entre otros temas, la discusión sobre la fuerza vinculante de la jurisprudencia, el papel de los métodos de interpretación y de la argumentación en las decisiones contencioso administrativas, las diversas posiciones sobre la aplicación de normas fundamentales por el juez administrativo y algunas de las novedosas iniciativas establecidas por la Ley 1437 de 2011. Conocer la influencia del juez administrativo colombiano en el fortalecimiento del Estado social de derecho permite evaluar su nivel de relevancia para dicho modelo de Estado y, con ello, proponer cambios en su razonamiento y modos de proceder judicial. A estos dos aspectos se espera incentivar con la lectura de este libro. Este es, sobre todo, un libro para cuestionar el derecho administrativo a la luz del contraste entre los cambios del rol del juez administrativo colombiano y las transformaciones de esta rama del derecho.', '["administrative judge","social rule of law","constitutional state","administrative law reform","binding force of case law","judicial reasoning","fundamental rights","Law 1437 of 2011","law and politics","judicial role"]', '10.7476/9789587385878', '9789587385861', 'https://books.scielo.org/id/bc2w8', NULL, NULL, 'https://books.scielo.org/id/bc2w8/cover/cover_thumbnail.jpeg', 205, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bc84k', 'bc84k', 'E-science e políticas públicas para ciência, tecnologia e inovação no Brasil', NULL, '["Valdinéia Barreto Ferreira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em E-science e políticas públicas para ciência, tecnologia e inovação no Brasil, a autora apresenta o conceito que está relacionado à melhoria e fortalecimento dos laboratórios e grupos de pesquisa como ambientes colaborativos. Além disso, discute ao longo dos capítulos, questões que dizem respeito a políticas públicas para fomento científico, tecnológico e de inovação e também dos institutos nacionais de ciência e tecnologia, entre outros aspectos.', '["e-Science","science, technology and innovation policy","research laboratories","research groups","collaborative environments","research funding","Brazil"]', '10.7476/9788523218652', '9788523218652', 'https://books.scielo.org/id/bc84k', 'https://books.scielo.org/id/bc84k/pdf/ferreira-9788523218652.pdf', NULL, 'https://books.scielo.org/id/bc84k/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
