INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bd8py', 'bd8py', 'Introdução à filosofia crítica de Kant', NULL, '["Joãosinho Beckenkamp"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro sobre a filosofia crítica kantiana, o autor empreende a incomum tarefa de apresentar, ainda que introdutoriamente, o conjunto dos temas e problemas que têm interessado os estudiosos de Kant ao longo destes dois séculos em que já perdura sua recepção. Indo além da mera justaposição dos temas, à qual se limitam em geral as exposições abrangentes da obra kantiana, o autor fornece uma linha de interpretação que permite apreender de maneira articulada as diversas partes do ousado programa desta filosofia crítica que revolucionou a maneira como se abordam as questões últimas que sempre interessaram ao gênero humano.', '["Immanuel Kant","critical philosophy","Kantian interpretation","reception of Kant"]', '10.7476/9786558581543', '9788542301786', 'https://books.scielo.org/id/bd8py', NULL, NULL, 'https://books.scielo.org/id/bd8py/cover/cover_thumbnail.jpeg', 454, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(