THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bfwrk', 'bfwrk', 'Os eleitos: representação e carreiras políticas em democracias', NULL, '["André Marenco"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'popularização da classe política brasileira?Um perfil dos Senadores da República Luiz Domingos Costa e Adriano Codatodesvendar as condições de ingresso nas câmaras municipais -na maioria das vezes, o primeiro degrau para carreiras políticas -pode ser encontrado nos capítulos seguintes, de Grill, Seidl e Reis.Igor Grill parte da constatação de que a política no Maranhão sempre esteve associada a um padrão oligárquico: a importância de patrimônio econômico, vínculos familiares e patronagem como recursos para potencializar carreiras políticas.O texto procura refinar esta descrição, analisando informações biográficas de deputados federais eleitos no Maranhão, entre 1946 e 2010.Paralelo a um exame diacrônico das 17 bancadas federais maranhenses eleitas neste período, o autor constrói uma comparação com bancadas federais eleitas no Rio Grande do Sul e desenvolve, ainda, uma análise sincrônica sobre casos exemplares em carreiras políticas no Maranhão recente.Como resultado, identifica três diferentes configurações de carreira, segundo combinações distintas de reconversão de notoriedade profissional, capital econômico e passagem por funções públicas: tradicional, ascensão social e militante.Em seu capítulo, Ernesto Seidl pergunta de onde vêm os representantes eleitos em Sergipe.Para responder, investiga o perfil de 200 candidatos a Prefeito em 75 municípios daquele estado, nas eleições de 2008.Constata que prevalece um perfil formado por indivíduos do sexo masculino, oriundos de ocupações superiores, dotados de experiência política, e com patrimônio crescente sobretudo de eleitos em relação a candidatos.À medida em que cresce a magnitude dos colégios eleitorais municipais, cresce também conforme revela Seidl, o capital social e escolar dos candidatos.Por fim, examinando candidatos a cadeiras no legislativo municipal de Aracaju, o autor revela itinerários políticos bem caracterizados por experiência política precoce e baixo ativismo associativo.Eliana Reis propõe-se a analisar a apropriação da gramática democrática e sua tradução em práticas administrativas, por militantes que iniciaram sua trajetória na luta contra o regime autoritário e, no presente, ocupam postos ligados a experiências de ampliação da participação política: Orçamento Participativo no Rio Grande do Sul e gestão da cultura, no Maranhão.Para alcançar este objetivo, Reis investiga perfis sociais, modalidades de atuação política, destinos profissionais e investimentos realizados em experiências participativas por quadros políticos com atuação em dois momentos históricos distintos, em cada um dos estados.André Marenco e de leadership que os especificam.Quanto ao "entorno" que determina suas estratégias, ele é, na maior parte do tempo, reduzido às variáveis políticas, principalmente o próprio sistema de partidos, o regime político e o modo de votar.Desde a célebre distinção construída por M. Duverger entre partidos de quadros e partidos de massas, os pesquisadores em ciência política consagraram muita energia ao pôr em ordem novas categorias: as noções de catch-all-party (Otto Kirchheimer), stratarchic party (Samuel Eldersveld), electoral-professional party (Angelo Panebianco 11 ), e mais recentemente a de cartel-party (Richard S.Katz e Peter Mair 12 ), vieram enriquecer progressivamente o arsenal dos estudos políticos ao sabor de mutações sociopolíticas, com destinos diversos.A construção social das organizações políticas Desde a aparição do livro de Duverger, um politólogo francês, Georges Lavau, criticara "a explicação dos partidos pelos partidos e pelo regime eleitoral" proposta por Duverger, assim como sua escolha de considerar "o partido político como uma comunidade de estrutura peculiar" caracterizando-se "antes de tudo por sua autonomia".Georges Lavau advertia sobre os limites das tipologias exclusivamente organizacionais."Um partido fascista pode calcar sua organização sobre a do partido comunista, inserir-se em um mesmo sistema partidário, escrevia ele, a semelhança será apenas morfológica, isto é, formal, deixando escapar o essencial que só pode ser explicado precisamente com o auxílio da doutrina e da composição social.Em um grau menor, poderíamos ainda sublinhar diferenças tão fundamentais entre dois partidos comunistas, um inserido em uma sociedade de tipo agrícola e outro em uma sociedade de tipo industrial."E concluía ele: "Não é apenas o estudo da doutrina e da composição social dos partidos que falta, com efeito, à obra de Duverger, mas sobretudo o estudo dos tipos de sociedade e civilização em que se movem os partidos, o das condições econômicas e das circunstâncias históricas nas quais eles evoluem."13 Dito de outra forma, "os partidos políticos não constituem, abstratamente, co-11 PANEBIANCO, A.', '["political careers","political representation","elected officials","Brazilian politics","Maranhão","Rio Grande do Sul","Sergipe","local elections","social capital","economic capital","political elites","patronage"]', '10.7476/9788538603849', '9788538603849', 'https://books.scielo.org/id/bfwrk', 'https://books.scielo.org/id/bfwrk/pdf/marenco-9788538603849.pdf', NULL, 'https://books.scielo.org/id/bfwrk/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bg29q', 'bg29q', 'A construção do mito Mário Palmério: um estudo sobre a ascensão social e política do autor de Vila dos Confins', NULL, '["André Azevedo da Fonseca"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Antes de publicar Vila dos Confins e Chapadão do Bugre – obras seminais da literatura brasileira – Mário Palmério já era considerado um mito no interior de Minas Gerais. Contrariando as expectativas em uma região atormentada por diversas crises, o jovem e ambicioso professor assumiu riscos, tornou-se um empresário bem-sucedido e aprendeu a manipular os símbolos mais preciosos de sua sociedade. Palmério desenvolveu uma percepção aguçada sobre a dimensão teatral da vida social e empregou uma série de procedimentos dramatúrgicos para supervalorizar seu papel e conquistar a adoração dos conterrâneos. Na campanha eleitoral de 1950, ao atuar como um guerreiro sagrado capaz de conduzir seu povo à terra prometida, Palmério elegeu-se deputado federal e consagrou-se como um mito político. Resultado de pesquisa de doutorado, o livro explica essa trajetória na perspectiva da História Cultural.', '["political myth","social ascent","Minas Gerais","federal deputies","cultural history","regional identity","Brazilian literature"]', '10.7476/9788539302680', '9788539302680', 'https://books.scielo.org/id/bg29q', 'https://books.scielo.org/id/bg29q/pdf/fonseca-9788539302680.pdf', NULL, 'https://books.scielo.org/id/bg29q/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bg6yw', 'bg6yw', 'Plantas medicinais: memória da ciência no Brasil', NULL, '["Tania Maria Fernandes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'A história do campo disciplinar da pesquisa em plantas medicinais e suas inter-relações com a indústria farmacêutica nacional são aqui analisados com perspicácia e ousadia metodológica. Dentre os aspectos abordados, evidencia-se o voltado para compreender a constituição e o desenvolvimento da comunidade científica, investigado pela autora entre 1960 e 2002. Apresenta ainda oportuna discussão sobre a propriedade industrial e intelectual e a lei de patentes para produtos químico-farmacêuticos, e sua importância para a pesquisa atual brasileira.', '["medicinal plants","scientific community development","pharmaceutical industry","industrial property","intellectual property","patent law","pharmaceutical patents"]', '10.7476/9788575413487', '9788575413487', 'https://books.scielo.org/id/bg6yw', 'https://books.scielo.org/id/bg6yw/pdf/fernandes-9788575413487.pdf', NULL, 'https://books.scielo.org/id/bg6yw/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bgqvf', 'bgqvf', 'Avessos do prazer: drogas, Aids e direitos humanos', NULL, '["Gilberta Acselrad"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'PREFÁCIOA combinação de ''drogas e Aids'' como objeto de reflexão sinaliza para a identidade estrutural de dois dramas humanos atuais.Em ambos se associam prazer e dor, vida e morte, repressores e pseudo-humanistas, intolerância, preconceito e discriminação.Nessa patética combinação, parafraseando Glauber Rocha, "deus é o diabo na terra do sol", porque o esplendor do amor, da paixão e das transformações perceptivas passaram a acenar com o gozo, mas já então indissociável da avaliação de seu custo.Entretanto, como calcular e reduzir esse custo?Que quadrantes do conhecimento humano deveriam ser abordados para o adequado enfrentamento da questão?Ou que direção escolher que pudesse alimentar a esperança de contribuir, efetivamente, para a formulação de políticas públicas sobre os temas enfocados?Os artigos aqui reunidos, pela análise de seu conteúdo, definem, em primeiro lugar, a centralidade da pessoa humana como razão de ser de todo o trabalho desenvolvido.Isso significa que os anelos do ser humano, suas carências, suas lutas, seus direitos, suas utopias, seus ideais de igualdade, de solidariedade e de justiça formaram o núcleo deste ''pensar coletivo''.É interessante notar que nenhum dos autores priorizou a análise dos temas específicos da repressão, que inflamam a mídia, como a formação de tropas para o combate armado ao narcotráfico nas fronteiras, os processos de detecção de lavagem de dinheiro, os métodos novos de enfrentamento da chamada ''economia da droga'', as estatísticas de apreensão, o aumento de penas privativas de liberdade, entre tantos outros eletrizantes capítulos integrantes da seara repressiva.E por que não foi priorizada a repressão?Por que os autores não estariam preocupados com tais assuntos?Não.Positivamente não.Esses temas preocupam a todos nós, tanto quanto, por exemplo, o ataque à corrupção denunciada nos poderes da República ou o combate ao contrabando, além De maneira geral, predominam mistérios, discriminação, repressão.Daí a urgência de um debate amplo e esclarecido.Com o objetivo de contribuir para a reflexão e a ação dos atores sociais com prática institucional e/ou comunitária no campo da educação, saúde e direitos dos usuários de drogas e pessoas com HIV/Aids, tentamos aqui pensar coletivamente tais questões nos seus ''avessos'', ou seja, de forma essencialmente solidária, na contramão das políticas repressivas e autoritárias.Tentamos refletir sobre o estreitamento dos espaços de prazer na vida dos sujeitos e sobre o prazer que a droga garante, ainda que, hoje, em meio a tantos riscos.À pergunta usual -por que as pessoas se drogam?-, acrescentamos outrapor que algumas pessoas conseguem usar drogas de forma controlada e por que, de outro lado, se tem exercido tanta intervenção em experiências que pertencem à esfera da vida privada?', '["human rights","pleasure and pain","drug use","HIV prevention","drug policy","public policy","discrimination","stigma"]', '10.7476/9788575415368', '9788575415368', 'https://books.scielo.org/id/bgqvf', 'https://books.scielo.org/id/bgqvf/pdf/acselrad-9788575415368.pdf', NULL, 'https://books.scielo.org/id/bgqvf/cover/cover_thumbnail.jpeg', NULL, 41, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bjdd3', 'bjdd3', 'A Bahia em pedaços', NULL, '["Antônio Fernando Guerreiro de Freitas"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Se o que não é recôncavo é reconvexo, então podemos dizer que a obra “Bahia em Pedaços” do professor Antônio Fernando Guerreiro de Freitas nos lança para o vasto reconvexo baiano e para a diversidade de sua formação histórica e espacial. A Bahia que não só é de todos os santos, mas também de variadas referências sociais, espaciais e culturais, foi analisada nesta obra a partir de duas regiões forjadas desde o final do século XIX até meados do século XX, demonstrando o quão heterogênea é a Bahia. Ao menos dois pedaços são analisados: o sul cacaueiro e o sertão do São Francisco. Dessa forma, temos uma contribuição teórico-metodológica para pensar os processos de regionalização dentro da Bahia, bem como o conceito de região pode ser pensado de forma histórica.', '["Bahia","regionalization","concept of region","historical geography","regional variation"]', '10.7476/9788574555829', '9788574555546', 'https://books.scielo.org/id/bjdd3', NULL, NULL, 'https://books.scielo.org/id/bjdd3/cover/cover_thumbnail.jpeg', 366, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bjj6w', 'bjj6w', 'Atenção primária à saúde no Brasil: conceitos, práticas e pesquisa', NULL, '["Maria Helena Magalhães de Mendonça","Gustavo Corrêa Matta","Roberta Carolino Antunes Gondim","Lígia Giovanella"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', '“A reflexão crítica sobre a trajetória e os desafios relacionados à Atenção Primária à Saúde (APS) no Brasil torna-se densa e inspiradora de debates e propostas de intervenção quando se reúnem perspectivas diversas a respeito dos caminhos teóricos, das experiências em diferentes territórios, das práticas profissionais e dos processos de trabalho. Tal panorama permite compreender o valor desta política social para a conquista do direito universal à saúde e para a consolidação do Sistema Único de Saúde (SUS). Este é o convite que nos fazem os autores desta obra, escrita com o objetivo de atingir gestores, pesquisadores, estudantes e trabalhadores que atuam na APS. Em um contexto que exige capacidade de escuta e argumentação, o cuidado das análises se soma à preocupação com a clareza de linguagem, ou seja, com uma proposta pedagógica. Com acerto, os autores relacionam o adensamento da APS à expansão da Estratégia Saúde da Família, apontando seu impacto na redução de desigualdades e iniquidades socioeconômicas. Neste aspecto, a abordagem intersetorial é da maior relevância, e os capítulos aqui reunidos contribuem para uma discussão mais ampla sobre políticas públicas”. (Nísia Trindade Lima, presidente da Fiocruz)', '["primary care","Family Health Strategy","Unified Health System (SUS)","right to health","health disparities","socioeconomic inequities","multisectoral approach","public health policy","health management"]', '10.7476/9788575416297', '9788575415634', 'https://books.scielo.org/id/bjj6w', NULL, NULL, 'https://books.scielo.org/id/bjj6w/cover/cover_thumbnail.jpeg', 610, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bk', 'bk', 'Espaços culturais: vivências, imaginações e representações', NULL, '["Ângelo Serpa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O que há de comum entre as representações dos índios Terena do Mato Grosso do Sul, o espaço sagrado no islã Shi´i, a Irmandade da Boa Morte na Bahia, as festas em louvor a São João Batista, as representações do Brasil Sertanejo, as representações e territorialidades homoeróticas e os naturistas? Responder esta pergunta não é algo simples, mas a resposta está na idéia de que as representações do espaço e o espaço das representações são plurais e diversos, exigindo outros olhares para interpretar a complexidade do mundo.', '["cultural space","representations of space","Terena people","sacred space","Shi''i Islam","homoeroticism","naturism","territoriality"]', '10.7476/9788523211899', '9788523211899', 'https://books.scielo.org/id/bk', 'https://books.scielo.org/id/bk/pdf/serpa-9788523211899.pdf', NULL, 'https://books.scielo.org/id/bk/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bm9qp', 'bm9qp', 'Os médicos no Brasil: um retrato da realidade', NULL, '["Maria Helena Machado"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Quem são os médicos, hoje, em nosso país? De onde vêm, o que pensam, como trabalham e em que condições? Recebem devidamente? A recente pesquisa "Perfil dos Médicos no Brasil", sediada na Escola Nacional de Saúde Pública Sergio Arouca (Ensp/Fiocruz), buscou responder a todas estas indagações. Este livro analisa os dados oriundos daquela pesquisa. Para melhor tratá-los, os autores apoiaram-se na teoria sociológica e em sólida base empírica, diagnosticando de maneira clara e consistente a situação atual desses profissionais. Torna-se, assim, referência básica e obrigatória para planejadores, gestores e pesquisadores da saúde, especialmente os que necessitam compreender aspectos sociodemográficos, formação profissional, mercado de trabalho, ética e organização social e política da corporação médica.', '["physicians","medical profession","physician profile","medical education","physician workforce","physician remuneration","medical ethics","medical profession organization","health policy planning","Brazil"]', '10.7476/9788575412695', '9788575412695', 'https://books.scielo.org/id/bm9qp', 'https://books.scielo.org/id/bm9qp/pdf/machado-9788575412695.pdf', NULL, 'https://books.scielo.org/id/bm9qp/cover/cover_thumbnail.jpeg', NULL, 74, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bmhq9', 'bmhq9', 'Marcadores da diferença: raça e racismo na história do Brasil', NULL, '["Sampaio, Gabriela dos Reis","Lima, Ivana Stolze","Balaban, Marcelo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro investiga a história de homens e mulheres não brancos, anônimos ou bem conhecidos, que sofreram as agruras de viver em uma sociedade definida pelo racismo. A obra pretende promover um debate sobre o tema da raça e do racismo a partir da perspectiva da história social. Focalizados em diferentes personagens, os textos revelam de que forma, ao longo do processo histórico, os problemas e relacionados ao racismo foram enfrentados em seus múltiplos sentidos, observando como diferentes marcas da cor, inscritas em diversas realidades e aspectos, produziam (e ainda produzem) distinções sociais, gerando essa violenta forma de opressão que subsiste, surpreendentemente, com tanta força no nosso país.', '["race","racism","racial discrimination","social inequality","racial oppression","racial identity"]', '10.7476/9788523218058', '9788523219499', 'https://books.scielo.org/id/bmhq9', NULL, NULL, 'https://books.scielo.org/id/bmhq9/cover/cover_thumbnail.jpeg', 326, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bmzsz', 'bmzsz', 'Difíceis decisões: etnografia de um Centro de Tratamento Intensivo', NULL, '["Rachel Aisengart Menezes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Em nossos modernos CTIs, a morte, antes vista como acontecimento irrevogável, passa mais claramente à ordem dos processos, cuja duração, intensidade e conseqüências são administradas ou reguladas segundo critérios e valores muitas vezes não explicitados. Mediante um estudo de caso, a autora aborda a organização social dos centros de tratamento intensivo; os dramas éticos envolvendo profissionais da saúde, pacientes e familiares; e, finalmente, a emergência de um novo especialista, o intensivista.', '["intensive care unit","intensive care ethics","end-of-life decisions","patient and family involvement","intensivists","medical ethics"]', '10.7476/9788575413135', '9788575413135', 'https://books.scielo.org/id/bmzsz', 'https://books.scielo.org/id/bmzsz/pdf/menezes-9788575413135.pdf', NULL, 'https://books.scielo.org/id/bmzsz/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bn2ds', 'bn2ds', 'Ayer mineros, hoy ecoguías y concesionarios: tensiones en torno a la conservación ambiental, el uso de la tierra y el trabajo en Guasca, Cundinamarca', NULL, '["Felipe Rojas Arias"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Al entrar a los predios de la Reserva Biológica Encenillo (RBE), ubicada en la vereda Trinidad del municipio de Guasca (Cundinamarca), pocos se imaginan que allí operó una mina de piedra caliza por más de sesenta años. Los cambios que han acontecido en esta vereda a partir del cierre de la mina, la constitución de esta área protegida, la tenencia de la tierra y la precariedad laboral, han generado tensiones a nivel local por cuenta del uso de los recursos naturales, en particular la tierra, y por la carencia de fuentes de trabajo para abastecer la demanda local. Las añoranzas por condiciones laborales más favorables en la época en que funcionó la mina, los reparos por la falta de oportunidades labores en la vereda y los desacuerdos por los usos de los recursos naturales y la apropiación territorial entre los administradores del área protegida y la población local, son los principales problemas que analiza esta obra a partir de un trabajo etnográfico.', '["land use conflicts","environmental protection","territorial appropriation","precarious employment","local employment","natural resource use","mining legacy","local tensions"]', '10.7476/9789587385892', '9789587385892', 'https://books.scielo.org/id/bn2ds', 'https://books.scielo.org/id/bn2ds/pdf/rojas-9789587385892.pdf', NULL, 'https://books.scielo.org/id/bn2ds/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bnbxx', 'bnbxx', 'Testosterona: a biografia de um hormônio', NULL, '["Lucas Tramontano"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro de Tramontano guia-nos por um caminho que tem um sem-número de ramificações. O autor, entretanto, percorre tais ramificações sem deixar que a história se disperse, alinhavando com cuidado e esmero as diversas aproximações e afastamentos, construindo conexões e apontando divergências cabíveis. Assim, a personagem testosterona vai ganhando corpo, e sua relevância política vai ficando clara, ajudando-nos a compreender, por um lado, como nossas trocas cotidianas são perpassadas pelas descobertas científicas, e, por outro, como as descobertas científicas são influenciadas pelo que trocamos em nossas vidas cotidianas.', '["testosterone","history of endocrinology","scientific discovery","politics of science","science in everyday life"]', '10.7476/9786557082201', '9786557081846', 'https://books.scielo.org/id/bnbxx', NULL, NULL, 'https://books.scielo.org/id/bnbxx/cover/cover_thumbnail.jpeg', 246, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bpbvs', 'bpbvs', 'Responsabilidad internacional y del estado: encrucijada entre sistemas para la protección de los derechos humanos', NULL, '["Ana Gemma López Martín","López Cárdenas, Carlos Mauricio","Manuel Alberto Restrepo Medina"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Desde que en 1948 se proclamaron universalmente los derechos humanos, la lucha por su plena y efectiva realización ha sido una constante de la comunidad internacional. En este marco se circunscribe el Segundo Decenio de las Naciones Unidas para la educación en la esfera de los derechos humanos (2004-2014), que tiene como propósito orientar la enseñanza universitaria al campo no sólo de la docencia, sino de la investigación científica. En este sentido, el propósito de la presente obra consiste en divulgar una serie de estudios relacionados con la responsabilidad internacional y los derechos humanos cuyas áreas temáticas no han sido trabajadas de forma sistemática, presentan vacíos investigativos o, simplemente, constituyen los más recientes avances en el campo del derecho. El libro presenta dos estudios históricos relacionados con las desapariciones forzadas, así como temáticas novedosas del derecho internacional de los derechos humanos acerca de la responsabilidad agravada y el derecho a la alimentación. De la misma manera, se tratan temáticas de la más reciente actualidad sobre la protección de los derechos socio-laborales en el marco de la organización internacional del trabajo, la política migratoria de la Unión Europea, así como las contribuciones del regionalismo africano al mantenimiento de la paz y a la seguridad internacional. En la parte final de la obra, se presentan una serie de estudios que profundizan sobre temáticas relacionadas con la lucha contra el terrorismo y la prohibición de la tortura, la protección de bienes culturales en situaciones de conflicto armado, la proscripción del uso de la fuerza y, finalmente, un estudio sobre la competencia de la Corte Penal Internacional."', '["international responsibility","state responsibility","human rights protection","international human rights law","enforced disappearance","right to food","International Labour Organization","EU migration policy","African regionalism","peace and security","counterterrorism","prohibition of torture"]', '10.7476/9789587385854', '9789587385847', 'https://books.scielo.org/id/bpbvs', NULL, NULL, 'https://books.scielo.org/id/bpbvs/cover/cover_thumbnail.jpeg', 779, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bpkng', 'bpkng', 'Ensino de ciências e matemática, IV : temas de investigação', NULL, '["Nelson Antônio Pirola"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Uma melhor qualificação das práticas de ensino nas áreas curriculares da educação básica obrigatória certamente apresenta -se como meta de programas de investigação com fundamentações epistemológicas e propostas metodológicas distintas que enfrentam uma variedade considerável de desafios.', '["science education","mathematics education","teaching practice","basic education","compulsory education","epistemological foundations","research programs"]', '10.7476/9788579830815', '9788579830815', 'https://books.scielo.org/id/bpkng', 'https://books.scielo.org/id/bpkng/pdf/pirola-9788579830815.pdf', NULL, 'https://books.scielo.org/id/bpkng/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bqkhv', 'bqkhv', 'O gênero da parábola', NULL, '["Marco Antônio Domingues Sant''Anna"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro pretende demonstrar que o Novo Testamento bíblico é o contexto da constituição da parábola como gênero literário. Mesmo que essa modalidade seja mencionada em outros universos, temos como proposta mostrar que é somente no Novo Testamento que ela assume feições mais definidas. Tal tarefa justifica-se, em primeiro lugar, pelo fato de haver, no Brasil, um número muito limitado de obras disponíveis que tratem da parábola e dos aspectos teóricos a ela relacionados. Em segundo lugar, a situação se agrava quando se parte para uma pesquisa especificamente em língua portuguesa. Como será demonstrado com maiores detalhes nos capítulos subsequentes, o que se encontra em uma parte restrita de livros de teoria literária publicados em nosso país são apenas pequenos verbetes sobre o assunto. Além desses dados ligados basicamente à limitação de bibliografia, tem-se que o tratamento que essas poucas obras existentes oferecem ao gênero parabólico está muito distante de ser exaustivo.', '["parables","literary genre","New Testament","genre theory","biblical literature"]', '10.7476/9788539304394', '9788539300112', 'https://books.scielo.org/id/bqkhv', NULL, NULL, 'https://books.scielo.org/id/bqkhv/cover/cover_thumbnail.jpeg', 315, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bqpsx', 'bqpsx', 'Tessituras do cuidado: as condições crônicas de saúde na infância e adolescência', 'as condições crônicas de saúde na infância e adolescência', '["Camila Aloísio Alves"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Com o objetivo de compreender como se constrói o cuidado às condições crônicas na infância e na adolescência em hospitais de média e alta complexidade, a psicóloga e sanitarista Camila Aloisio Alves estudou as relações entre crianças e adolescentes com doenças crônicas, seus familiares e profissionais da saúde, em ambientes de internação (neonatologia, pediatria e cirurgia pediátrica). O cuidado, assumido como categoria central da pesquisa, conduziu a autora a estudar essas relações a fim de refletir criticamente não só sobre o cotidiano da assistência, mas também sobre as possibilidades de se produzir um projeto de vida com e apesar do adoecimento crônico, contribuindo para o entendimento dos elementos, desafios e potencialidades inscritos no cuidado dedicado a essas crianças e adolescentes. “Este livro trata de um tema que marca intimamente a vida de um grupo de sujeitos, mas não é demais lembrar que as condições crônicas de crianças e adolescentes referem-se a problemas que afetam toda a sociedade, o que demanda que o cuidado objeto do presente estudo seja integral, intersetorial e incorpore valores que afirmem a humanização das relações”, afirma a autora.', '["care","hospitalized children","neonatology","pediatric surgery","family relationships","healthcare workers","life project","humanized care","intersectoral care","comprehensive care"]', '10.7476/9786557083000', '9788575414804', 'https://books.scielo.org/id/bqpsx', 'https://books.scielo.org/id/bqpsx/pdf/alves-9786557083000.pdf', NULL, 'https://books.scielo.org/id/bqpsx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-br33x', 'br33x', 'Saneamento: promoção da saúde, qualidade de vida e sustentabilidade ambiental', NULL, '["Cezarina Maria Nobre Souza","André Monteiro Costa","Luiz Roberto Santos Moraes","Carlos Machado de Freitas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'A declaração da Assembleia Geral da ONU de 2010 denuncia grave violação de um direito humano essencial: grande parte da população do mundo vive em condições precárias de acesso a bens e serviços essenciais. Esse quadro poderia ser minimizado e até evitado se fosse possível oferecer saneamento básico a todos. Neste livro, quatro profissionais atuantes nas áreas de engenharia sanitária e saúde ambiental propõem um novo olhar sobre a tríade ‘desenvolvimento, ambiente e saúde’, com o objetivo de formular estratégias inovadoras para garantir o acesso mais amplo ao saneamento. Fatores como o modo de vida da população, as condições socioeconômicas e a cultura servem de base na busca por soluções capazes de combinar tecnologia e gestão sociocultural. “O modelo de gestão deve ser adequado à tecnologia utilizada e às características socioculturais da população. Não é mais aceitável, como tem sido corrente, a imposição de soluções que, por não considerarem a coerência com a cultura e as condições de habitabilidade das pessoas, geram ônus de manutenção para as mais pobres.”, destacam os autores no texto de apresentação do livro.', '["sanitation","basic sanitation","right to water and sanitation","health promotion","quality of life","environmental sustainability","sanitation management","sociocultural factors","sanitation technology","access to basic services"]', '10.7476/9788575415238', '9788575414705', 'https://books.scielo.org/id/br33x', NULL, NULL, 'https://books.scielo.org/id/br33x/cover/cover_thumbnail.jpeg', 140, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-brq52', 'brq52', 'Estado e capital na China', NULL, '["Renildo Souza"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A reorientação políticaA construção do novo discurso do PCC Pós-Mao O período precedente, aqui denominado Era Mao, teria que ser submetido a uma interpretação conclusiva, no Partido Comunista Chinês (PCC), a partir da segunda metade dos anos 1970, após a morte em setembro de 1976 do seu, até então, indiscutido principal dirigente, Mao Zedong.3 Esse balanço do período Mao associouse às ideias subjacentes às reformas que reorientaram o Estado chinês, a partir de fins da década de 1970.A consolidação do novo poder político, as transformações econômicas, as reviravoltas diplomáticas, o Grande Salto à Frente e a Revolução Cultural (RC) 3 Na grafia dos nomes chineses, observou-se o sistema ortográfico oficial romanizado pinyin, mantendo-se, como esse sistema faculta, algumas exceções.', '["state and capital","Chinese Communist Party","economic reform","Great Leap Forward","Cultural Revolution","Mao Zedong","Chinese state","Chinese economy"]', '10.7476/9788523220020', '9788523220020', 'https://books.scielo.org/id/brq52', 'https://books.scielo.org/id/brq52/pdf/souza-9788523220020.pdf', NULL, 'https://books.scielo.org/id/brq52/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-brzzm', 'brzzm', 'A democracia reduz a desigualdade econômica? Um estudo sobre as possibilidades de construção de uma sociedade mais igual por meio da democracia', NULL, '["Ivan Filipe de Almeida Lopes Fernandes"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro trata de assunto tão importante quanto controverso: os efeitos de sistemas políticos democráticos sobre a distribuição mais equânime da renda nas sociedades contemporâneas. Há muito essa discussão vem preocupando pensadores e analistas. O livro dialoga com a rica literatura produzida pelos economistas sobre o tema desigualdade e busca fazê-la conversar com o que cientistas políticos andam dizendo sobre o assunto. Submetendo, com competência, grande massa de informação à sofisticada análise estatística, Ivan Fernandes nos apresenta conclusões interessantes e originais. Segundo ele, os efeitos da democracia sobre a situação de desigualdade não são os mesmos em toda parte, mas dependem do contexto socioeconômico no qual a desigualdade de renda é produzida. A heterogeneidade dos efeitos dos sistemas democráticos sobre a distribuição de renda é a principal conclusão empírica do estudo. Mas, ele vai mais adiante sugerindo uma explicação de corte político. É preciso que existam partidos que tenham interesse em brandir a bandeira eleitoral de mais igualdade e um grande número de eleitores, cuja situação objetiva, os faça demandar políticas redistributivas. “Somente nas sociedades mais desiguais”, argumenta o autor, “tanto os partidos políticos têm interesse em ofertar políticas redistributivas, quanto tende a surgir demanda por redistribuição por parte de uma maioria de eleitores.” Aquela conclusão, engenhosa, ainda demanda outros estudos, mas os resultados apresentados são promissores e garantem ao autor um lugar na mesa de discussão sobre o assunto, que se arrasta há mais de um século, acompanhando a trajetória do capitalismo e dos sistemas políticos democráticos. E que, sem dúvida, perdurará enquanto os dois existirem em tensa relação.', '["democracy","income inequality","income distribution","redistributive politics","political parties","socioeconomic context","capitalism"]', '10.7476/9788568576793', '9788568576793', 'https://books.scielo.org/id/brzzm', 'https://books.scielo.org/id/brzzm/pdf/fernandes-9788568576793.pdf', NULL, 'https://books.scielo.org/id/brzzm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bskw2', 'bskw2', 'Segurança do paciente: criando organizações de saúde seguras', NULL, '["Sousa, Paulo","Mendes, Walter"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Promover, proteger e recuperar a saúde é o que se espera dos serviços de saúde. Por isso, provoca espanto quando se fala que o processo de cuidado em saúde pode causar incidentes com danos. Alguns perigos são inerentes a esse processo – por exemplo, os efeitos colaterais conhecidos de determinados medicamentos. Outros podem ser consequências de erros, que acontecem em qualquer ramo de atividade, inclusive na saúde. Para fazer frente à frequência e à magnitude desses problemas, deve-se disseminar a cultura da segurança nos serviços de saúde, com o objetivo de melhorar a qualidade e os resultados desses serviços. Importantes contribuições nesse sentido podem ser encontradas nestes dois volumes. Os livros são desdobramento de um curso internacional de especialização em qualidade em saúde e segurança do paciente, oferecido na modalidade a distância (EAD) no âmbito de uma parceria entre a Escola Nacional de Saúde Pública da Fundação Oswaldo Cruz e a Escola Nacional de Saúde Pública da Universidade Nova de Lisboa. Especialistas brasileiros e portugueses produziram materiais didáticos para o curso, pois se verificou uma escassez de publicações sobre essas temáticas, sobretudo em língua portuguesa. Contudo, os materiais ganharam vida própria, independente do curso. Estruturadas de modo a suprir as reais necessidades de formação de médicos, enfermeiros, farmacêuticos, profissionais das tecnologias da saúde e gestores, as coletâneas têm por base conhecimentos e evidências que refletem o atual estado da arte em segurança do paciente. Os leitores – não só do Brasil e de Portugal, mas de toda a Comunidade dos Países de Língua Portuguesa (CPLP) – encontrarão subsídios para que, no dia a dia, mudanças na prática dos cuidados resultem em serviços mais seguros em todos os pontos da atenção à saúde.', '["patient safety","health care organization","safety culture","medical errors","adverse events","quality of care","health professions education","health management","Portuguese-speaking countries"]', '10.7476/9788575416426', '9788575416426', 'https://books.scielo.org/id/bskw2', 'https://books.scielo.org/id/bskw2/pdf/sousa-9788575416426.pdf', NULL, 'https://books.scielo.org/id/bskw2/cover/cover_thumbnail.jpeg', NULL, 60, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bsmtd', 'bsmtd', 'Epidemiologia e saúde dos povos indígenas no Brasil', NULL, '["Carlos Ε. A. Coimbra","Ricardo Ventura Santos","Ana Lúcia Escobar"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Rica seleção de textos e experiências sobre a questão da saúde indígena no Brasil, originários de discussão em oficina de trabalho ocorrida no V Congresso Brasileiro de Epidemiologia (Curitiba, 2002). Escrito por pesquisadores estudiosos das mais diferentes vertentes do assunto, traz importante e inovadora contribuição a tema que vem emergindo como de grande importância no âmbito da saúde coletiva no Brasil nos últimos anos. Oferece um amplo panorama, detalhado e atualizado, da saúde indígena no País, contemplando reflexões com base nas diversas áreas do conhecimento que compõem a saúde coletiva.', '["Indigenous health","public health","health disparities"]', '10.7476/9788575412619', '9788575412619', 'https://books.scielo.org/id/bsmtd', 'https://books.scielo.org/id/bsmtd/pdf/coimbra-9788575412619.pdf', NULL, 'https://books.scielo.org/id/bsmtd/cover/cover_thumbnail.jpeg', NULL, 58, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bsx4q', 'bsx4q', 'Cartografia social: (re)descobrindo saberes', NULL, '["Jocimara Souza Britto Lobão","Ana Isabel Leite Oliveira","Israel de Oliveira Junior"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'No processo de automapeamento, a Cartografia Social garante protagonismo, empoderamento, elaboração de conhecimentos significativos na prática social e para a prática social. Comunidades e grupos envolvidos pensam o seu território, representam os seus elementos, desvelam as relações socioespaciais, identificam conflitos, vêm a se fortalecer enquanto coletividade, reafirmam identidades, propõem intervenções e rearranjos que, de fato, atendem às suas necessidades, contribuem para melhorar a qualidade de vida pela efetiva participação no planejamento e gestão territorial.', '["social cartography","community empowerment","spatial planning","territorial management","socio-spatial relations","community participation","territorial disputes","collective identity"]', '10.7476/9786589524953', '9786589524953', 'https://books.scielo.org/id/bsx4q', 'https://books.scielo.org/id/bsx4q/pdf/lobao-9786589524953.pdf', NULL, 'https://books.scielo.org/id/bsx4q/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-btnj5', 'btnj5', 'Guia para as palmeiras do nordeste do Brasil', NULL, '["Larry R. Noblick"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Esse volume faz parte dos produtos técnico-científicos da Rede Pindorama (Proc. 407717/2013-7), que é uma iniciativa fomentada pelo CNPq via RENORBIO (Chamada 79-2013) para o desenvolvimento de redes de cooperação de instituições e pesquisadores. Na Rede Pindorama, foram integrados cinco propostas pesquisa, todas com o tema principal no uso e no aproveitamento dos recursos das palmeiras (Arecaceae). A Rede também possibilitou a formação de recursos humanos em todos os níveis e envolveu instituições de todos os estados do Nordeste, com participação de outras instituições nacionais e até uma do Estados Unidos da América (Montgomery Botanical Center). A Rede Pindorama teve a coordenação geral a cargo do Prof. Francisco de Assis Ribeiro dos Santos da Universidade Estadual de Feira de Santana.', '["Arecaceae","Northeast Brazil","palm uses"]', '10.7476/9786589524960', '9786589524960', 'https://books.scielo.org/id/btnj5', 'https://books.scielo.org/id/btnj5/pdf/noblick-9786589524960.pdf', NULL, 'https://books.scielo.org/id/btnj5/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-btwc9', 'btwc9', 'Geografia urbana: desafios teóricos contemporâneos', NULL, '["Ângelo Serpa","Ana Fani Alessandri Carlos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os textos reunidos na coletânea discutem qual a potência da análise geográfica para explicar as novas dinâmicas de urbanização na contemporaneidade. Na busca pela compreensão da realidade brasileira vista da perspectiva de sua espacialização, se estabelece um diálogo com outras disciplinas que compartilham da cidade como objeto de estudo. As perspectivas teórico-metodológicas apresentadas na obra são várias, contribuindo para a sedimentação dos caminhos da pesquisa no campo da Geografia Urbana.', '["urban geography","urbanization dynamics","contemporary urbanization","Brazilian cities","spatialization","theoretical and methodological approaches"]', '10.7476/9788523218812', '9788523217938', 'https://books.scielo.org/id/btwc9', NULL, NULL, 'https://books.scielo.org/id/btwc9/cover/cover_thumbnail.jpeg', 511, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-btxhx', 'btxhx', 'O ayllu andino nas crônicas quinhentistas', NULL, '["Ana Raquel Portugal"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro são analisadas as representações do ayllu da América andina a partir dos dados históricos e etnográficos encontrados nas crônicas indígenas e espanholas do século XVI. O ayllu pré-hispânico era um grupo ligado por sistema de parentesco que mantinha relações de reciprocidade produtiva para subsistência de seus integrantes. No período colonial, ele adquiriu um caráter primordialmente territorial com a finalidade de armazenar mão-de-obra, passando a ser representado como uma organização medieval européia. Ao desfazer alguns equívocos historiográficos sobre o assunto, esta obra contribui para o conhecimento da História colonial da América Hispânica', '["ayllu","16th-century chronicles","indigenous chronicles","Spanish colonial period","kinship systems","reciprocity","territorial organization","labor reserves","colonial historiography","representation of indigenous peoples"]', '10.7476/9788579830006', '9788579830006', 'https://books.scielo.org/id/btxhx', 'https://books.scielo.org/id/btxhx/pdf/portugal-9788579830006.pdf', NULL, 'https://books.scielo.org/id/btxhx/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-btydh', 'btydh', 'Relações étnico-raciais, de gênero e sexualidade: perspectivas contemporâneas', NULL, '["Aparecida de Jesus Ferreira"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A ideia de diversidade tornou-se, frente à crescente afirmação das identidades, um fenômeno significativo especialmente em sociedades oriundas do colonialismo europeu, onde grupos e indivíduos reafirmam seus particularismos locais, suas identidades étnicas, raciais, culturais ou religiosas, chamando a atenção de organismos internacionais a atributos da globalização que não são apenas econômicos ou tecnológicos, mostrando a inadequação das análises estritamente socioeconômicas.', '["ethnic-racial relations","gender relations","sexuality","diversity","ethnic identity","racial identity","cultural identity","religious identity","globalization","European colonialism","identity politics"]', '10.7476/9788577982103', '9788577982103', 'https://books.scielo.org/id/btydh', 'https://books.scielo.org/id/btydh/pdf/ferreira-9788577982103.pdf', NULL, 'https://books.scielo.org/id/btydh/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
