= COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bvc3g', 'bvc3g', 'Arquivologia e patrimônio musical', NULL, '["André Guerra Cotta","Pablo Sotuyo Blanco"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O título compõe o projeto “Patrimônio Musical na Bahia”, que compreende a arquivologia musical como um campo de conhecimento que reúne conceitos e técnicas com o fim de atender as necessidades específicas relativas à organização de acervos ligados à música, compreendendo manuscritos, impressos, discos e documentos tradicionais, como cartas e missivas.', '["music archives","musical heritage","music collections","music manuscripts","music recordings","archival organization"]', '10.7476/9788523208844', '9788523208844', 'https://books.scielo.org/id/bvc3g', 'https://books.scielo.org/id/bvc3g/pdf/cotta-9788523208844.pdf', NULL, 'https://books.scielo.org/id/bvc3g/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bwb4z', 'bwb4z', 'As causas sociais das iniqüidades em saúde no Brasil', NULL, '["Comissão Nacional sobre Determinantes Sociais da Saúde"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é produto do relatório final da Comissão Nacional sobre Determinantes Sociais da Saúde, que desenvolveu uma série de atividades voltadas para a produção de conhecimento e informação sobre os determinantes sociais da saúde no Brasil. A Comissão também propôs a revisão e análise de políticas e programas de intervenção sobre estes determinantes, além da comunicação aos diversos setores da sociedade sobre a importância dos DSS e suas possibilidades de atuação. Somente através da transdisciplinaridade do grupo que compõe esta Comissão foi possível produzir um texto que respeita todos os setores a que se destina, com a capacidade de atingi-los plenamente nas suas múltiplas linguagens.', '["social determinants of health","health disparities","health policy","health intervention programs","transdisciplinarity","Brazil"]', '10.7476/9788575415917', '9788575415917', 'https://books.scielo.org/id/bwb4z', 'https://books.scielo.org/id/bwb4z/pdf/comissao-9788575415917.pdf', NULL, 'https://books.scielo.org/id/bwb4z/cover/cover_thumbnail.jpeg', NULL, 58, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bww3z', 'bww3z', 'O Codex Cigoli-Galileo: ciência, arte e religião num enigma copernicano', NULL, '["Josie Ágatha Parrilha da Silva","Marcos César Danhoni Neves"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra que se abre aos olhos dos leitores compreende a relação entre a Arte e a Ciência no Renascentismo a partir das relações maduras entre Galileo Galilei (1564-1642) e Lodovico Cardi (1559-1613) conhecido como Cigoli. Compreende uma pesquisa de meio década dessa relação que se inicia a partir da Madonna Assunta pintada num afresco, por Cigoli, na cúpula da capela Paolina na Basílica Papale di Santa Maria em Roma. Três fontes primárias são estudadas: o Sidereus Nuncius, o Istoria e Dimostrazione sulle Macchie Solari e loro Accidenti, de Galileo Galilei, e o Carteggio fra Cigoli e Galileo.', '["Galileo Galilei","art and science","Renaissance","Copernicanism","Sidereus Nuncius","sunspots","science and religion"]', '10.7476/9788576286974', '9788576286424', 'https://books.scielo.org/id/bww3z', NULL, NULL, 'https://books.scielo.org/id/bww3z/cover/cover_thumbnail.jpeg', 429, 35, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bwwtm', 'bwwtm', 'A persistência do aviamento: colonialismo e história indígena no Noroeste Amazônico', NULL, '["Márcio Meira"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro analisa o processo de colonização do Noroeste Amazônico desde a sua gênese, centrado no chamado sistema de aviamento, um dos fatores estruturantes da sociologia dessa região. Tal sistema é caracterizado por trocas comerciais assimétricas baseadas no escambo a crédito, estabelecendo uma relação de dívida e uma rede hierárquica de dominação entre patrões e fregueses. Os indígenas impactados pela persistência do aviamento, entendido como condição colonial, lograram atuar no tempo longo, nas margens do regime de violências, renovando seu antigo sistema social fluido e aberto. Em uma abordagem metodológica interdisciplinar do processo colonial, esta obra estabelece um diálogo entre história e memória.', '["colonialism","indigenous history","Northwest Amazon","debt","clientelism","violence","memory","memory and history"]', '10.7476/9786586768435', '9786586768435', 'https://books.scielo.org/id/bwwtm', 'https://books.scielo.org/id/bwwtm/pdf/meira-9786586768435.pdf', NULL, 'https://books.scielo.org/id/bwwtm/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bx899', 'bx899', 'Democracia, federalismo e centralização no Brasil', NULL, '["Marta Arretche"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As primeiras avaliações após a Constituição de 1988 foram de que a federação brasileira – União, estados e municípios –, operando de forma descentralizada, fortaleceria a democracia. Passada a euforia inicial, emergiram as críticas, segundo as quais essa descentralização poderia, ao contrário, funcionar como um obstáculo à democracia, pois a autonomia de estados e municípios dificultaria ações unificadas, gerando desequilíbrios entre as unidades constituintes. Neste livro, com base em evidências empíricas de longas séries históricas e informações abrangentes, a autora discorda das duas abordagens anteriores e apresenta uma nova leitura: o sistema federativo brasileiro é bastante centralizado, o que não deve ser confundido com ausência de mecanismos de frear a influência do governo central – apesar da forte presença da União, estados e municípios são atores relevantes na formulação e implementação de políticas públicas.', '["federalism","democracy","centralization","Brazilian Constitution of 1988","decentralization","intergovernmental relations","public policy formulation"]', '10.7476/9788575415665', '9788575412985', 'https://books.scielo.org/id/bx899', NULL, NULL, 'https://books.scielo.org/id/bx899/cover/cover_thumbnail.jpeg', 232, 121, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bxgqr', 'bxgqr', 'Gestão Educacional nos municípios: entraves e perspectivas', NULL, '["Maria Couto Cunha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro “Gestão Educacional nos Municípios: entraves e perspectivas", de Maria Couto Cunha foi lançado no dia 18 de junho no Museu Geológico da Bahia. A obra analisa políticas públicas, implantadas na área educacional, nas últimas décadas, principalmente no que se refere à descentralização do ensino. As análises evidenciaram a gênese destas políticas, as forças que engendraram suas formulações, as implantações das mesmas e, em alguns casos, investigaram os impactos produzidos. O foco dos textos reside no desdobramento destas políticas nos governos municipais, registrando uma pesquisa sobre violência escolar e outra sobre a formação de diretores de escolas estaduais.', '["educational management","municipal government","decentralization of education","education policy","school violence","principal training","state schools","policy implementation","Bahia"]', '10.7476/9788523209025', '9788523209025', 'https://books.scielo.org/id/bxgqr', 'https://books.scielo.org/id/bxgqr/pdf/cunha-9788523209025.pdf', NULL, 'https://books.scielo.org/id/bxgqr/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bxj5n', 'bxj5n', 'Gestão sustentável dos recursos naturais: uma abordagem participativa', NULL, '["Waleska Silveira Lira","Gesinaldo Ataíde Cândido"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O livro Gestão sustentável dos recursos naturais: uma abordagem participativa é resultado de um trabalho em conjunto com professores e alunos do programa de pós graduação em desenvolvimento regional - UEPB e de recursos naturais da UFCG, do grupo de pesquisa em gestão do conhecimento e sustentabilidade - GECIS. O livro mostra a importância do gerenciamento dos recursos de uso comum com a participação efetiva dos diversos atores sociais em cada etapa do processo de tomada de decisão.', '["sustainable natural resource management","participatory approach","common-pool resources","stakeholder engagement","decision-making","regional development","sustainability"]', '10.7476/9788578792824', '9788578792824', 'https://books.scielo.org/id/bxj5n', 'https://books.scielo.org/id/bxj5n/pdf/lira-9788578792824.pdf', NULL, 'https://books.scielo.org/id/bxj5n/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bxpm7', 'bxpm7', 'Tramas do sagrado: a poética do sertão de Elomar', 'a poética do sertão de Elomar', '["Simone Guerreiro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Ao investigar a obra poética, musical e operística de Elomar Figueira Mello, este livro mergulha nas complexas “tramas do sagrado” que atravessam a criação do artista sertanejo. A partir do diálogo entre literatura, filosofia e música, a obra analisa as tensões entre o poeta e o homem religioso, explorando os paradoxos, ausências e ambiguidades do sagrado na contemporaneidade. Fundamentado no pensamento de Martin Heidegger e nas reflexões de autores como Friedrich Hölderlin, Walter Benjamin e José Ortega y Gasset, o estudo oferece uma leitura profunda e sensível da poética do sertão de Elomar, revelando uma sofisticada filosofia da linguagem raramente explorada pela crítica contemporânea.', '["sertão","sacred","sertanejo music","Martin Heidegger","Friedrich Hölderlin","Walter Benjamin","José Ortega y Gasset","philosophy of language","religion and literature"]', '10.7476/9786556309736', '9786556307367', 'https://books.scielo.org/id/bxpm7', 'https://books.scielo.org/id/bxpm7/pdf/guerreiro-9786556309736.pdf', NULL, 'https://books.scielo.org/id/bxpm7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bxsqj', 'bxsqj', 'Política e cultura no governo de Dom João VI: imprensa, teatros, academias e bibliotecas (1792-1821)', NULL, '["Juliana Gesuelli Meirelles"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"D. João: personagem fundamental na história luso-brasileira, que em meio às máscaras do cargo e aos poucos vestígios que deixou, fez com que sua personagem fosse, regra geral, uma criação pessoal dos historiadores que forjaram e continuam forjando sua história. Muito já se escreveu sobre o soberano em si mesmo ou acerca de seu governo. No entanto, várias lacunas ainda existem na historiografia sobre seu papel e sua política. Dessa forma, o livro que Juliana Gesuelli Meirelles apresenta ao público contribui para preencher um novo espaço em nossa historiografia acerca de D. João, cuja figura ocupa um lugar especial no imaginário dos brasileiros, como salientou o antropólogo Roberto DaMatta. Jovem historiadora, que há alguns anos trabalha com temáticas que envolvem o período joanino no Brasil, Juliana traz agora um olhar inovador sobre os diversos sentidos da política cultural durante a governança de D. João no mundo luso-brasileiro entre os anos de 1792-1821. Demonstra grande sensibilidade ao analisar, a partir da ótica da ilustração luso-brasileira, as especificidades da política cultural joanina por meio de quatro pontos fundamentais desse conjunto tanto em Lisboa quanto no Rio de Janeiro: a imprensa interatlântica, os Reais teatros, as Reais Academias Militares e as Reais Bibliotecas Públicas da Corte. Dessa forma, traz à luz a ação do Estado monárquico voltada para tais espaços de saber, demonstrando essa política como uma prática governativa da Coroa em sua ação em relação ao todo da sociedade daquela época, com exceção de uma grande parcela da população, ou seja, a dos escravos. No entanto, tal política cultural contribuiu para se apreender as constantes trocas não só entre diferentes segmentos da sociedade, como também entre mundos distintos. Utilizando-se de um rico conjunto de fontes, Juliana consegue, a partir de leituras diversas e de um texto escrito com clareza, mapear o processo de construção da política cultural de D. João, combinando enfoques da história cultural e da nova história política. Por conseguinte, traz ao público leitor, em geral, novas informações e leituras que possibilitam a compreensão de um período histórico que abriu caminhos para a divisão do Império Português e para a construção de um novo Império – o Império Brasílico – em 1822."', '["João VI","cultural policy","press","royal libraries","royal theatre","Royal Academy","Lisbon","Rio de Janeiro","monarchy","18th century","19th century","power and knowledge"]', '10.7476/9788568576878', '9788568576878', 'https://books.scielo.org/id/bxsqj', 'https://books.scielo.org/id/bxsqj/pdf/meirelles-9788568576878.pdf', NULL, 'https://books.scielo.org/id/bxsqj/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-by55h', 'by55h', 'Antropologia da Saúde: traçando identidade e explorando fronteiras', NULL, '["Miriam C. M. Rabelo"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Tem como objetivos definir, problematizar e explorar o potencial da abordagem antropológica às questões relativas a saúde e doença. Ainda que todos os artigos tentem esclarecer e delimitar o campo de atuação da antropologia médica, não apresentam a mesma visão ao tratar das características internas e das fronteiras deste saber. Em alguns, a busca é por desconstruir dicotomias correntes, rumo aos fundamentos metateóricos; em outros, nota-se uma visão complexa do campo a partir da discussão de trabalhos empíricos, etnográficos.', '["medical anthropology","identity","health and disease","ethnography of health"]', '10.7476/9788575414040', '9788575414040', 'https://books.scielo.org/id/by55h', 'https://books.scielo.org/id/by55h/pdf/alves-9788575414040.pdf', NULL, 'https://books.scielo.org/id/by55h/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-by67h', 'by67h', 'Judaísmo para el siglo XXI: el rabino y el sociólogo', NULL, '["Nilton Bonder","Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Vivir en la periferia del sistema no siempre representó una desventaja. El judaísmo de Europa central a fines del siglo XIX e inicios del XX fue uno de los polos culturales más creativos de los tiempos modernos. El problema del judaísmo en América Latina reside en que es doblemente pe-riférico, además de ser de otra época. Al estar localizado en países capitalistas "emergentes", es decir, alejados de la cola pero, todavía, lejos de la cabeza y con comunidades de baja densidad demográfica y cultural y en un ambiente relativamente poco hostil - lo que disminuye las fuerzas centrífugas -, enfrenta el desafío de individualizarse en un universo globalizado en donde los espacios locales son permanentemente colonizados por el mundo exterior.', '["Judaism","rabbinic thought","sociology of religion","globalization","peripheral cultures","Jewish identity","modernity"]', '10.7476/9788599662304', '9788599662304', 'https://books.scielo.org/id/by67h', 'https://books.scielo.org/id/by67h/pdf/bonder-9788599662304.pdf', NULL, 'https://books.scielo.org/id/by67h/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bytpk', 'bytpk', 'Formación en derecho basada en competencias', NULL, '["María Teresa Carreño Bustamante","Isabel Goyes Moreno","Ana Patricia Pabón Mantilla"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra hace referencia a las competencias para la formación de los estudiantes de derecho en Colombia, desde las discusiones que a nivel nacional se suscitan a partir de la evaluación en pruebas saber pro, por la preocupación constante de los programas de derecho hacia la formación de personas íntegras con responsabilidad social; por ello, este libro pretende aportar a dicha discusión, desde la perspectiva de una formación crítica, investigativa y participativa que permita fundamentalmente la consolidación de comunidades académicas jurídicas que dediquen su esfuerzo, no solamente a una formación teórica del estudiante sino también práctica y contextualizada, asegurando la formación de sujetos competentes para las necesidades de este país. Finalmente, pretende proponer alternativas curriculares para la organización de contenidos y ante todo, espacios de interacción con los estudiantes.', '["competency-based education","legal education","law school curriculum","critical pedagogy","participatory learning","social responsibility","curriculum alternatives"]', '10.7476/9789587384772', '9789587384765', 'https://books.scielo.org/id/bytpk', NULL, NULL, 'https://books.scielo.org/id/bytpk/cover/cover_thumbnail.jpeg', 130, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bywgd', 'bywgd', 'O cânone visual: as belas-artes em discurso', NULL, '["Renan Belmonte Mazzola"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O Cânone Visual apresenta uma investigação das belas-artes sob o ponto de vista da teoria do discurso. No campo dos estudos da linguagem, atualmente, o conceito de “discurso” mostra-se complexo e multifacetado: constitui-se de um modo de produzir sentido que se materializa em diversos sistemas de signos, como a língua, as imagens, os gestos, etc. Nesta obra, investiga-se como as artes plásticas estão a serviço dos discursos, ora para reafirmá-los, ora para refutá-los. A partir de Michel Foucault, que refletiu intensivamente sobre a dimensão discursiva que atravessa os textos e as imagens, este livro aprofunda a discussão sobre o sentido do cânone visual ocidental sob as perspectivas teórica, epistemológica e analítica.', '["discourse theory","Michel Foucault","visual arts","sign systems","epistemology of art"]', '10.7476/9788579836718', '9788579836718', 'https://books.scielo.org/id/bywgd', 'https://books.scielo.org/id/bywgd/pdf/mazzola-9788579836718.pdf', NULL, 'https://books.scielo.org/id/bywgd/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bz787', 'bz787', 'Watupari: um testemunho da resistência do povo Yanomami', NULL, '["Marcos A. Pellegrini"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em Watupari, Marcos Pellegrini, médico e antropólogo, narra sua convivência com o povo Yanomami e seu enfrentamento de uma crise humanitária que perdura há décadas. Ao testemunhar o sofrimento gerado por invasões e epidemias, o autor descreve a realidade de um povo que luta pela sobrevivência em meio à destruição de seu território. Trinta anos após sua publicação original, a obra revela, com poesia e relato biográfico, a importância da cultura Yanomami e a urgência de um futuro mais justo e solidário sob o mesmo céu.', '["indigenous peoples","territorial invasion","epidemics","humanitarian crisis","cultural survival","ethnography"]', '10.7476/9786557082287', '9786557081938', 'https://books.scielo.org/id/bz787', 'https://books.scielo.org/id/bz787/pdf/pellegrini-9786557082287.pdf', NULL, 'https://books.scielo.org/id/bz787/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bz97z', 'bz97z', 'A luta da África por sua arte: história de um malogro pós-colonial', NULL, '["Bénédicte Savoy"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é dedicado àquilo que vem sendo reprimido. Ele começa em 1965, com um dos primeiros apelos para a devolução de arte para a África, e termina em 1985, na Ilha dos Museus, na então Berlim Oriental, quando a Nigéria não alinhada estreou com uma exposição de seus tesouros arqueológicos no Museu Pergamon – para, depois de duas décadas de lutas mais tarde, perder toda a esperança de uma restituição. O livro é a primeira tentativa de escrever a história coerente de um malogro pós-colonial com base na profusão de material a respeito espalhado em inúmeros arquivos europeus e publicações africanas. Trata-se de um malogro compartilhado, lembremo-nos, pois a recusa de restituições aos países africanos nas primeiras décadas de sua independência não representou, de forma alguma, um capítulo glorioso da história da Europa. (Da Introdução)', '["restitution of cultural property","African art","postcolonialism","colonial looting","archaeological finds","decolonization"]', '10.7476/9788526816503', '9788526815759', 'https://books.scielo.org/id/bz97z', NULL, NULL, 'https://books.scielo.org/id/bz97z/cover/cover_thumbnail.jpeg', 247, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-bz9vs', 'bz9vs', 'Lógica para principiantes', NULL, '["Pedro Abelardo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra de Abelardo distribui-se em várias direções: teologia sistemática, exegese bíblica, sermões, ética, lógica, sem esquecer a poesia e as cartas. Não seria exagero dizer que ele teve papel de destaque em todos estes setores. No que diz respeito à lógica, Abelardo nos deixou quatro textos: Introductiones dialecticae, Logica "Ingredientibus", Logica "Nostrorum petitione sociorum" e Dialectica. Trata-se do mais importante monumento ligado à chamada "Lógica velha". Este volume, Logica "ingrendientibus", pode ser dividido em três grandes partes. A primeira é constituída por considerações gerais sobre a lógica e a filosofia. A segunda contém um comentário literal da introdução da Isagoge. A terceira, na qual nos deteremos com mais vagar, é justamente uma investigação sobre as perguntas de Porfírio com o objetivo de respondê-las.', '["Peter Abelard","Isagoge","medieval logic","dialectics","scholastic logic","introduction to logic"]', '10.7476/9788539303205', '9788571396289', 'https://books.scielo.org/id/bz9vs', NULL, NULL, 'https://books.scielo.org/id/bz9vs/cover/cover_thumbnail.jpeg', 96, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c2248', 'c2248', 'História da psicologia: pesquisa, formação, ensino', NULL, '["Regina Helena de Freitas"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'instituído por ocasião do VI Simpósio de Pesquisa e Intercâmbio Científico da Associação Nacional de Pesquisa e Pós-graduação em Psicologia, realizado em Teresópolis, Rio de Janeiro, em maio de 1966.A publicação reúne os trabalhos dos primeiros participantes do Grupo, pesquisadores e professores em diversas universidades brasileiras na área da História da Psicologia, e a contribuição do Professor Josef Brožek, da Universidade de Lehigh, EUA, convidado especial dessa primeira reunião.Brožek (1913-2004) foi um dos pioneiros no estabelecimento do ensino e da pesquisa em História da Psicologia nos Estados Unidos, tendo sido co-fundador da Seção 26 da American Psychological Association, dedicada a essa área.Em 1965, junto com Robert Watson, participou da criação do periódico Journal of the History of the Behavioral Sciences, em cujo Conselho Editorial atuou por muitos anos.Com sua extensa experiência, o autor contribuiu com um importante testemunho da evolução dos estudos em História da Psicologia na América do Norte e na Europa, e sobre os métodos e fontes utilizados na pesquisa nessa área.Durante sua estadia entre nós, tivemos ainda a oportunidade de conhecer melhor a encantadora figura humana que ele era, e contar com seu apoio entusiástico ao trabalho de nosso Grupo.A Coletânea foi organizada na forma de um manual de orientação para a pesquisa em História da Psicologia, para uso de professores e estudantes.Na primeira parte, e com base em sugestões e apontamentos do próprio Brožek em curso que lecionou na época a convite da Universidade de São Paulo em Ribeirão Preto, apresentamos três capítulos sobre a pesquisa em História da Psicologia: historiografia, métodos e fontes.A segunda parte traz os relatos da experiência e as reflexões de pesquisadores na área.A terceira parte trata do ensino em História da Psicologia e sua função na formação de pesquisadores e psicólogos.Devemos um agradecimento especial à Professora Maria do Carmo Guedes, da Pontifícia Universidade Católica de São Paulo, por seu papel fundamental na promoção do intercâmbio acadêmico e científico entre pesquisadores interessados na História da Psicologia.Graças a seu esforço de aproximar os pesquisadores, por meio do trabalho do Núcleo de História da Psicologia do Programa de Estudos Pós-graduados em Psicologia Social da PUC-SP, este Grupo se constituiu e prossegue na tarefa de aprofundar e disseminar o interesse pelo conhecimento da evolução desse campo de conhecimento, seja no período pré-científico, seja no período em que a Psicologia atinge o status de ciência.A publicação inicial foi possível pelo empenho das Professoras Elizabeth de Melo Bomfim e Teresinha Feres-Carneiro à frente da ANPEPP no período 1994-1996.A Coletânea foi editada na série Coletâneas da ANPEPP, com o n° 15.Desde então, o Grupo de Trabalho em História da Psicologia da ANPEPP se ampliou, e continua a contribuir para a expansão da área dos estudos históricos em Psicologia em diversas universidades brasileiras.Os colegas do Grupo continuam a explorar caminhos ainda desconhecidos de nossa história, desenvolvendo novas abordagens e conhecimentos sobre os processos de construção dos conceitos e das práticas psicológicas.É nossa convicção que o conhecimento do passado é condição essencial para a melhor orientação das escolhas feitas no presente, e para ampliar as bases da reflexão sobre a condição humana e sobre o papel das reflexões em Psicologia ao longo dessa trajetória.A riqueza e diversidade de leituras possíveis a relevância desse trabalho, que continua a nos desafiar.', '["history of psychology","historiography of psychology","historical sources","history of psychology education","training of psychologists","history of psychology in Brazil"]', '10.7476/9788599662830', '9788599662830', 'https://books.scielo.org/id/c2248', 'https://books.scielo.org/id/c2248/pdf/freitas-9788599662830.pdf', NULL, 'https://books.scielo.org/id/c2248/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c26m8', 'c26m8', 'Camponeses: sua participação no Brasil', NULL, '["Shepard L. Forman"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As experiências pessoais e intelectuais que me levaram a escrever este livro tiveram início há mais de uma década, e se estenderam por toda a minha carreira, desde os tempos de bolsista da “Fulbright” até a etapa acadêmica. Sem dúvida, o argumento central amadureceu nestes últimos anos, da mesma forma que o Brasil, ele próprio, sofreu uma mudança significativa. No entanto, perdura até hoje um conjunto de impressões iniciais. [trecho retirado do prefácio do livro]', '["peasants","rural society","agricultural history","social participation","Brazil"]', '10.7476/9788579820021', '9788579820021', 'https://books.scielo.org/id/c26m8', 'https://books.scielo.org/id/c26m8/pdf/forman-9788579820021.pdf', NULL, 'https://books.scielo.org/id/c26m8/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c29cs', 'c29cs', 'Metamorfoses do Corpo: uma pedagogia Freudiana', NULL, '["Sherrine Maria NJaine Borges"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1996, '1996-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Busca contribuir para ampliar as fronteiras da educação no campo da saúde e o terreno discursivo no qual podem ser pensadas e desdobradas as questões referentes ao processo saúde-doença, entendido em sua dimensão singular de cada sujeito e da verdade de sua história. A contribuição primordial do texto é colocar em xeque as dicotomias ''clínica x saúde coletiva'' e ''indivíduo x sociedade'' na construção da compreensão do fenômeno saúde-doença. Considerando que a posição da psicanálise não poderia ficar de fora de um diálogo com as outras áreas do saber contemporâneo, a autora examina que apoio as contribuições originais e inovadoras de uma pedagogia freudiana podem oferecer à revitalização de um diálogo com uma prática de educação dos homens no campo da saúde.', '["psychoanalysis and education","body","health-disease process","health education","individual and society","subjectivity","history of the subject"]', '10.7476/9788575412718', '9788575412718', 'https://books.scielo.org/id/c29cs', 'https://static.scielo.org/scielobooks/c29cs/pdf/borges-9788575412718.pdf', NULL, 'https://books.scielo.org/id/c29cs/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c2hxb', 'c2hxb', 'A gestão do SUS no âmbito estadual: o caso do Rio de Janeiro', NULL, '["Maria Alicia Domínguez Ugá","Marilene de Castilho Sá","Mônica Silva Martins","Francisco Campos Braga Neto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Antônio Ivo de Carvalho & Regina BodsteinApresentAção Ainda,como evidenciado no quarto capítulo, a realidade atual é paradoxal, dada a penetração de valores democráticos e universalistas na sociedade e, simultaneamente, a permanência de práticas clientelistas que se adaptaram à modernização capitalista vivenciada no país no século XXI se transformando em um dos instrumentos que permitiram essa modernização.Mais ainda, a ampliação do poder local promovida pela descentralização teria reforçado as práticas de uso privado do poder público.Conformando essa realidade paradoxal, podemos destacar, ainda, a possibilidade da convivência dessas práticas do atraso e do baixo desempenho dos serviços de saúde (analisados nos capítulos 10, 11 e 12) com a modernização e o avanço na capacidade regulatória em alguns âmbitos específicos de atuação da esfera estadual -por exemplo, o da vigilância sanitária.Nessa perspectiva, destaca-se então a importância dos estudos de caso para além da compreensão de suas singularidades.Ao tomarmos o Rio de Janeiro como caso para pensar a gestão estadual do sistema de saúde, com seus paradoxos e contradições, avanços e atrasos com relação à consolidação do SUS, o compreendemos como uma metonímia do país, que pode ajudar a pensar outras realidades estaduais no que diz respeito à gestão do sistema de saúde nessa esfera de governo.Uma peculiaridade deste livro é que ele nasceu como iniciativa dos pesquisadores do Departamento de Administração e Planejamento em Saúde (Daps) da Escola Nacional de Saúde Pública Sergio Arouca da Fundação Oswaldo Cruz (Ensp/Fiocruz), que o conceberam coletivamente, ao longo de várias oficinas de trabalho.Entretanto, no processo de seu desenvolvimento, vários capítulos incorporaram a valiosa participação de colegas de outras instituições e departamentos desta Escola, no âmbito da cooperação entre a Secretaria de Saúde e Defesa Civil do Estado do Rio de Janeiro e a referida Escola.Vale mencionar desse modo a pluralidade de abordagens contidas nesta obra: por exemplo, uma mesma questão -a assistência hospitalar -é tratada a partir de métodos quantitativos e qualitativos em capítulos distintos, que denotam olhares completamente diferenciados sobre ela.Assim, em "O pacto federativo brasileiro e o papel do gestor estadual no SUS", Luciana Dias de Lima, Cristiani Vieira Machado, Tatiana Wargas de Faria Baptista e Adelyne Maria Mendes Pereira trazem elementos para a discussão sobre o papel dos estados na política pública de saúde a partir da instituição do SUS, destacando as articulações existentes entre o modelo de intervenção do Estado, o pacto federativo brasileiro e a política setorial.São tratadas as mudanças no papel dos estados no período recente e sua repercussão no Brasil, enfatizando-se as alterações nas macrofunções estatais e suas implicações para a saúde.O capítulo aborda ainda as especificidades das organizações federativas, suas implicações para as políticas de saúde e discute os dilemas do arranjo', '["Unified Health System (SUS)","state health management","Rio de Janeiro state","decentralization","clientelism","health service performance","health regulation","sanitary surveillance","health governance","health care consolidation","hospital care","public health administration"]', '10.7476/9788575415924', '9788575415924', 'https://books.scielo.org/id/c2hxb', 'https://books.scielo.org/id/c2hxb/pdf/uga-9788575415924.pdf', NULL, 'https://books.scielo.org/id/c2hxb/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c2j3b', 'c2j3b', 'Los morlacos y las redes sociales', NULL, '["Torres-Toukoumidis, Ángel","Andrea De Santis-Piras"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'En conmemoración del Bicentenario de Independencia, la Universidad Politécnica Salesiana junto al Grupo de Investigación Gamelab-UPS y la dirección de Carrera de Comunicación -sede Cuenca- presenta la obra “Los morlacos y las redes sociales”, la cual es el resultado de investigación cualitativas y cuantitativas realizadas por estudiantes por estudiantes de segundo ciclo en la asignatura “Investigación de la Comunicación”. Los resultados demuestran que la ciudad de Cuenca y su población está inmersa en el uso de las redes sociales, denotando sus beneficios para la reactivación socieconómica y cultural posterior a la pandemia.', '["social media use","Cuenca","socio-economic recovery","cultural recovery","post-pandemic society","benefits of social media","university student research"]', '10.7476/9789978105771', '9789978105771', 'https://books.scielo.org/id/c2j3b', 'https://books.scielo.org/id/c2j3b/pdf/torres-9789978105771.pdf', NULL, 'https://books.scielo.org/id/c2j3b/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c3h5q', 'c3h5q', 'Facebook e educação: publicar, curtir, compartilhar', NULL, '["Cristiane de Magalhães Porto","Edmea Oliveira dos Santos"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'reflexões acerca do Facebook enquanto espaço de aprendizagem José António Moreira (UAB-PT) Susana Junuário (UAB-PT) 85 Comunidade REA-Brasil no Facebook um espaço de ativismo, autorias, compartilhamentos e inquietações Edméa Santos (PROPED-UERJ) Tatiana Rossini (PROPED-UERJ) 113 Um caso lúdico brincar no Facebook!Alessandra Alcântara (UNIFOR) António Osório (u-Minho-PT) 131 Uma proposta de uso das redes sociais digitais em atividades de ensino e aprendizagem o Facebook como espaço virtual de usos socioeducacionais singulares Cristiane Porto (PPED-UNIT) Edilberto Marcelino da Gama Neto (PPED-UNIT) 149 Ser amigo e ter amigos no Facebook uma análise com crianças Nélia Macedo (Colégio Pedro II -RJ) Rita Ribes (PROPED-UERJ) 167 "Fico sem nada de interessante pra postar qnd estou recatada!a relação entre o espaço eletrônico e o espaço físico em conversas mantidas entre jovens no Facebook Dilton Ribeiro do Couto Junior (PROPED-UERJ) Maria Luiza Oswald (PROPED-UERJ) 185 Facebook conectividade e reflexões da rede social para o contexto social do século XXI Jamile Santinello (UNICENTRO-PR) Andrea Versuti (UFG) 199 Breves comentários sobre a análise de conversações em sites de', '["Facebook","social media in education","virtual learning environments","social networking sites","social activism","online and offline spaces"]', '10.7476/9788578792831', '9788578792831', 'https://books.scielo.org/id/c3h5q', 'https://books.scielo.org/id/c3h5q/pdf/porto-9788578792831.pdf', NULL, 'https://books.scielo.org/id/c3h5q/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c3qn3', 'c3qn3', 'Palmas, a última capital projetada do século XX: uma cidade em busca do tempo', NULL, '["Valéria Cristina Pereira da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Esse livro é mesmo um convite à viagem imaginária que começa por Palmas (TO), mas pode nos levar muito além, em direção a uma cidade em busca do seu tempo, concebida pela autora como construção imaginária, que transforma o espaço urbano em lugar de construção de sentido, criando uma cidade sensibilista. Relações tempo-espaço, compactação temporal, tempo ausente, subjetividade do tempo, polissemia da imagem urbana, semelhanças e diferenças entre Palmas e Brasília, relações (e possibilidades) entre cidade pós-modernista e cidade modernista, proposta de relação entre ciência e arte, entre Geografia e Literatura, transdisciplinaridade... são alguns dos elementos que compõem o livro, expressão do grande desafio teórico-metodológico enfrentado pela autora, que não perde de vista um parâmetro fundamental - as imagens da cidade são os modos de vê-las e vivenciá-las.', '["Palmas","Brasília","imaginary city","urban space","space-time relationship","temporality","sense of place","urban image","modernist city","art and science","geography and literature","transdisciplinarity"]', '10.7476/9788579830921', '9788579830921', 'https://books.scielo.org/id/c3qn3', 'https://books.scielo.org/id/c3qn3/pdf/silva-9788579830921.pdf', NULL, 'https://books.scielo.org/id/c3qn3/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c3tv7', 'c3tv7', 'A epopéia bandeirante: letrados, instituições, invenção histórica (1870-1940)', NULL, '["Antônio Celso Ferreira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Responde a uma complexa indagação: o que é ser paulista? Para isso, estuda a obra dos letrados paulistas entre 1870 e 1940. Relaciona literatura e história, mostrando que os intelectuais do Estado, no período enfocado, buscaram a criação de uma identidade regional. As principais fontes consultadas foram o Almanach Literario de São Paulo e matérias contidas na Revista do Instituto Histórico e Geográfico de São Paulo, além de romances, novelas, contos e outras narrativas. Foram analisados, entre outros autores, Júlio Ribeiro, Valdomiro Silveira, Menotti del Picchia e Guilherme de Almeida.', '["bandeirantes","bandeirismo","regional identity","historical invention","Júlio Ribeiro","history and literature"]', '10.7476/9788539303038', '9788571393868', 'https://books.scielo.org/id/c3tv7', NULL, NULL, 'https://books.scielo.org/id/c3tv7/cover/cover_thumbnail.jpeg', 376, 49, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c46v3', 'c46v3', 'Segurança pública no Brasil: um campo de desafios', NULL, '["Ivone Freire Costa","Ricardo Brisolla Balestreti"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A temática da gestão da segurança constitui um campo de desafios e remete, inicialmente, ao aspecto da construção social desse problema das violências e sua problematizarão sociológica. O livro se propõe a realizar uma reflexão sobre o campo do conhecimento da gestão da segurança pública, sob diversas óticas, agregando-se evidências empíricas e teóricas obtidas através da complementação de dados de pesquisas científicas e de um quadro traçado com as visões de pesquisadores do campo especialmente convidados.', '["public security management","security management","violence","social construction of violence","sociology of violence","security knowledge","Brazil"]', '10.7476/9788523212322', '9788523212322', 'https://books.scielo.org/id/c46v3', 'https://books.scielo.org/id/c46v3/pdf/costa-9788523212322.pdf', NULL, 'https://books.scielo.org/id/c46v3/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c49zf', 'c49zf', 'Termodinâmica da fratura: uma nova abordagem do problema da fratura nos sólidos', NULL, '["João Augusto de Lima Rocha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'A mecânica da fratura é um campo de grande relevância, atestada pela quantidade de abordagens distintas do problema crucial da caracterização do limite último de resistência dos sólidos. Com uma base teórica consistente, este livro inclui ainda a utilização de ferramentas recentes, tais como a Análise de Sensibilidade e o Método dos Elementos de Contorno.', '["fracture mechanics","sensitivity analysis","boundary element method","fracture characterization"]', '10.7476/9788523212353', '9788523212353', 'https://books.scielo.org/id/c49zf', 'https://books.scielo.org/id/c49zf/pdf/rocha-9788523212353.pdf', NULL, 'https://books.scielo.org/id/c49zf/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c4ww5', 'c4ww5', 'O que é saúde?', NULL, '["Naomar de Almeida Filho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Durante muito tempo, a saúde foi entendida simplesmente como o estado de ausência de doença. Considerada insatisfatória, esta definição de saúde foi substituída por outra, que engloba bem-estar físico, mental e social. Embora mais abrangente, o novo conceito não está livre de dificuldades, sobretudo quando se leva em conta a legitimidade dos movimentos que defendem a ‘saúde para todos’. “A partir daí, a sociedade literalmente bate à porta das instituições acadêmicas e científicas que supostamente deveriam saber o que é, como se mede e como se promove ‘essa tal de saúde’”, problematiza o autor, que é professor de Epidemiologia da Universidade Federal da Bahia (Ufba). Ao contrário do que possa parecer à primeira vista, a obra demonstra que a definição de saúde não é trivial e constitui grande lacuna epistemológica no campo da saúde coletiva. Os capítulos retomam os debates filosófico, teórico, metodológico e pragmático sobre saúde, doença e noções correlatas, como vida e qualidade de vida, morte, sofrimento, cuidado e iniquidades.', '["definition of health","health as absence of disease","health for all","well-being","collective health","philosophy of health","disease","quality of life","death","suffering","care","health disparities"]', '10.7476/9788575413432', '9788575413432', 'https://books.scielo.org/id/c4ww5', 'https://books.scielo.org/id/c4ww5/pdf/almeida-9788575413432.pdf', NULL, 'https://books.scielo.org/id/c4ww5/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c54jn', 'c54jn', 'A luta pela terra', NULL, '["Maria Aparecida de Moraes Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'PARADIDÁTICOS - SÉRIE: PODER Obra de rara oportunidade que propicia o conhecimento da realidade dos sem-terra para além da caricatura muitas vezes veiculada pela mídia. Podem ser acompanhadas as chegadas e partidas, venturas e desventuras, os sonhos feitos e desfeitos de personagens típicos desse universo, a partir de seus depoimentos, realizados em acampamentos, barracas de lona preta e assentamentos. Com o objetivo de discutir a questão da posse da terra no Brasil e as novas perspectivas políticas ligadas à questão agrária do país, a autora não perde de vista as raízes históricas do processo, seus matizes e a diversidade de tensões que o modulam.', '["landless workers","agrarian question","land tenure","land struggle","landless movement"]', '10.7476/9788539303212', '9788571395541', 'https://books.scielo.org/id/c54jn', NULL, NULL, 'https://books.scielo.org/id/c54jn/cover/cover_thumbnail.jpeg', 133, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c55xm', 'c55xm', 'Alberto da Veiga Guignard: modernidade e tradição', NULL, '["Taisa Palhares"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Alberto da Veiga Guignard (1896-1962) é reconhecido como um dos mais importantes artistas modernos em atuação no Brasil na primeira metade do século XX. Sua produção se destaca principalmente pelas paisagens montanhosas de tom lírico que aludem às festas juninas e que, no geral, foram interpretadas pela crítica de arte como índice de uma visão pura e ingênua sobre o país. Este estudo pretende investigar as origens da produção artística de Guignard, desde sua formação europeia até o diálogo que estabelece com o meio artístico brasileiro a partir do final dos anos 1920, a fim de ampliar a compreensão do sentido moderno de sua obra.', '["modernist painting","Brazilian modernism","mountain landscape","tradition and modernity","art criticism"]', '10.7476/9788526816428', '9788526815858', 'https://books.scielo.org/id/c55xm', NULL, NULL, 'https://books.scielo.org/id/c55xm/cover/cover_thumbnail.jpeg', 148, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c5bz5', 'c5bz5', 'Ser nobre na Colônia', NULL, '["Maria Beatriz Nizza da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Estudo inédito que percorre quase três séculos de nobreza no Brasil. Destaca as mudanças ocorridas ao longo do processo histórico do país, divididas em três fases: do início da colonização até 1750; do ministério pombalino à chegada da Corte ao Rio de Janeiro; e de 1808 ao movimento constitucionalista. Um retrato fiel da nobreza no Brasil Colônia que revela tanto a complexidade da vida familiar, civil, militar e política, como os esforços da nobreza para manter o seu estilo de vida, a qualquer custo.', '["colonial Brazil","constitutional movement","social history","family life","military nobility","political history","lifestyle"]', '10.7476/9788539303410', '9788571395800', 'https://books.scielo.org/id/c5bz5', NULL, NULL, 'https://books.scielo.org/id/c5bz5/cover/cover_thumbnail.jpeg', 341, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c5nm2', 'c5nm2', 'Políticas e sistema de saúde no Brasil', NULL, '["Lígia Giovanella","Sarah Escorel","Lenaura de Vasconcelos Costa Lobato","José Carvalho de Noronha","Antônio Ivo de Carvalho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Como desconhecer o que é a política de saúde, o que é o Sistema Único de Saúde (SUS), os determinantes sociais, as condições de saúde e as desigualdades do acesso no Brasil? Esta obra consolida o conhecimento crítico sobre o sistema de saúde brasileiro produzido ao longo dos últimos trinta anos. Conhecimento militante na defesa do direito universal à saúde e do acesso aos serviços de um sistema nacional de saúde de qualidade para todos e de políticas de saúde que promovam a redução das desigualdades sociais. Um livro didático e de referência que inclui os eixos de análise individual/coletivo, clínico/epidemiológico e público/privado, além de congregar autores com experiência na gestão de serviços e do próprio sistema, nos três níveis da federação. A construção do SUS há muito deixou de ser obra exclusiva de intelectuais capazes de ler em língua estrangeira. Temos ‘construtores’ que lêem na realidade concreta dos serviços e da gestão, e que participam ativamente do complexo processo de construção cotidiana da saúde.', '["health policy","Unified Health System (SUS)","social determinants of health","health disparities","health care access","social inequality reduction","health services administration","Brazil"]', '10.7476/9788575413494', '9788575413494', 'https://books.scielo.org/id/c5nm2', 'https://books.scielo.org/id/c5nm2/pdf/giovanella-9788575413494.pdf', NULL, 'https://books.scielo.org/id/c5nm2/cover/cover_thumbnail.jpeg', NULL, 164, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c5rn4', 'c5rn4', 'Saúde Global: olhares do presente', NULL, '["Helena Ribeiro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'No âmbito da saúde, evidencia-se a necessidade de novas abordagens que levem em conta a relação do local com o global/universal. Composta por processos muito dinâmicos no tempo e no espaço, e pautada por valores como ética, justiça e solidariedade, a saúde global é um campo com grande potencial de crescimento e cada vez mais atrai a atenção de instituições acadêmicas. Este livro descreve o surgimento desse campo de estudos e apresenta algumas definições do termo saúde global; contextualiza a saúde ambiental global e discute os problemas ecológicos de maior vulto enfrentados pela humanidade; enfoca alguns dos determinantes sociais das doenças não transmissíveis; mostra que as doenças infecciosas ainda constituem questões relevantes e urgentes no âmbito mundial; e aborda algumas questões socioambientais e de saúde transfronteiriças no nosso continente. O livro, portanto, apresenta as bases formadoras da saúde global e busca despertar interesse e vocações para o campo, onde os atores da área da saúde devem atuar em conjunto com as próprias comunidades e com profissionais de outros setores, como direito, agricultura, meio ambiente, engenharia, diplomacia, sociologia, antropologia, geografia e comunicação. “Argumenta-se a favor de compromisso com todos no mundo, em relações não assimétricas, em que o conhecimento e a cultura de todos os povos tenham contribuições válidas, que possam se somar na construção da saúde global, como ciência emergente”, afirma a autora.', '["global health","infectious diseases","socio-environmental health","health care ethics","health justice","solidarity","emerging science","intersectoral collaboration","Latin America"]', '10.7476/9786557080528', '9788575414897', 'https://books.scielo.org/id/c5rn4', NULL, NULL, 'https://books.scielo.org/id/c5rn4/cover/cover_thumbnail.jpeg', 106, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c6dvj', 'c6dvj', 'Trem de ferro e usina do Almada: a física da história da região cacaueira', NULL, '["Adriano Marcus Stuchi","Thais Barbosa dos Santos Moura"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro ganhou 2º lugar no Prêmio ABEU 2022. Pouco conhecidas e mal preservadas, as histórias da estrada de ferro de Ilhéus a Conquista e da usina do Almada são contadas do ponto de vista técnico e científico neste pequeno livro de linguagem simples. A obra despertará o interesse do público em geral, mas é voltada mais especificamente a professores e estudantes das séries finais do ensino fundamental. O texto e as figuras do livro são um convite para o diálogo, a investigação e a busca de novos conhecimentos de caráter interdisciplinar.', '["iron industry","Cauca Valley","history of technology","science education","interdisciplinary teaching","high school students"]', '10.7476/9788574555515', '9786586213331', 'https://books.scielo.org/id/c6dvj', NULL, NULL, 'https://books.scielo.org/id/c6dvj/cover/cover_thumbnail.jpeg', 87, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c6kqr', 'c6kqr', 'Avaliação de políticas urbanas: contexto e perspectiva', NULL, '["Angélica Tanus Benatti Alvim","Luiz Guilherme Rivera de Castro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] A obtenção de resultados consistentes, sustentáveis e legítimos do ponto de vista social tem sido preocupação crescente no âmbito do debate sobre políticas públicas. A obra trata do processo de avaliação de políticas urbanas, enfocando sua formulação, formalização e implementação, bem como as instâncias sociais e os instrumentos para acompanhamento e controle dos resultados.', '["urban policy evaluation","public policy","policy formulation","policy implementation","social environment","social legitimacy"]', '10.7476/9788582930458', '9788582930458', 'https://books.scielo.org/id/c6kqr', NULL, NULL, 'https://books.scielo.org/id/c6kqr/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url)