= CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c8c5v', 'c8c5v', 'Anatomia de uma epidemia: pílulas mágicas, drogas psiquiátricas e o aumento assombroso da doença mental', 'pílulas mágicas, drogas psiquiátricas e o aumento assombroso da doença mental', '["Robert Whitaker"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Livro vencedor George Polk Award for Medical Writing e o Investigative Reporters and Editors Book Award. Livro premiado e traduzido em diversos idiomas, Anatomia de uma Epidemia aborda a controvertida questão das drogas e tratamentos psiquiátricos. O autor foi impulsionado a escrever sobre o que considera “um tremendo campo minado político” a partir de uma reportagem sobre maus-tratos em pesquisas com pacientes psiquiátricos, como, por exemplo, o uso de medicamentos para exacerbar sintomas em esquizofrênicos ou, ao contrário, para privá-los de antipsicóticos. Ao escrever uma série de reportagens sobre esses experimentos, Whitaker estava convencido de que novas drogas psiquiátricas eram desenvolvidas para ajudar a “equilibrar” a química cerebral e que seria antiético retirar a medicação dos pacientes experimentalmente. Ao se aprofundar na questão, no entanto, esbarrou com descobertas da Organização Mundial da Saúde, “que parecia haver encontrado uma associação entre os resultados positivos (no tratamento de esquizofrênicos) e a não utilização contínua desses medicamentos”. A partir daí, dedicou-se a uma “busca intelectual” que originou esta obra. “Estas páginas falam de uma epidemia de doenças mentais incapacitantes induzidas pelos fármacos”.', '["psychiatric medication","antipsychotic drugs","schizophrenia","psychiatric drug trials","pharmaceutical industry","drug safety"]', '10.7476/9786557082324', '9788575414927', 'https://books.scielo.org/id/c8c5v', NULL, NULL, 'https://books.scielo.org/id/c8c5v/cover/cover_thumbnail.jpeg', 421, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c8vkc', 'c8vkc', 'Planejamento e gestão em saúde: caminhos para o fortalecimento das hemorredes', NULL, '["Mariluce Karla Bomfim de Souza"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro traz uma importante reflexão em torno de temas sobre política, planejamento e gestão em saúde, especialmente, aborda sobre a vigilância e a qualidade dos serviços hemoterápicos. Organizada em sete capítulos, a obra analisa desde questões históricas sobre ações de planejamento do Sistema Único de Saúde (SUS) aos seus desafios em proposições voltadas para a Política de Sangue e o fortalecimento da Hemorrede. Debate ainda, sobre as metodologias empregadas nos cursos sobre Planejamento e Gestão em Saúde. Assim, apresenta sobre as experiências da implementação do projeto Planeja Sangue, realizado em 2015, a partir da cooperação entre o Instituto de Saúde Coletiva (ISC) e a coordenação Geral de Sangue e Hemoderivados. Portanto busca contribui com a reflexão de tais políticas buscando inovações para o fortalecimento das Hemorredes estaduais.', '["health planning","health management","blood transfusion services","blood and blood products","health policy","health surveillance","quality of health services","health management training"]', '10.7476/9788523220273', '9788523220273', 'https://books.scielo.org/id/c8vkc', 'https://books.scielo.org/id/c8vkc/pdf/souza-9788523220273.pdf', NULL, 'https://books.scielo.org/id/c8vkc/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c94zn', 'c94zn', 'Dança Cristal: da arte do movimento à abordagem somático-performativa', NULL, '["Ciane Fernandes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro traça o desenvolvimento da Abordagem Somático-Performativa de pesquisa em artes cênicas, a partir de uma perspectiva autobiográfica, simultaneamente acadêmica e poética, analítica e criativa. A abordagem inédita no país, faz parte do terceiro paradigma metodológico, integrando o arcabouço da Prática Artística como Pesquisa, que vem sendo desenvolvido principalmente na Austrália, Escandinávia e Inglaterra, apresentadas na obra num entrelaçamento de criação interartística fundamentada na corporeidade e reflexão teórica transdisciplinar. A Abordagem associa a educação somática e os estudos da performance, fundamentando-se na Análise Laban/Bartenieff de Movimento, no Movimento Autêntico, na dança-teatro e na performance, integrando também questões relativas à improvisação, à dança e diferença (dança inclusiva), à intervenção urbana e à ecoperformance.', '["dance research","somatic education","performance studies","Authentic Movement","dance theatre","improvisation","inclusive dance","urban intervention","artistic research","embodiment","autobiographical research"]', '10.7476/9786556300832', '9788523216986', 'https://books.scielo.org/id/c94zn', NULL, NULL, 'https://books.scielo.org/id/c94zn/cover/cover_thumbnail.jpeg', 228, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c9fb5', 'c9fb5', 'Administración de la innovación', NULL, '["Acevedo Urquiaga, Ana Julia","Suárez Mella, Rogelio"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'El libro se ha elaborado en correspondencia con el syllabus y programa analítico de la materia administración de la innovación, perteneciente al programa de maestría de Desarrollo Local. Su objetivo general se corresponde con el de la asignatura que se plantea para formar en los estudiantes un sistema de conocimientos (saber), habilidades (saber hacer) y valores (saber estar), también denominados competencias, que contribuyan a la solución de problemas empresariales mediante la aplicación de herramientas que permitan diagnosticar y mejorar el nivel de gestión de la innovación en la empresa.', '["innovation management","innovation tools","business problem solving","local development","competencies"]', '10.7476/9786287725157', '9786289526264', 'https://books.scielo.org/id/c9fb5', 'https://books.scielo.org/id/c9fb5/pdf/acevedo-9786287725157.pdf', NULL, 'https://books.scielo.org/id/c9fb5/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c9fjf', 'c9fjf', 'Vigilância alimentar e nutricional para a saúde Indígena', NULL, '["Denise Cavalcante de Barros","Denise Oliveira e Silva","Sílvia Ângela Gugelmin"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A importância da diversidade étnica brasileira e seus desafios são aspectos fundamentais para os profissionais que atuam no campo da saúde indígena. É nesse contexto que se insere o primeiro volume desta publicação. Trata-se de contribuição relevante e inédita ao debate e à consolidação da vigilância alimentar e nutricional no âmbito da saúde indígena. Povos indígenas e o processo saúde-doença; situações e determinantes de saúde e nutrição da população brasileira; sociodiversidade, alimentação e nutrição indígena; políticas públicas e intervenções nutricionais: eis alguns dos temas abordados nesta coletânea, valioso instrumento de reflexão também sobre as potencialidades do Sistema de Vigilância Alimentar e Nutricional (Sisvan) para a prevenção de agravos nutricionais e a promoção da saúde. Já o segundo volume discute a avaliação nutricional de comunidades e indivíduos, em todas as faixas etárias e mesmo na gestação, e destaca as duas faces de um problema: os déficits de crescimento ou subnutrição, de um lado, e o sobrepeso e a obesidade, de outro. Oferece ao leitor as bases para a realização do diagnóstico nutricional na atenção básica; aprofunda o estudo de técnicas e procedimentos usados nas medições antropométricas; destaca como a informação pode orientar ações, reorganizar serviços e melhorar a assistência; e explica as etapas de organização do fluxo de dados, desde a construção até o uso para o planejamento de intervenções, passando pela análise (com ferramentas estatísticas e epidemiológicas) e pela divulgação de resultados.', '["food and nutrition surveillance","Indigenous health","SISVAN","ethnic diversity","public health policy","nutritional assessment","anthropometry","malnutrition","overweight and obesity","health promotion"]', '10.7476/9788575415894', '9788575415894', 'https://books.scielo.org/id/c9fjf', 'https://books.scielo.org/id/c9fjf/pdf/barros-9788575415894.pdf', NULL, 'https://books.scielo.org/id/c9fjf/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-c9tdt', 'c9tdt', 'O catolicismo brasileiro e a construção de identidades negras na contemporaneidade: um olhar sócioantropológico sobre a Pastoral AfroBrasileira', NULL, '["Gabriel dos Santos Filho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Partindo da fronteira entre religião e raça, este livro reflete sobre a construção política e cultural do movimento nacional de negros chamados Agentes de Pastoral Negra (APNs). Discute cultura, etnia e identidade a partir de um olhar interdisciplinar, que abarca desde discussões sobre a cultura afro-brasileira até questões sobre a Igreja Católica do Brasil.', '["Brazilian Catholicism","Black identity","race and religion","Afro-Brazilian culture","Catholic Church","ethnicity"]', '10.7476/9788523211950', '9788523209650', 'https://books.scielo.org/id/c9tdt', NULL, NULL, 'https://books.scielo.org/id/c9tdt/cover/cover_thumbnail.jpeg', 156, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cb', 'cb', 'Formação do professor: a docência universitária em busca de legitimidade', NULL, '["Sandra Regina Soares","María Isabel da Cunha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Formação do professor K essencialmente, das preocupações desses atores, que se centravam na formação para pesquisa e na formação do pesquisador, em sintonia com os critérios de avaliação instituídos.a despeito de algumas repercussões nas suas práticas educativas como docentes da educação superior, mencionadas pelos egressos, a formação da docência universitária, em especial a formação pedagógica, resta, no essencial, ausente.esperamos com esta obra contribuir para visibilidade e fortalecimento da pedagogia universitária, campo de pesquisa, prática e formação, que se interessa pelo processo de ensino e aprendizagem, pelas condições de exercício e saberes da docência e pelas teorias e práticas de formação de professores e estudantes da educação superior. Capítulo 1Formação do professor 13 K Contextualização do estudo a busca da melhoria da qualidade da atuação do professor universitário há muito vem sendo objeto de iniciativas e de estudos esparsos no interior das próprias universidades, porém a discussão mais sistemática sobre a formação dos professores da educação superior emerge com mais força, no cenário internacional, a partir da década de 80 do século XX. insere-se num contexto, simultaneamente, de expansão e de questionamentos relativos ao papel da educação superior e, por conseguinte, da docência universitária.o modelo de docente universitário porta-voz de um saber dogmatizado, capaz de transferir, pelo dom da oratória, em aulas magistrais, seus saberes profissionais, não mais atende as necessidades da sociedade contemporânea.essa perspectiva, baseada na erudição, parece ainda predominar, exigindo, fundamentalmente, o domínio de conteúdos específicos da área de conhecimento, sem a preocupação de conhecer os estudantes e sua cultura, a fim de possibilitar-lhes uma aprendizagem significativa e uma formação profissional voltada para o enfrentamento crítico dos problemas da sociedade.', '["university teacher training","graduate education in education","university pedagogy","political-pedagogical project","university teaching","teacher professional development","pedagogical training","university faculty","teaching quality","student-centered learning","research training"]', '10.7476/9788523211981', '9788523209032', 'https://books.scielo.org/id/cb', 'https://books.scielo.org/id/cb/pdf/soares-9788523211981.pdf', NULL, 'https://books.scielo.org/id/cb/cover/cover_thumbnail.jpeg', NULL, 35, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cbwwq', 'cbwwq', 'Jovens, violência e escola: um desafio contemporâneo', NULL, '["Joyce Mary Adam","Leila Maria Ferreira Salles"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Jacques Pain 1Com a globalização, a violência instalou-se como uma constante intraespecífica da relação humana, para retomar um termo dos especialistas -ou seja, ela é uma especificidade interna à espécie humana.De fato, a globalização alcança os seres humanos, seus problemas, suas diferenças e semelhanças, globalizando também as violências em uma escala refinada e inventiva.Tais violências envolvem-nos em situações que vão dos golpes e feridas resultantes da agressão física até as violências por omissões indiretas, resultado de negligência ou ignorância em relação aos outros.A violência pertence à antropologia humana fundamental, no sentido de que ela ocupa o primeiro plano da humanidade, desde sempre.Basta reler os livros antigos, os textos sacros de várias religiões, particularmente a Bíblia, para dar-se conta de que a violência é uma das dimensões constitutivas da relação humana desde a origem do laço social.Hoje, na generalização dos encontros, da "circulação de bens e pessoas", das questões postas pelas populações humanas (escrevemos assim porque a igualdade é um mito), fica claro que a violência é uma cultura fundamental dessa neo-humanidade globalizada e em via de emergência.A violência política dos sistemas sociais, sob tutela econômica do que alguns chamam hipercapitalismo, ostenta aspectos ao mesmo tempo diferentes e paralelos, como aqueles que dispõem, de um lado, os Estados Unidos ou a Europa e, de outro, a China, a Índia ou o Japão.As grandes tradições comuns que fundam o que era até hoje a humanidade entendem as relações humanas como ligadas à cultura e à violência endêmica dessa relação.Ela ganhou múltiplos aspectos no curso dos séculos precedentes, mas hoje, globalmente mediatizada, sustentada ou reivindicada em termos de guerras de ingerência, de regulação, de política de civilização, essa violência, cultura da força, sob todas suas formas, é claramente o tronco comum da humanidade globalizada.Com efeito, a globalização -e não se trata de entendê-la como algo total ou problematicamente negativo, a não ser no sentido da análise institucional, ou seja, como o negativo de uma fotografia, como parâmetro de análise -tem essa grande virtude de forçar igualmente encontros, trocas, intercâmbios (inclusive assimilações, quase como casamentos) entre civilizações, com', '["youth violence","school violence","globalization","political violence","interpersonal relationships","intercultural dialogue"]', '10.7476/9788579831096', '9788579831096', 'https://books.scielo.org/id/cbwwq', 'https://books.scielo.org/id/cbwwq/pdf/silva-9788579831096.pdf', NULL, 'https://books.scielo.org/id/cbwwq/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cbysw', 'cbysw', 'Machado de Assis – antes do livro, o jornal: suporte, mídia e ficção', NULL, '["Lúcia Granja"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro propõe um novo modo de compreender a história literária no século XIX e a escrita literária de Machado de Assis. Lúcia Granja analisa a Poética da escrita jornalística em Machado de Assis, passando pelas crônicas do Diário do Rio de Janeiro e O Cruzeiro, alguns contos e o romance Memórias Póstumas de Brás Cubas. No hipertexto do periódico cotidiano, a circulação e a hiperligação constantes das formas textuais criaram parâmetros de referencialidade e literaridade deslizantes, que mimetizou e com os quais dialogou a obra de nosso maior escritor. A partir das crônicas, a autora demonstra os procedimentos e os recursos textuais na gênese do narrador machadiano revelado nos romances da fase madura do Bruxo do Cosme Velho.', '["Machado de Assis","journalism","literary poetics","O Cruzeiro","Memórias póstumas de Brás Cubas","Brás Cubas","chronicles","hypermedia","19th-century Brazilian literature","narrator"]', '10.7476/9788595462816', '9788595462816', 'https://books.scielo.org/id/cbysw', 'https://books.scielo.org/id/cbysw/pdf/granja-9788595462816.pdf', NULL, 'https://books.scielo.org/id/cbysw/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cbyx4', 'cbyx4', 'As empresas familiares da cidade de Franca: um estudo sob a visão do serviço social', NULL, '["Maria José de Oliveira Lima"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'O presente estudo teve o objetivo de compreender e explicar o processo de modernização da gestão das empresas familiares da cidade de Franca/SP, levando em consideração as mudanças estruturais advindas e impostas pelo processo de reestruturação produtiva a partir dos anos de 1990. A investigação foi realizada por meio de pesquisas bibliográficas, documental e de campo que, ao longo do processo, permitiram acúmulo de conhecimentos acerca do objeto de estudo e possibilitaram análise e compreensão das formas de atualização da gestão das empresas familiares da cidade de Franca. Essas empresas familiares, parte integrante da amostra do presente estudo, foram criadas em períodos propícios que possibilitaram seu crescimento e desenvolvimento. Na década de 1970, as indústrias orientaram a produção para atender o mercado externo e, durante quase duas décadas, conseguiram alcançar desenvolvimento industrial, considerando o volume significativo das exportações que nos anos 1980 atingiram 35% da produção total. No início da década de 1990, essas organizações empresariais, passaram por momentos de transição diante do processo de globalização, dinâmica e abertura internacional dos mercados incluindo políticas econômicas voltadas à estabilização da economia brasileira. Nesse contexto, as empresas familiares foram obrigadas à reestruturação para atender a realidade dos mercados, na expectativa da oferta de produtos mais sofisticados, com maior qualidade e menor preço. A abertura dos mercados colocou as empresas diante de grandes desafios, uma vez que a estrutura produtiva e organizacional não se encontrava totalmente preparada às exigências internacionais. O empresariado se preocupou com a competitividade e, para isso, foram necessários investimentos, modernização no sentido de busca por maior tecnologia e processos inovadores de organização e...', '["family business","management modernization","productive restructuring","economic stabilization policy","industrial development","Franca, São Paulo","social work perspective"]', '10.7476/9788579830372', '9788579830372', 'https://books.scielo.org/id/cbyx4', 'https://books.scielo.org/id/cbyx4/pdf/lima-9788579830372.pdf', NULL, 'https://books.scielo.org/id/cbyx4/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cc7nk', 'cc7nk', 'Histórias de países imaginários: variedades dos lugares utópicos', NULL, '["Marcos Antônio Lopes","Renato Moscateli"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Conhecer os planos idealizados por algumas das mentes mais criativas do quadro geral das ficções filosóficas, contemplar um bom punhado das mais extravagantes propostas de eugenia social e, de quebra, poder avaliar outro tanto das construções mais sombrias e contrastantes a esses projetos regeneradores – as chamadas distopias -, eis a essência dessas histórias de países imaginários.', '["imaginary country","utopia","dystopia","philosophical fiction","utopian fiction","speculative fiction","imaginary places"]', '10.7476/9788572166485', '9788572166485', 'https://books.scielo.org/id/cc7nk', NULL, NULL, 'https://books.scielo.org/id/cc7nk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ccfq2', 'ccfq2', 'Dialogismo e ironia em São Bernardo, de Graciliano Ramos', NULL, '["Rogério Gustavo Gonçalves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As transformações no discurso do personagem Paulo Honório durante o desenrolar do romance “São Bernardo”, de Graciliano Ramos, é o centro deste estudo, que tenta evidenciar que elas ocorrem concomitantemente às mudanças ocorridas na caracterização psicológica do protagonista. Para desenvolver tal análise, o autor se utiliza das formulações teóricas de Mikhail Bakhtin (1895-1975), para quem a prosa de ficção tem como eixo norteador uma concepção dialógica tanto das ideias quanto da linguagem veiculadas pela narrativa. A partir das definições de Bakhtin, o pesquisador demonstra que o discurso inicialmente convicto e manipulador do protagonista – predominantemente “monológico” – vai se modificando com a crescente interferência da personagem Madalena, o “outro” que porta uma consciência independente e que, aos poucos, acaba tornando o discurso de Paulo Honório, e a própria narrativa do romance, acentuadamente “dialógicos”. O autor identifica os elementos e estratégias discursivas que caracterizam essas duas instâncias no texto, interpretando a interdiscursividade, que se instaura nesse processo de mudança, como uma representação do conflito entre ideologias sociais opostas, que em vários trechos Graciliano trata usando a técnica da ironia, neste caso com forte conotação crítica.', '["Graciliano Ramos","São Bernardo","dialogism","irony","Bakhtin","monologue and dialogue","interdiscursivity","literary characterization","Madalena","Brazilian novel"]', '10.7476/9786557144978', '9786557144978', 'https://books.scielo.org/id/ccfq2', 'https://books.scielo.org/id/ccfq2/pdf/goncalves-9786557144978.pdf', NULL, 'https://books.scielo.org/id/ccfq2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ccq83', 'ccq83', 'Política externa na Nova República: os primeiros 30 anos', NULL, '["Dawisson Belém Lopes"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Este livro é fruto de um investimento sistemático, feito no curso dos últimos seis anos, em uma agenda de pesquisa sobre política externa brasileira na Nova República. Os capítulos estão dispostos em três partes: na primeira, resgatam-se prefigurações sociais e condicionamentos históricos da redemocratização brasileira, do que resultou uma nova política externa, talhada, bem ou mal, para o contexto democrático; na segunda, monitoram-se variáveis de política exterior durante os processos eleitorais da Nova República, bem como a saliência assumida por partidos políticos na confecção dessa política; e, na terceira, abordam-se as inovações institucionais e normativas da diplomacia pátria, da transição de regime político, oficialmente processada em 1985, até os dias correntes. “O livro do professor Belém Lopes coloca-se como um importante trabalho de referência, uma vez que abre a porta para entender como o nacional e o internacional têm interagido para mudar o quadro da política externa brasileira, bem como prepara o terreno para uma séria reconsideração das práticas de produção de políticas e das estruturas institucionais capitaneadas pelo Itamaraty.” (Sean W. Burges)', '["Brazilian foreign policy","redemocratization","democratic transition","electoral process","political parties and foreign policy","Itamaraty"]', '10.7476/9786558580881', '9788542301915', 'https://books.scielo.org/id/ccq83', NULL, NULL, 'https://books.scielo.org/id/ccq83/cover/cover_thumbnail.jpeg', 284, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ccv7z', 'ccv7z', 'Ciência, desenvolvimento e democracia no Brasil: trajetórias, instituições e agendas de pesquisa, 1945-2000', 'trajetórias, instituições e agendas de pesquisa, 1945-2000', '["Freire Junior, Olival","Figueirôa, Silvia","Videira, Antonio Augusto Passos","Lopes, Maria Margaret"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Ciência, Desenvolvimento e Democracia no Brasil: trajetórias, instituições e agendas de pesquisa, 1945-2000 reúne 22 capítulos assinados por pesquisadores de diferentes instituições brasileiras e internacionais para analisar a consolidação da ciência e da tecnologia no Brasil na segunda metade do século XX. A obra aborda temas como políticas científicas, financiamento à pesquisa, universidades, inovação, gênero, diplomacia científica e cooperação internacional, discutindo também os paradoxos do desenvolvimento científico brasileiro durante a ditadura civil-militar.', '["science and technology policy","research funding","universities","innovation","gender","science diplomacy","international research collaboration","military dictatorship","science and democracy","history of science in Brazil"]', '10.7476/9786557083048', '9786557082393', 'https://books.scielo.org/id/ccv7z', NULL, NULL, 'https://books.scielo.org/id/ccv7z/cover/cover_thumbnail.jpeg', 709, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cd2sq', 'cd2sq', 'Ziembinski, o encenador dos tempos modernos: a construção de uma trajetória na crítica de Décio de Almeida Prado (1950-1959)', NULL, '["Camila Maria Bueno Souza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Na primeira metade do século XX o teatro brasileiro passou por um processo de atualização que contou com a liderança de personalidades que marcaram a cultura nacional. Neste complexo cenário de renovação da cena houve a participação do diretor e ator polonês Zbigniew Marian Ziembinski (1908-1978), fugitivo da Segunda Guerra Mundial ele aportou no Brasil, em 1941. O movimento de atualização estética no teatro estava em curso desde a década de 1920 e os esforços de Ziembinski se somaram ao grupo de atores, atrizes, dramaturgos e críticos que desejavam introduzir nos palcos nacionais novas concepções de encenação.', '["theatre criticism","stage direction","Brazilian theatre","modernist drama","Polish émigré theatre"]', '10.7476/9788579837029', '9788579837029', 'https://books.scielo.org/id/cd2sq', 'https://books.scielo.org/id/cd2sq/pdf/souza-9788579837029.pdf', NULL, 'https://books.scielo.org/id/cd2sq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cd98c', 'cd98c', 'A grande imprensa e o PT (1989-2014)', NULL, '["Fernando Antônio Azevedo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] O livro examina e discute a relação da “grande imprensa”, formada pelos três grandes diários de circulação nacional, O Estado de S. Paulo, a Folha de S. Paulo e O Globo, com o petismo a partir da indagação se os jornais atuam de forma paralela ao sistema político, assumindo posições partidárias em disputa. A obra é produto de uma ampla pesquisa e faz uma revisão histórica do comportamento dos jornais nos anos 1950 e 1960, revisa a literatura sobre as coberturas da imprensa na atual quadra democrática e analisa as manchetes e os editoriais dos jornais relacionados ao PT e publicados durantes as campanhas eleitorais presidenciais de 1989 a 2014, abrangendo um período de vinte e cinco anos e sete eleições presidenciais.', '["Partido dos Trabalhadores (PT)","O Estado de S. Paulo","Folha de S. Paulo","O Globo","newspaper editorial positions","newspaper coverage of politics","presidential campaigns","headlines","press and politics","Brazilian democracy"]', '10.7476/9786580216093', '9786580216093', 'https://books.scielo.org/id/cd98c', NULL, NULL, 'https://books.scielo.org/id/cd98c/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cdbjg', 'cdbjg', 'Doença de chagas: manual para experimentação animal', NULL, '["Tânia Cremonini de Araújo-Jorge","Solange Lisboa de Castro"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Edição comemorativa aos noventa anos da descoberta da doença de Chagas, esta obra propicia a estudantes e pesquisadores brasileiros e latino-americanos uma visão global de questões obscuras da relação Trypanosoma cruzi-hospedeiro - para as quais cientistas de todo o mundo ainda buscam respostas, junto com as ferramentas para a investigação da moléstia - em forma de manual para experimentação animal. O objetivo é municiar a nova geração de cientistas com que o Brasil contará neste início de século e milênio. Eles ainda encontrarão cinco milhões de indíviduos chagásicos, sob o risco de morte por cardiopatia, a desafiar sua capacidade de explicar por que alguns desenvolvem a doença enquanto outros equilibram muito bem o convívio na relação parasita-hospedeiro.', '["Chagas disease","Trypanosoma cruzi","host-parasite interactions","animal experimentation","Chagas cardiomyopathy","Chagas disease vectors","Chagas disease epidemiology"]', '10.7476/9788575413937', '9788575413937', 'https://books.scielo.org/id/cdbjg', 'https://books.scielo.org/id/cdbjg/pdf/araujo-9788575413937.pdf', NULL, 'https://books.scielo.org/id/cdbjg/cover/cover_thumbnail.jpeg', NULL, 46, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cdgvt', 'cdgvt', 'Esperança equilibrista: cartografias de sujeitos em sofrimento psíquico', NULL, '["Bernadete Maria Dalmolin"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro analisa os tipos de cuidados que recebem os sofredores psíquicos e suas famílias, usuários de serviços de saúde mental de uma comunidade urbana: o modelo de atenção é padronizador, condicionando e determinando comportamentos e desconsiderando a autonomia e a liberdade como elementos de expressão do sofrimento. Indicado ao Prêmio Jabuti 2007 (1ª fase)', '["psychological suffering","mental health services","family caregivers","models of care","standardization of care","autonomy","freedom","urban communities"]', '10.7476/9788575413210', '9788575410844', 'https://books.scielo.org/id/cdgvt', NULL, NULL, 'https://books.scielo.org/id/cdgvt/cover/cover_thumbnail.jpeg', 216, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cdmjf', 'cdmjf', 'Política de financiamento das universidades estaduais da Bahia: dimensões relevantes à gestão da Universidade Estadual de Feira de Santana (UEFS)', NULL, '["Antônio de Macêdo Mota Júnior"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As universidades estaduais têm sua importância principalmente pela interiorização da oferta pública de educação superior no Brasil e, especialmente, em função do atraso histórico na criação de universidades e da oferta federal limitada às regiões litorâneas. Nesse sentido, o estado da Baia destaca-se com a manutenção de quatro dessas instituições.', '["state universities","Universidade Estadual de Feira de Santana","university administration","public higher education","Bahia","university governance"]', '10.7476/9786589524984', '9786589524984', 'https://books.scielo.org/id/cdmjf', 'https://books.scielo.org/id/cdmjf/pdf/mota-junior-9786589524984.pdf', NULL, 'https://books.scielo.org/id/cdmjf/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cdtqr', 'cdtqr', 'Toxoplasmose adquirida na gestação e congênita: vigilância em saúde, diagnóstico, tratamento e condutas', NULL, '["Regina Mitsuka‐Breganó","Fabiana Maria Ruíz Lopes-Mori","Italmar Teodorico Navarro"]', 'EDUEL', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Immunology and Microbiology', 'Este manual foi concebido com o objetivo de introduzir alguns conceitos, sistematizar os conhecimentos existentes e nortear o Programa de Vigilância em Saúde da Toxoplasmose Congênita no município de Londrina. [...] [trecho retirado da Apresentação do livro]', '["congenital toxoplasmosis","Toxoplasma gondii","diagnosis","treatment","clinical management","Londrina"]', '10.7476/9788572166768', '9788572166768', 'https://books.scielo.org/id/cdtqr', 'https://books.scielo.org/id/cdtqr/pdf/mitsuka-9788572166768.pdf', NULL, 'https://books.scielo.org/id/cdtqr/cover/cover_thumbnail.jpeg', NULL, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cdv3h', 'cdv3h', 'Biodiversidade marinha de Pontal do Paraná', NULL, '["Rocha, Rosana Moreira da","Haddad, Maria Angélica","Maikon Di Domênico"]', 'Sociedade Brasileira de Zoologia', 'Brasil', 'SciELO Books', 'books', 2025, '2025-05-30', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Earth and Planetary Sciences', 'Este livro reúne os resultados do esforço de observações e coletas em diferentes ambientes costeiros do Município de Pontal do Paraná por estudantes de mestrado e doutorado em Zoologia, da Universidade Federal do Paraná. O livro reúne fotos dos animais e plantas encontrados nos seguintes ambientes: praia, costão rochoso, manguezal e estuário. Adicionamos as observações que fizemos sobre as principais características de cada ambiente, sobre os desafios a que os organismos que ali vivem estão submetidos, suas adaptações para vencer esses desafios e seus hábitos de vida. Este livro é uma oportunidade para iniciar estudos de biologia marinha, focando a ecologia de alguns ecossistemas litorâneos com uma linguagem acessível a não especialistas. Trata-se também de um guia de identificação, ao trazer a maioria das espécies identificadas pelo nome comum e nome científico, de modo que o leitor possa fazer a sua própria pesquisa na medida de seu interesse. Termos científicos menos conhecidos foram conceituados em um glossário ao final do livro.', '["marine biodiversity","coastal ecosystems","beaches","rocky shores","mangroves","estuaries","species identification guide","lifestyle habits","marine organisms","Pontal do Paraná"]', '10.7476/9786587590080', '9786587590080', 'https://books.scielo.org/id/cdv3h', 'https://books.scielo.org/id/cdv3h/pdf/rocha-9786587590080.pdf', NULL, 'https://books.scielo.org/id/cdv3h/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cg45q', 'cg45q', 'Prisões e punição: no Brasil contemporâneo', NULL, '["Luiz Cláudio Lourenço","Geder Luiz Rocha Gomes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra tem como objetivo esboçar um panorama sobre as dinâmicas punitivas e as prisões no Brasil contemporâneo, um tema que, de acordo com os organizadores, recebe pouca atenção midiática, ficando, as mazelas que a aplicação da pena de prisão pode causar à sociedade, às margens da discussão pública. Os textos apresentados foram escritos por investigadores com diferentes formações e perspectivas analíticas, o que enriqueceu a análise do sistema prisional brasileiro.', '["prisons","punishment","Brazilian prison system","criminal policy","contemporary Brazil","media coverage of prisons"]', '10.7476/9788523212230', '9788523210236', 'https://books.scielo.org/id/cg45q', NULL, NULL, 'https://books.scielo.org/id/cg45q/cover/cover_thumbnail.jpeg', 411, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cghr3', 'cghr3', 'Partidos e sindicatos: escritos de sociologia política', NULL, '["Leôncio Martins Rodrigues"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne um conjunto de artigos sobre dois temas que tendem a se aproximar: o do partido e o do sindicalismo. O primeiro, “A composição social das lideranças do PT”, foi escrito em março de 1989, e apresentado em abril no Colóquio Franco-Brasileiro de Ciências Sociais realizado em Paris. Esta é sua primeira publicação. O segundo artigo, “Paradoxos do sindicalismo”, foi publicado no Jornal da Tarde, em 5 de outubro de 1985. Apenas uma ou outra correção foi introduzida.', '["political parties","trade unions","Brazilian politics","political sociology"]', '10.7476/9788579820267', '9788579820267', 'https://books.scielo.org/id/cghr3', 'https://books.scielo.org/id/cghr3/pdf/rodrigues-9788579820267.pdf', NULL, 'https://books.scielo.org/id/cghr3/cover/cover_thumbnail.jpeg', NULL, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ch7p7', 'ch7p7', 'Nóis por nóis: poesia e resistência nos saraus periféricos de Salvador', NULL, '["Paulo Sérgio Silva da Paz"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A proposta deste livro é organizar uma leitura dos saraus periféricos de Salvador, a fim de entender como esses espaços se tornaram um campo de ação na trincheira contra um sistema literário-cultural excludente.', '["poetry reading","resistance","Salvador, Bahia","peripheral spaces","popular culture"]', '10.7476/9786588211601', '9786588211441', 'https://books.scielo.org/id/ch7p7', 'https://books.scielo.org/id/ch7p7/pdf/paz-9786588211601.pdf', 'https://books.scielo.org/id/ch7p7/epub/paz-9786588211601.epub', 'https://books.scielo.org/id/ch7p7/cover/cover_thumbnail.jpeg', 221, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cjfmv', 'cjfmv', 'Um peixe olhou pra mim', NULL, '["Tânia Stolze Lima"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro busca restituir as ligações que o cauim apresenta com diferentes aspectos da vida social Yudjá, oferecendo ao mesmo tempo uma análise de um sistema sociocosmológico e um mapa da condição humana. A autora realizou cerca de vinte meses de trabalho de campo etnográfico em aldeias Yudjá (na Terra Indígena Parque Indígena do Xingu, MT) e mais seis meses com famílias Yudjá que se achavam em Brasília, Rio de Janeiro ou Canarana. A substância do material apresentado neste livro foi reunida nos anos de 1984- 1985, 1988-1989 e 1990. O livro é uma versão abreviada, remanejada e parcialmente reescrita da tese de doutorado da autora.', '["traditional medicine","medicinal plants","Xingu Indigenous Park","Amazonian indigenous peoples","ethnobotany","human condition"]', '10.7476/9788539303441', '9788571396227', 'https://books.scielo.org/id/cjfmv', NULL, NULL, 'https://books.scielo.org/id/cjfmv/cover/cover_thumbnail.jpeg', 400, 53, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cjnwk', 'cjnwk', 'Estado e classes sociais na agricultura brasileira', NULL, '["Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[...] nosso estudo focaliza um primeiro ciclo histórico de expansão agroindustrial, caracterizado por estar ligado especialmente a produtos de exportação. Na atualidade, abre-se um novo ciclo de expansão agroindustrial na direção de produtos alimentícios e matérias-primas para o mercado interno.', '["Brazilian agriculture","agroindustrial expansion","agricultural exports","food products","agricultural raw materials","domestic market","agricultural history"]', '10.7476/9788599662281', '9788599662281', 'https://books.scielo.org/id/cjnwk', 'https://books.scielo.org/id/cjnwk/pdf/sorj-9788599662281.pdf', NULL, 'https://books.scielo.org/id/cjnwk/cover/cover_thumbnail.jpeg', NULL, 169, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ck2pg', 'ck2pg', 'Aids na terceira década', NULL, '["Francisco Inácio Bastos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este pequeno volume apresenta uma espécie de cronologia e ‘balanço’ da doença nas três últimas décadas, observando ainda os aspectos sociais e culturais de um fenômeno mundial. Ao apreciar a leitura percebemos que a história da Aids compreende, infelizmente, relatos degradantes de estigmatização e marginalização de pessoas sob risco de contrair/transmitir o HIV ou já vivendo com a infecção. Felizmente, também existem histórias de solidariedade e altruísmo, mobilização social e os avanços de uma ciência praticada com ética e qualidade.', '["AIDS","HIV","history of AIDS","HIV stigma","social mobilization","solidarity"]', '10.7476/9788575413012', '9788575413012', 'https://books.scielo.org/id/ck2pg', 'https://books.scielo.org/id/ck2pg/pdf/bastos-9788575413012.pdf', NULL, 'https://books.scielo.org/id/ck2pg/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ckhzg', 'ckhzg', 'A clínica psicanalítica na contemporaneidade', NULL, '["Carmen Backes"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Os textos que compõem este livro propõem ao leitor uma aproximação ao universo da clínica psicanalítica, do sofrimento psíquico, da forma como ele se apresenta na contemporaneidade. Passados pouco mais de cem anos da inauguração da psicanálise insiste a pergunta sobre quais modificações se operaram, no decorrer deste século – se é que de fato ocorreram –, na forma como é tomado o sofrimento psíquico e qual é hoje o estatuto da direção da cura na psicanálise. A ocupação e a preocupação com afecções dessa ordem na contemporaneidade são o norte que orienta os textos constantes deste livro. O retorno a alguns elementos balizadores (da teoria e da técnica) estabelecidos por Freud e Lacan – entrevistas preliminares, a transferência na clínica com crianças, os avatares da adolescência, a discriminação entre fantasia e fantasma, ato e interpretação – compõe a primeira parte deste livro e revela preocupação com o rigor do trabalho do psicanalista. O psicanalista estuda, opera, reconstrói conceitos quando uma pergunta se funda para ele, a partir de sua prática clínica. É tarefa da psicanálise a escuta do emergente, como também do sofrimento que na cena cotidiana aparece com freqüência. Freud, em sua produção teórica, fala de seu trabalho, de sua pesquisa, de seus impasses na condução da clínica de seu tempo e comprova que esta desarruma, desarticula os conceitos, inclusive os fundamentais. Porém, se a clínica desarruma os conceitos, ela também os renova. Este é o trabalho de pesquisa do psicanalista: construir e reconstruir conceitos a partir daquilo que sua prática clínica cotidiana aporta de novo. Os artigos sobre a direção da cura nas estruturas e quadros clínicos, revisitados à luz dos novos tempos, compõem a segunda parte do livro. As psicopatologias contemporâneas têm gerado discussões nos mais variados âmbitos: desde a área da saúde mais ampla, incluindo o meio médico, como também na mídia e na população em geral. De um lado, estão os laboratórios e o marketing em torno de seus lançamentos; de outro, o sujeito em sofrimento e a constatação de que as doenças também são fruto da modernidade, malgrado os avanços científicos.', '["psychoanalytic clinic","psychological suffering","Sigmund Freud","Jacques Lacan","preliminary interviews","adolescence","psychoanalytic concepts"]', '10.7476/9788538603870', '9788538603870', 'https://books.scielo.org/id/ckhzg', 'https://books.scielo.org/id/ckhzg/pdf/costa-9788538603870.pdf', NULL, 'https://books.scielo.org/id/ckhzg/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ckpg4', 'ckpg4', 'Fumo de Angola: canabis, racismo, resistência cultural e espiritualidade', NULL, '["Edward MacRae","Wagner Coutinho Alves"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Composta por 23 artigos, a obra trata de temas que destacam as inter-relações entre maconha e racismo; religiosidade e xamanismo; maconha como “problema de segurança pública”; etnobotânica; toxicomania; “desbunde e caretice”; cultos afro-brasileiros; autocultivo doméstico; e etnografias sobre áreas culturais diversas: Jamaica, México e Himalaia. A coletânea também aponta a maneira como a proibição da maconha e outras drogas funciona como estratégia de controle político e social sobre segmentos considerados “perigosos” em diferentes momentos da história.', '["cannabis","racism","cultural resistance","spirituality","xamanship","public security","ethnobotany","drug addiction","Afro-Brazilian religions","home cultivation","drug prohibition","political control"]', '10.7476/9788523217334', '9788523215095', 'https://books.scielo.org/id/ckpg4', NULL, NULL, 'https://books.scielo.org/id/ckpg4/cover/cover_thumbnail.jpeg', 565, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ckts9', 'ckts9', 'A etnopesquisa crítica e multirreferencial nas ciências humanas e na educação', NULL, '["Roberto Sidnei Macedo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'São abordadas, neste livro, questões relevantes ao âmbito da pesquisa epistemológica e crítica que tem por foco o saber humano, a ciência genuinamente humana.', '["critical ethnography","epistemology of the human sciences","human knowledge"]', '10.7476/9788523209353', '9788523202149', 'https://books.scielo.org/id/ckts9', NULL, NULL, 'https://books.scielo.org/id/ckts9/cover/cover_thumbnail.jpeg', 297, 53, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ckwyb', 'ckwyb', 'Escola do Meio Ambiente Com Vida', NULL, '["Elizabeth M. dos Santos Schmidt","Eliana Maria Nicolini Gabriel"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'COM VIDAEsta publicação reúne o material desenvolvido na forma de cartilhas destinadas às crianças do primeiro ano do ensino fundamental da rede pública do município de Botucatu (SP) que visitam a Escola do Meio Ambiente (EMA).A EMA está situada em uma área composta por cerrado, floresta estacional semidecidual, mata paludosa e floresta implantada de eucalipto, abrigando nascentes e a represa abastecida pelo ribeirão Lavapés, que atravessa a zona urbana de Botucatu.Trata-se de um local com trilhas destinadas à educação ambiental, onde as crianças têm a oportunidade de aprender sobre a importância de preservar e respeitar a natureza e os animais selvagens.As atividades de ensino ambiental fizeram com que a EMA fosse reconhecida como Escola Associada da Unesco.A partir de investigações realizadas em conjunto com a escola, foram obtidos', '["environmental education","elementary school students","Botucatu","Cerrado","semideciduous seasonal forest","riparian forest","eucalyptus plantations","wildlife conservation","nature trails"]', '10.7476/9788579837579', '9788579837579', 'https://books.scielo.org/id/ckwyb', 'https://books.scielo.org/id/ckwyb/pdf/schmidt-9788579837579.pdf', NULL, 'https://books.scielo.org/id/ckwyb/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cmtpv', 'cmtpv', 'Pele negra, máscaras brancas', NULL, '["Frantz Fanon","Silveira, Renato da"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Examina a negação do racismo contra o negro na França, tendo sua primeira edição, em português, em 1963. É um clássico do pensamento sobre a diáspora africana, sobre a descolonização, a arquitetura psicológica, a teoria das ciências, a filosofia e a literatura caribenha. Analisa o axioma que causou grande turbulência nas décadas de 60 e 70: como a ideologia que ignora a cor pode apoiar o racismo que nega.', '["racism","African diaspora","decolonization","psychological architecture","science and ideology","Caribbean philosophy","Caribbean literature"]', '10.7476/9788523212148', '9788523212148', 'https://books.scielo.org/id/cmtpv', NULL, NULL, 'https://books.scielo.org/id/cmtpv/cover/cover_thumbnail.jpeg', NULL, 482, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cmv7k', 'cmv7k', 'A relação conclusiva na língua portuguesa: funções resumo, conclusão e consequência', NULL, '["Norma Barbosa Novaes Marques","Erotilde Goreti Pezatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra analisa a relação conclusiva expressa por meio das conjunções então e portanto, em dados do português falado nos países lusófonos. Para tanto, utiliza o aparato teórico da Gramática Discursivo-Funcional, modelo que privilegia a intenção comunicativa do falante ao fazer uso do sistema linguístico em situação de interação. A análise revela a existência de três diferentes tipos de relação conclusiva: a Função Resumo (que ocorre entre porções textuais maiores, para sintetizar uma explanação anterior), a Função Conclusão (que relaciona indiretamente duas orações por meio de uma premissa) e a Função Consequência (que relaciona diretamente duas orações, à semelhança de causa-consequência).', '["then","Portuguese language","Discursive-Functional Grammar","causal relationship","discourse relations","conjunctions"]', '10.7476/9788579836992', '9788579836992', 'https://books.scielo.org/id/cmv7k', 'https://books.scielo.org/id/cmv7k/pdf/marques-9788579836992.pdf', NULL, 'https://books.scielo.org/id/cmv7k/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cmwvx', 'cmwvx', 'Wittgenstein e o problema da harmonia entre pensamento e realidade', NULL, '["Antonio Ianni Segatto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra discorre sobre o problema da vinculação entre pensamento (ou linguagem) e realidade tal como ele é formulado e discutido por Ludwig Wittgenstein, especificamente em sua produção filosófica a partir da década de 1930. Antonio Segatto examina o modo como o filósofo concebe aquilo que chamou de “harmonia entre pensamento e realidade” e como enfrenta as questões que giram em torno dela.', '["Wittgenstein","thought and reality","philosophy of language","later Wittgenstein","philosophy of mind"]', '10.7476/9788568334621', '9788568334621', 'https://books.scielo.org/id/cmwvx', 'https://books.scielo.org/id/cmwvx/pdf/segatto-9788568334621.pdf', NULL, 'https://books.scielo.org/id/cmwvx/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cn633', 'cn633', 'Territórios migrantes, interfaces expandidas', NULL, '["Ana Luísa Zaniboni Gomes"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'que apresentamos publicamente mais um título da série Comunicação e Educação, obra produzida graças à frutífera parceria estabelecida entre a Editus, Editora da Universidade Estadual de Santa Cruz (UESC), Ilhéus, BA, e o Grupo de Pesquisa (GP) Comunicação e Educação da Sociedade Brasileira de Estudos Interdisciplinares da Comunicação -Intercom.Comunicação e Educação: territórios migrantes, interfaces expandidas reúne 20 artigos produzidos por pesquisadores, docentes, especialistas e profissionais de distintas formações em áreas do conhecimento mobilizadas por processos comunicativos e educativos e apresentados no XXXX Congresso Brasileiro de Ciências da Comunicação realizado em Curitiba (PR), em 2017.Esta quinta edição está eivada de sentidos.Primeiro porque a obra nasce na passagem dos 40 anos de atuação da Intercom, entidade consolidada no cenário da pesquisa acadêmica nacional e mesmo internacional, reconhecida e respeitada por seus pares -o que é importante e louvável nesse momento histórico político brasileiro em que grande parte das instituições nacionais carece de legitimidade, decência e compromisso com o bem público, inclusive com o bem maior de um povo, que é a sua Educação.Segundo porque a coletânea é resultado de reflexões e discussões que vêm sendo cuidadosamente nutridas, atualizadas e ressignificadas ao longo dessas últimas quatro décadas por docentes e pesquisadores da área, consolidando uma trajetória teórica e metodológica de fôlego e cada vez mais aberta às novas possibilidades de intervenção.E terceiro porque, nessa caminhada, o GP vem se remodelando aos novos desafios investigativos e epistemológicos em função da realidade cada vez mais diversificada dos cenários educativos e comunicativos, especialmente nas salas de aula -presenciais ou ambientes virtuais -, nos recursos didático-pedagógicos e nas novas sociabilidades engendradas por esse atual e dinâmico "espírito do tempo".Ocorre que se formou, assim, um grupo heterogêneo, multitemático', '["communication and education","educational intervention","virtual learning environments","didactic-pedagogical resources","sociability"]', '10.7476/9786586213027', '9786586213027', 'https://books.scielo.org/id/cn633', 'https://books.scielo.org/id/cn633/pdf/nagamini-9786586213027.pdf', NULL, 'https://books.scielo.org/id/cn633/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cnpbk', 'cnpbk', 'Políticas e práticas da educação inclusiva', NULL, '["Ribeiro, Solange Lucas","Duboc, Maria José Oliveira","Souza, Lucimêre Rodrigues de"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os textos aqui apresentados, sob a forma de reflexões, artigos, ensaios, relatos de experiências, cujos autores e autoras sentem-se na responsabilidade de publicizar os resultados de seus estudos e pesquisas, intencionam contribuir para o fortalecimento da Educação Inclusiva, oportunizando que as pessoas com deficiências, ou outras diferenças, possam ocupar os espaços que desejam, sem medo da discriminação, preconceito e em concomitância com a defesa de uma sociedade inclusiva, onde todas as pessoas possam manifestar livremente suas diferenças, divergências e convergências, construindo, desse modo, um projeto coletivo substancial e acolhedor pelo reconhecimento e valorização da diversidade humana.', '["inclusive education","education policy","inclusive practices","people with disabilities","discrimination","prejudice","inclusive society","human diversity"]', '10.7476/9786589524922', '9786589524922', 'https://books.scielo.org/id/cnpbk', 'https://books.scielo.org/id/cnpbk/pdf/ribeiro-9786589524922.pdf', NULL, 'https://books.scielo.org/id/cnpbk/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cpjfq', 'cpjfq', 'Crack: contextos, padrões e propósitos de uso', NULL, '["Edward MacRae","Luiz Alberto Tavares","María Eugenia Núñez"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A partir do resultado de estudos desenvolvidos pelo CETAD/UFBA, o livro desmistifica concepções recorrentes na mídia e na própria Clínica Médica sobre o consumo e o consumidor de drogas, como a de que o crack, pelo seu alto potencial de destruição, levaria o usuário à morte em poucos anos. A proposta do livro é multidisciplinar e envolve áreas como a socioantropologia, psiquiatria, psicologia além do trabalho de redução de riscos e danos com usuários.', '["crack cocaine","drug use","drug users","harm reduction","risk mitigation"]', '10.7476/9788523211714', '9788523211714', 'https://books.scielo.org/id/cpjfq', 'https://books.scielo.org/id/cpjfq/pdf/macrae-9788523211714.pdf', NULL, 'https://books.scielo.org/id/cpjfq/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cq8kr', 'cq8kr', 'As tradições gaúchas e sua racionalização na modernidade tardia', NULL, '["Caroline Kraus Luvizotto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Rio Grande do Sul: cultura e tradições 19 Modernidade e modernidade tardia 53 A (re)invenção da tradição no contexto da modernidade tardia 65 Tradição e ludicidade 81 Preservação e transmissão das tradições 99 Conclusão 129 Referências bibliográficas 135 APRESENTAÇÃO Este livro analisa a racionalização das tradições num contexto de modernidade tardia.O estudo tem como ponto de partida as tradições gaúchas e sua manifestação nos Centros de Tradição Gaúcha (CTG).O estudo foi desenvolvido com base na bibliografia especializada sobre o tema e em uma pesquisa efetuada durante o Encontro de Arte e Tradição Gaúcha (Enart), realizado em 2008 na cidade de Santa Cruz do Sul (RS).Os estudos apontam que a modernidade tardia traz à tona a reflexividade e racionalização das relações, experiências e tradições.Tradições são (re)inventadas e, nesse caso, (re)inventadas tendo o CTG como cenário, e essa (re)invenção permite manter os vínculos e a sociabilidade do grupo sociocultural que se reconhece enquanto grupo e se diferencia dos demais por identificar -se em torno de símbolos, práticas, crenças e rituais que unem seus membros, pois é comum a todos estes, independente do espaço geográfico que ocupem.Na modernidade tardia, o caráter de ludicidade atribuído às tradições (re)inventadas no CTG é o fio condutor para inúmeras relações que se estabelecem nesse cenário e é o combustível de todas as práticas e rituais vivenciados ali.A ludicidade das atividades dá sentido às práticas tradicionalistas e a toda tradição que foi (re)in-12 CAROLINE KRAUS LUVIZOTTO ventada e que passa a ser racionalizada no contexto da modernidade reflexiva.Essa apropriação do caráter lúdico das tradições e as relações estabelecidas no CTG a partir dos símbolos, práticas e rituais sinalizam que estamos vivenciando no Brasil uma situação de modernidade tardia.Nessa situação da modernidade tardia, a tradição racionalizada é uma maneira de evitar choques entre diferentes valores e modos de vida,', '["gaúcho tradition","late modernity","reinvention of tradition","ludicidade","playfulness","sociability","rituals and symbols","traditionalism","Santa Cruz do Sul","reflexive modernity","regional identity"]', '10.7476/9788579830884', '9788579830884', 'https://books.scielo.org/id/cq8kr', 'https://books.scielo.org/id/cq8kr/pdf/luvizotto-9788579830884.pdf', NULL, 'https://books.scielo.org/id/cq8kr/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cqndd', 'cqndd', 'Dança e diferença: cartografia de múltiplos corpos', NULL, '["Matos, Lúcia"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2014, NULL, 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'O livro Dança e diferença: cartografia de múltiplos corpos ganha a sua segunda edição. Com uma apresentação cartográfica que esboça como novas territorializações estéticas vêm sendo tecidas na dança contemporânea, a obra aborda a análise de produtos coreográficos de grupos de dança que possuem em seu elenco dançarinos com os sem deficiência. Além da análise dos trabalhos dos grupos, o livro contém entrevistas com diretores, coreógrafos e elencos. Portanto, evidencia a existência de redes de relações estabelecidas na contemporaneidade através de conceitos chaves como o de corpo, dança contemporânea, diferença e deficiência.', '[]', '10.7476/9788523218164', '9788523217372', 'https://books.scielo.org/id/cqndd', 'https://books.scielo.org/id/cqndd/pdf/matos-9788523218164.pdf', 'https://books.scielo.org/id/cqndd/epub/matos-9788523218164.epub', 'https://books.scielo.org/id/cqndd/cover/cover_thumbnail.jpeg', 206, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cqtc4', 'cqtc4', 'Negritude sem etnicidade: o local e o global nas relações raciais e na produção cultural negra do Brasil', NULL, '["Livio Sansone"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com base em 15 anos de pesquisa na Bahia, no Rio, no Suriname e na Holanda, Livio Sansone indaga sobre as formas específicas que "raça" e etnicidade assumem no Brasil e no resto da América Latina. Ele compara as concepções latino-americanas de "raça" com as concepções dominantes nas ciências sociais, centradas em contextos determinados por identidades branco-negro claramente definidas, formuladas na base da situação dos Estados Unidos e da Europa do Noroeste. Sansone sugere que o estudo de noções de identidade e cultura mais complexas e até "ambíguas", certamente contribui para uma compreensão mais universal das tensões etno-raciais e de por que o pensamento racial continua tão forte. Ele também investiga os efeitos da globalização sobre as diferentes construções da noção de raça.', '["negritude","race","ethnicity","race relations","Black cultural production","racial identity","globalization","Bahia","Rio de Janeiro","Suriname","Brazil"]', '10.7476/9788523211974', '9788523211974', 'https://books.scielo.org/id/cqtc4', 'https://books.scielo.org/id/cqtc4/pdf/sansone-9788523211974.pdf', NULL, 'https://books.scielo.org/id/cqtc4/cover/cover_thumbnail.jpeg', NULL, 56, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-cr2rn', 'cr2rn', 'Políticas do Feminino: saúde, sexo, gênero', NULL, '["Hevelyn Rosa"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'São incontestes as relevantes contribuições que a presente obra traz, sobretudo para o campo da saúde coletiva, tanto do ponto de vista metodológico quanto do ponto de vista teórico-analítico, tornando-se leitura indispensável a quem utiliza as políticas públicas como objeto de estudo. É prodigioso como a autora nos revela seus estranhamentos e busca ampliar as conexões e os agentes numa ampla e ativa teia de significados e produção de sentidos. Seu texto é um convite à reflexão sobre as aparências, as normas instituídas, as possibilidades de subversão dos consensos, a produção de outras realidades e o acolhimento das diferenças. Também é um convite à elaboração de outros horizontes possíveis.', '["femininity","public health policy","sexuality","gender","collective health","public policy","gender norms","meaning production"]', '10.7476/9786557081860', '9786557081853', 'https://books.scielo.org/id/cr2rn', NULL, NULL, 'https://books.scielo.org/id/cr2rn/cover/cover_thumbnail.jpeg', 393, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-crqby', 'crqby', 'Princípios bioclimáticos para o desenho urbano', NULL, '["Marta Adriana Bustos Romero"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O acelerado processo de urbanização, apesar de muitos benefícios para a sociedade, tem permitido que os interesses econômicos na maioria das cidades brasileiras e a falta de considerações ambientais nas decisões morfológicas urbanas venham a criar problemas diversos, dentre os quais está o desconforto térmico dos espaços urbanos. Principalmente nas últimas décadas, temos observado que as cidades brasileiras, em geral, têm se formado e crescido de um modo que tem pouco a ver com o seu contexto climático. Marta preocupa-se com isso e desenvolve os princípios bioclimáticos do planejamento urbano, visando mostrar de que maneira devem ser definidas as morfologias urbano-regionais para atender às exigências de conforto térmico e bem-estar das pessoas, para diferentes condições de clima. E o faz de um modo claro e preciso, adotando uma linguagem facilmente apreendida pelos leitores. Nesse sentido a sua dissertação de mestrado, agora convertida em livro. é uma grande contribuição na área. Deve ser leitura obrigatória por parte de todos aqueles que participam do processo de urbanização e que se preocupam com a qualidade de vida urbana. Inclusive pelos usuários, para que, instrumentalizados com essa nova linguagem, possam conquistar o direito de se ter um ambientesaudável e confortável.', '["urban design","urban morphology","thermal comfort","urban planning","urbanization","Brazilian cities","urban quality of life","healthy urban environments"]', '10.7476/9788523013486', '9788523010904', 'https://books.scielo.org/id/crqby', NULL, NULL, 'https://books.scielo.org/id/crqby/cover/cover_thumbnail.jpeg', 128, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
